INSERT INTO modules (id, title, promise, position, published, updated_at) VALUES ('m1', 'Command Identity', 'Reframe the job: you are a solutions supplier for a programmer''s clock, not a supplicant. Quantify the cost of silence and lock the No-Spam Oath.', 0, 1, strftime('%Y-%m-%dT%H:%M:%SZ','now'))
ON CONFLICT(id) DO UPDATE SET title=excluded.title, promise=excluded.promise, position=excluded.position, updated_at=strftime('%Y-%m-%dT%H:%M:%SZ','now');
INSERT INTO modules (id, title, promise, position, published, updated_at) VALUES ('m2', 'Target Architecture', 'Turn geography, tour dates, and format math into a 20-station war room with a defensible priority score for every row.', 1, 1, strftime('%Y-%m-%dT%H:%M:%SZ','now'))
ON CONFLICT(id) DO UPDATE SET title=excluded.title, promise=excluded.promise, position=excluded.position, updated_at=strftime('%Y-%m-%dT%H:%M:%SZ','now');
INSERT INTO modules (id, title, promise, position, published, updated_at) VALUES ('m3', 'The Pitch System', 'Build the 4-7 word subject line, the 90-word pitch, the one-page EPK, and radio-ready audio — one weapon, one ask.', 2, 1, strftime('%Y-%m-%dT%H:%M:%SZ','now'))
ON CONFLICT(id) DO UPDATE SET title=excluded.title, promise=excluded.promise, position=excluded.position, updated_at=strftime('%Y-%m-%dT%H:%M:%SZ','now');
INSERT INTO modules (id, title, promise, position, published, updated_at) VALUES ('m4', 'The 21-Day Campaign', 'Run the dated 21-day loop: load, fire, watch, follow up with value, exit with grace, log every result.', 3, 1, strftime('%Y-%m-%dT%H:%M:%SZ','now'))
ON CONFLICT(id) DO UPDATE SET title=excluded.title, promise=excluded.promise, position=excluded.position, updated_at=strftime('%Y-%m-%dT%H:%M:%SZ','now');
INSERT INTO modules (id, title, promise, position, published, updated_at) VALUES ('m5', 'Human Frequency', 'Convert replies into relationships: high-value calls, gratitude protocols, burned-well repair, and the ally engine.', 4, 1, strftime('%Y-%m-%dT%H:%M:%SZ','now'))
ON CONFLICT(id) DO UPDATE SET title=excluded.title, promise=excluded.promise, position=excluded.position, updated_at=strftime('%Y-%m-%dT%H:%M:%SZ','now');
INSERT INTO modules (id, title, promise, position, published, updated_at) VALUES ('m6', 'The Compounding Loop', 'Cascade proof into the next market, price your revenue lanes honestly, calendar the next release, and audit every 90 days.', 5, 1, strftime('%Y-%m-%dT%H:%M:%SZ','now'))
ON CONFLICT(id) DO UPDATE SET title=excluded.title, promise=excluded.promise, position=excluded.position, updated_at=strftime('%Y-%m-%dT%H:%M:%SZ','now');
INSERT INTO lessons (id, module_id, code, title, minutes, exercise_minutes, position, published, truth, masterclass_json, field_protocol_json, warnings_json, decoder_json, worksheets_json, community_json, exercise_json, pass_json, tool_links_json, print_asset, version, created_at, updated_at)
       VALUES ('m1l1', 'm1', '1.1', 'The Unheard Tax — What Being Ignored Actually Costs You', 8, 60, 0, 1, 'Every single release cycle without broadcast airplay imposes a compounding tax across your reach, direct revenue, and deal leverage. Silence is not neutral — it is an active expense.', '[{"b":"h","level":3,"spans":[{"t":"text","v":"Strategic Foundation & Operational Reality"}]},{"b":"p","spans":[{"t":"text","v":"Most independent musicians view radio airplay as a speculative luxury or an arbitrary vanity metric. They believe that releasing music directly to digital service providers (DSPs) is sufficient, assuming algorithms will organically discover and elevate their catalog. This is commercial delusion."}]},{"b":"p","spans":[{"t":"text","v":"The digital streaming landscape is an algorithmic silo designed to reinforce existing consumption habits. Terrestrial radio, syndicated satellite broadcasts, and curated non-commercial stations remain the single broadcast medium capable of delivering true "},{"t":"i","v":"passive mass reach"},{"t":"text","v":". When an artist is not in radio rotation, they are paying what we define as the "},{"t":"b","v":"Unheard Tax"},{"t":"text","v":" across three compounding asset channels:"}]},{"b":"list","ordered":true,"items":[{"spans":[{"t":"b","v":"The Passive Reach Deficit:"},{"t":"text","v":" On streaming platforms, a listener must explicitly seek you out or be spoon-fed by an algorithmic playlist among millions of competing tracks. Terrestrial and non-comm radio places your music into cars, workplaces, gyms, and retail spaces where tens of thousands of listeners absorb your sound without prior permission. Zero adds equals zero unsolicited broadcast reach."}]},{"spans":[{"t":"b","v":"The Revenue Bleed:"},{"t":"text","v":" Radio airplay directly triggers high-yield performance royalties via PROs (ASCAP, BMI, SESAC) and SoundExchange digital performance rights. More importantly, terrestrial rotation acts as an authoritative validation stamp that converts local live concert ticket sales, merchandise purchases, and regional brand sponsorships at rates 3x to 5x higher than unverified streaming metrics."}]},{"spans":[{"t":"b","v":"The Leverage Vacuum:"},{"t":"text","v":" When pitching festival talent buyers, commercial booking agencies, sync licensing supervisors, and press editors, raw Spotify stream counts are routinely discounted due to bot farms and payola playlists. Radio station adds provide third-party, FCC-regulated, human-curated proof of listener demand."}]}]},{"b":"h","level":3,"spans":[{"t":"text","v":"Compounding Mathematical Models: The Growth Divergence"}]},{"b":"p","spans":[{"t":"text","v":"The Unheard Tax is not a linear deduction; it is an exponential decay curve. Consider two artists operating over a 12-month timeline:"}]},{"b":"list","ordered":false,"items":[{"spans":[{"t":"b","v":"Artist A (The Algorithmic Hopeful):"},{"t":"text","v":" Relies solely on social posts and playlist pitching. Accumulates modest streams, zero broadcast receipts, and enters Month 12 with identical leverage to Month 1. Every release restarts at ground zero."}]},{"spans":[{"t":"b","v":"Artist B (The Frequency Operator):"},{"t":"text","v":" Executes a disciplined 21-day campaign achieving just one verified station add every two to three weeks. By Month 12, Artist B holds 24 to 36 verified station receipts, rotation upgrades in 6 secondary markets, verifiable PRO royalty statements, and a regional footprint that sells out 300-capacity rooms."}]}]},{"b":"p","spans":[{"t":"text","v":"The spread between Artist A and Artist B is not merely 30 station spins. It is a completely different career valuation, because broadcast proof compounds into booking power, sync clearance, and immediate station re-adds on future singles."}]},{"b":"h","level":3,"spans":[{"t":"text","v":"The Three Structural Enemies of Airplay"}]},{"b":"p","spans":[{"t":"text","v":"To defeat the Unheard Tax, an artist must eliminate three catastrophic operational habits:"}]},{"b":"list","ordered":false,"items":[{"spans":[{"t":"b","v":"Enemy 1: The Comfortable Blast."},{"t":"text","v":" Blasting 2,000 blind BCC emails to generic info@ station inboxes. It feels like high productivity, but it functions as spam, triggers automated server domain blacklists, and permanently poisons your sender reputation."}]},{"spans":[{"t":"b","v":"Enemy 2: The One-and-Done."},{"t":"text","v":" Sending a single polite email, receiving no reply within 48 hours, and concluding that \"radio is dead\" or \"they hated my track.\" Professional programming decisions operate on rigid weekly music meetings and multi-touch evaluation cadences."}]},{"spans":[{"t":"b","v":"Enemy 3: The Prettier Project."},{"t":"text","v":" Delaying campaign execution for six months while endlessly tweaking mix revisions, re-shooting press photos, or redesigning websites. The market rewards speed and deployment over endless private perfectionism."}]}]}]', '[{"b":"p","spans":[{"t":"b","v":"WAR-ROOM DIRECTIVE — 1.1 The Unheard Tax — What Being Ignored Actually Costs You"}]},{"b":"p","spans":[{"t":"b","v":"THE TAX IS A COMPOUND DECAY CURVE — NOT A STATIC LINE"},{"t":"text","v":" The amateur treats radio silence as a neutral holding pattern. In commercial reality, every month without broadcast distribution represents negative compounding. Station program directors cycle out, specialty show rosters fill their annual rotation priorities, and competing regional acts lock down the local champion slots that should belong to you."}]},{"b":"p","spans":[{"t":"b","v":"THE THREE OPERATOR LAWS OF THE AUDIT:"}]},{"b":"list","ordered":true,"items":[{"spans":[{"t":"b","v":"The Audit Number Is an Invoice, Not an Emotion:"},{"t":"text","v":" Print your calculated tax number and affix it above your primary production workstation. When creative fatigue or fear of rejection prompts you to delay outreach, the audit number reminds you that inactivity costs thousands in tangible asset value."}]},{"spans":[{"t":"b","v":"First-Party Leverage Is Non-Transferable:"},{"t":"text","v":" You cannot borrow another artist''s airplay credentials. You must generate your own verifiable receipts within your immediate geographic perimeter before attempting national syndication."}]},{"spans":[{"t":"b","v":"The Unfair Advantage Is Timing:"},{"t":"text","v":" Radio rotation operates on strict seasonal cycles. Launching early in the quarterly ratings book provides exponential advantages over artists who arrive during conservative ratings freeze periods. <!-- WARROOM:END -->"}]}]}]', '[]', '["The mechanic: silence compounds negatively.","The missing piece: the tax isn''t just missed airplay — it''s missed compounding. Every month silent, you lose the receipts that would have made the next month''s pitch stronger.","The operator move: run the tax audit quarterly (not once). The 90-day audit is the tax''s invoice — and a number on paper beats any motivation speech."]', '[{"kind":"note","blocks":[{"b":"p","spans":[{"t":"text","v":"Complete the structured table below as part of your lesson implementation. This worksheet directly replaces legacy spreadsheets with a publication-grade execution protocol."}]}]},{"kind":"table","title":"THE UNHEARD TAX AUDIT SCORECARD","headers":["Asset Channel","Current Baseline","Projected Dominion Output","Annual Opportunity Cost","Corrective Action"],"rows":[["Passive Ear Impressions","0 broadcast spins / mo","45,000 weekly gross listeners","$14,400 equivalent ad spend","Target 20 non-comm / college stations"],["Performance Royalties","$0.00 PRO radio distributions","$1,800 - $4,500 annual distributions","$3,150 uncollected revenue","Register works with PRO + SoundExchange"],["Regional Ticket Sales","30 tickets @ $15 local gate","150 tickets @ $25 supported gate","$9,000 gross gate deficit","Sync airplay push with tour routing"],["Sync & Brand Leverage","0 inbound commercial briefs","3 - 5 vetted pitch submissions","$7,500 licensing opportunity","Deploy broadcast receipts in sync pitches"],["TOTAL ANNUAL TAX","Unquantified Career Friction","Systematic Regional Dominion","$34,050 Tax Payable in Silence","Execute Frequency Dominion 21-Day Cycle"]]}]', '["Post your exact 12-Month Unheard Tax dollar figure. State the raw number with zero defensive rationalizations.","Identify which of the Three Enemies (Comfortable Blast, One-and-Done, Prettier Project) has cost you the most traction over your career.","Describe the single commercial asset (tickets, sync, or royalties) that will change most dramatically once you reach 10 verified station adds.","Verify completion of Drill 4: Confirm that your Proof-Stack directory has been initialized with at least one verifiable historical asset."]', '{"kind":"field-exercise","prompt":"Complete every drill below with real, verifiable answers, then confirm the pass standard.","items":[{"id":"d1","label":"The Financial Tax Audit","description":"The Financial Tax Audit . Calculate your exact Unheard Tax for the preceding 12 months using the Action Worksheet below. Compute lost passive reach, uncollected performance royalties, and unbooked regional ticket revenue.","minutes":20,"type":"response","passStandard":"Complete all worksheet fields with conservative dollar estimates; total tax valuation must exceed $0."},{"id":"d2","label":"The 12-Month Compounding Projection","description":"The 12-Month Compounding Projection . Model two distinct 12-month projections: Pipeline A at 1 add per month (12 annual adds) versus Pipeline B at 1 add per week (52 annual adds). Write a two-sentence executive statement comparing the commercial valuation of both outcomes.","minutes":15,"type":"response","passStandard":null},{"id":"d3","label":"The Three Enemies Elimination Audit","description":"The Three Enemies Elimination Audit . Document one historical instance in your career where you succumbed to the Comfortable Blast, the One-and-Done, or the Prettier Project. Detail the exact corrective protocol you are adopting today.","minutes":10,"type":"response","passStandard":null},{"id":"d4","label":"The First Proof Deposit","description":"The First Proof Deposit . Locate your single strongest existing performance receipt (a press mention, live video snippet, notable playlist inclusion, or local gig flyer) and deposit it into a dedicated local Proof-Stack directory.","minutes":15,"type":"response","passStandard":null}],"worksheets":[{"kind":"table","title":"THE UNHEARD TAX AUDIT SCORECARD","headers":["Asset Channel","Current Baseline","Projected Dominion Output","Annual Opportunity Cost","Corrective Action"],"rows":[["Passive Ear Impressions","0 broadcast spins / mo","45,000 weekly gross listeners","$14,400 equivalent ad spend","Target 20 non-comm / college stations"],["Performance Royalties","$0.00 PRO radio distributions","$1,800 - $4,500 annual distributions","$3,150 uncollected revenue","Register works with PRO + SoundExchange"],["Regional Ticket Sales","30 tickets @ $15 local gate","150 tickets @ $25 supported gate","$9,000 gross gate deficit","Sync airplay push with tour routing"],["Sync & Brand Leverage","0 inbound commercial briefs","3 - 5 vetted pitch submissions","$7,500 licensing opportunity","Deploy broadcast receipts in sync pitches"],["TOTAL ANNUAL TAX","Unquantified Career Friction","Systematic Regional Dominion","$34,050 Tax Payable in Silence","Execute Frequency Dominion 21-Day Cycle"]]}],"confirmations":[{"id":"community","text":"One community drill answered (optional but strengthens calibration).","required":false}]}', '{"policy":"all-responses-min-words","minWords":40,"requireAllDrills":true,"requireWorksheetCells":0,"note":"Complete all worksheet fields with conservative dollar estimates; total tax valuation must exceed $0."}', '[{"to":"/frequency-dominion/app/campaign","label":"Campaign Builder"},{"to":"/frequency-dominion/app/vault","label":"Proof-stack organizer"}]', 'courses/frequency-dominion/frequency-dominion-course.zip', 1, strftime('%Y-%m-%dT%H:%M:%SZ','now'), strftime('%Y-%m-%dT%H:%M:%SZ','now'))
       ON CONFLICT(id) DO UPDATE SET module_id=excluded.module_id, code=excluded.code, title=excluded.title, minutes=excluded.minutes, exercise_minutes=excluded.exercise_minutes, position=excluded.position, truth=excluded.truth, masterclass_json=excluded.masterclass_json, field_protocol_json=excluded.field_protocol_json, warnings_json=excluded.warnings_json, decoder_json=excluded.decoder_json, worksheets_json=excluded.worksheets_json, community_json=excluded.community_json, exercise_json=excluded.exercise_json, pass_json=excluded.pass_json, tool_links_json=excluded.tool_links_json, version=lessons.version+1, updated_at=strftime('%Y-%m-%dT%H:%M:%SZ','now');
INSERT INTO lessons (id, module_id, code, title, minutes, exercise_minutes, position, published, truth, masterclass_json, field_protocol_json, warnings_json, decoder_json, worksheets_json, community_json, exercise_json, pass_json, tool_links_json, print_asset, version, created_at, updated_at)
       VALUES ('m1l2', 'm1', '1.2', 'Station-As-Customer — Radio Is a Market, Not a Favor', 8, 65, 1, 1, 'You are not asking a Program Director for a favor. You are offering a commercial enterprise a precision product that solves their clock, audience retention, and regulatory compliance problems.', '[{"b":"h","level":3,"spans":[{"t":"text","v":"Strategic Foundation & Operational Reality"}]},{"b":"p","spans":[{"t":"text","v":"The fundamental error committed by 98% of independent musicians is approaching radio stations with the posture of a beggar seeking charity. They send emails asking programmers to \"check out my new single\" or \"give an indie artist a shot.\" This language immediately signals amateurism and triggers swift deletion."}]},{"b":"p","spans":[{"t":"text","v":"A radio station is an operating business governed by strict balance sheets, Arbitron/Nielsen ratings data, FCC public-interest mandates, and relentless clock constraints. The Program Director (PD) and Music Director (MD) do not wake up wondering whose artistic feelings they can validate today. Their professional mandate is simple:"}]},{"b":"list","ordered":true,"items":[{"spans":[{"t":"text","v":"Maximize Average Quarter-Hour (AQH) listener retention and cumulative audience (Cume)."}]},{"spans":[{"t":"text","v":"Maintain strict format coherence so listeners do not change the frequency during commercial or programming sweeps."}]},{"spans":[{"t":"text","v":"Fulfill regional/local community programming quotas to protect their FCC broadcast license."}]},{"spans":[{"t":"text","v":"Outperform direct market competitor stations in quarterly ratings books."}]}]},{"b":"p","spans":[{"t":"text","v":"Your song is not an emotional expression; in the eyes of a programmer, it is a "},{"t":"b","v":"commercial SKU"},{"t":"text","v":" entering their inventory. If your SKU fits their clock, matches their tempo architecture, and brings a compelling regional story, it represents an asset. If it violates their format or introduces tuning risk, it is discarded."}]},{"b":"h","level":3,"spans":[{"t":"text","v":"The Five Station Customer Needs"}]},{"b":"p","spans":[{"t":"text","v":"To position your release as an irresistible acquisition, you must address the five core variables every programmer evaluates:"}]},{"b":"list","ordered":false,"items":[{"spans":[{"t":"b","v":"Need 1: Format Integrity:"},{"t":"text","v":" Does your record seamlessly transition between current core playlist charting tracks without causing an abrupt sonic clash? A modern alternative station cannot drop an 8-minute progressive track between 3-minute post-punk singles."}]},{"spans":[{"t":"b","v":"Need 2: The Hourly Clock Grid:"},{"t":"text","v":" Where does your track fit within the station''s broadcast wheel? Is it tailored for a 3:15 morning drive energy burst, a 2:45 specialty indie block, or a late-night deep-cut feature?"}]},{"spans":[{"t":"b","v":"Need 3: Listener Retention Risk:"},{"t":"text","v":" Does the record possess an immediate hook within the first 15 to 20 seconds to prevent commuter scan-button abandonment?"}]},{"spans":[{"t":"b","v":"Need 4: The Local Angle & Community Equity:"},{"t":"text","v":" Why this week, and why from this market? Programmers are hungry for regional relevance—upcoming sold-out club dates, local venue residencies, hometown viral traction, or regional cultural milestones."}]},{"spans":[{"t":"b","v":"Need 5: Third-Party Risk Mitigation:"},{"t":"text","v":" What evidence indicates that other tastemakers or markets have validated this track without audience backlash?"}]}]},{"b":"h","level":3,"spans":[{"t":"text","v":"The Supplier Mindset Shift"}]},{"b":"p","spans":[{"t":"text","v":"Cease acting like an applicant seeking employment. Operate as an agile, reliable B2B content supplier. When communicating with programmers, adopt professional commercial diction:"}]},{"b":"list","ordered":false,"items":[{"spans":[{"t":"i","v":"Amateur approach:"},{"t":"text","v":" \"Hey! I''m an independent artist from Chicago, please listen to my single, it would mean the world to me if you played it!\""}]},{"spans":[{"t":"i","v":"Dominion Operator approach:"},{"t":"text","v":" \"Targeted local add for WXRT evening specialty rotation: 3:08 run-time, 122 BPM guitar hook, currently supporting upcoming sold-out Metro Chicago showcase on the 18th. Clean broadcast WAV and 30s hook cut attached.\""}]}]},{"b":"p","spans":[{"t":"text","v":"Programmers respect clarity, precision, and technical competence. When you make their curation job effortless, you jump to the top 2% of their consideration pile."}]}]', '[{"b":"p","spans":[{"t":"b","v":"WAR-ROOM DIRECTIVE — 1.2 Station-As-Customer — Radio Is a Market, Not a Favor"}]},{"b":"p","spans":[{"t":"b","v":"RADIO DIRECTORS ARE RISK MANAGERS, NOT TALENT SCOUTS"},{"t":"text","v":" When a commercial or AAA station adds an unproven song, the programmer puts their personal reputation and their station''s quarterly ratings at risk. A sudden quarter-hour drop in Arbitron / Nielsen ratings directly threatens station advertising CPM rates and the programmer''s employment security."}]},{"b":"p","spans":[{"t":"b","v":"HOW TO LOWER THE PROGRAMMER''S PERCEIVED RISK:"}]},{"b":"list","ordered":true,"items":[{"spans":[{"t":"b","v":"Clock Compliance Over Egotism:"},{"t":"text","v":" Never submit songs with 45-second ambient synth intros. Radio programmers live on the \"15-Second Rule.\" If a vocal or undeniable rhythmic motif does not establish itself within 15 seconds, a commuter presses the preset button. Provide a tailored Radio Edit that commands attention instantly."}]},{"spans":[{"t":"b","v":"Metadata Perfection as a Competence Signal:"},{"t":"text","v":" If your file name is "},{"t":"code","v":"Final_Mix_V4_Master_uncompressed.wav"},{"t":"text","v":", you are instantly flagged as an amateur. Your asset delivery must be tagged: "},{"t":"code","v":"ArtistName_TrackTitle_RadioEdit_Clean_120BPM.wav"},{"t":"text","v":" with complete ID3 broadcast tags."}]},{"spans":[{"t":"b","v":"The Tuesday Morning Rhythm:"},{"t":"text","v":" Major music meetings take place on Monday afternoon and Tuesday morning. Submissions sent on Friday evening die under weekend inbox pileups. Deliver your payload when the programmer is compiling their candidate list. <!-- WARROOM:END -->"}]}]}]', '["The Program Director (PD) and Music Director (MD) do not wake up wondering whose artistic feelings they can validate today.","Maintain strict format coherence so listeners do not change the frequency during commercial or programming sweeps. 3.","Clock Compliance Over Egotism: Never submit songs with 45-second ambient synth intros."]', '["The mechanic: the PD''s yes is a ratings bet, not a taste vote.","The missing piece: the real customer is the format, and the format''s needs change by daypart — the same record can fit a 7pm specialty block and fail a 9am power hour.","The operator move: ask the format question on every call (\"what does a new record need to fit here?\") and mirror the PD''s wording in the next pitch. Their language is the acceptance criteria."]', '[{"kind":"note","blocks":[{"b":"p","spans":[{"t":"text","v":"Complete the structured table below as part of your lesson implementation. This worksheet directly replaces legacy spreadsheets with a publication-grade execution protocol."}]}]},{"kind":"table","title":"STATION BENCHMARK COMPLIANCE MATRIX","headers":["Benchmark Element","Station Track A (Core)","Station Track B (Add)","Your Song Submission","Format Variance / Fix Required"],"rows":[["BPM & Tempo Curve","118 BPM mid-tempo drive","124 BPM upbeat hook","120 BPM driving groove","Zero variance — direct tempo match"],["Total Run-Time","3 minutes 12 seconds","2 minutes 54 seconds","3 minutes 06 seconds","Within optimal < 3:20 radio clock limit"],["Vocal Entry Timestamp","0:08 immediate vocal","0:04 drum pickup + verse","0:09 vocal hook entrance","Compliant — no drawn-out intro"],["Explicit Content","FCC Clean broadcast edit","FCC Clean broadcast edit","Uncensored master file","ACTION: Bounce dedicated FCC Clean WAV edit"],["Local / Story Hook","National label priority","Regional touring act","Hometown venue headliner","Emphasize upcoming 250-cap club date"]]}]', '["Share your rewritten 20-word Supplier Value Statement. Critique peer statements for hidden begging language.","Post the results of your Station Benchmark Matrix for your #1 target station.","What specific operational friction (e.g., long intro, unclean lyrics, missing metadata) did you discover in your existing packaging during today''s drills?","Identify the chief commercial competitor of your target station. Explain how your song helps them counter-program that competitor."]', '{"kind":"field-exercise","prompt":"Complete every drill below with real, verifiable answers, then confirm the pass standard.","items":[{"id":"d1","label":"The PD Job Description Dossier","description":"The PD Job Description Dossier . Draft an objective, three-point job description for the Music Director of your primary target station. Detail their ratings pressures, weekly rotation quotas, and commercial competitors.","minutes":15,"type":"response","passStandard":null},{"id":"d2","label":"The Station Benchmark Matrix","description":"The Station Benchmark Matrix . Analyze three consecutive tracks recently added to daytime rotation at your target station. Complete the Benchmark Grid below, charting BPM, run-time, vocal entry point, and lyrical themes.","minutes":25,"type":"response","passStandard":null},{"id":"d3","label":"The 20-Word Supplier Value Statement","description":"The 20-Word Supplier Value Statement . Write a single 20-word sentence framing your track strictly as a programming solution for that specific daypart. Zero emotional or begging adjectives allowed.","minutes":10,"type":"response","passStandard":null},{"id":"d4","label":"The Pitch De-Begging Sweep","description":"The Pitch De-Begging Sweep . Review your three most recent email pitches. Highlight and permanently strike every supplicant word (''please'', ''hope you like'', ''give me a chance'', ''independent artist''). Replace each with operational supplier language.","minutes":15,"type":"response","passStandard":null}],"worksheets":[{"kind":"table","title":"STATION BENCHMARK COMPLIANCE MATRIX","headers":["Benchmark Element","Station Track A (Core)","Station Track B (Add)","Your Song Submission","Format Variance / Fix Required"],"rows":[["BPM & Tempo Curve","118 BPM mid-tempo drive","124 BPM upbeat hook","120 BPM driving groove","Zero variance — direct tempo match"],["Total Run-Time","3 minutes 12 seconds","2 minutes 54 seconds","3 minutes 06 seconds","Within optimal < 3:20 radio clock limit"],["Vocal Entry Timestamp","0:08 immediate vocal","0:04 drum pickup + verse","0:09 vocal hook entrance","Compliant — no drawn-out intro"],["Explicit Content","FCC Clean broadcast edit","FCC Clean broadcast edit","Uncensored master file","ACTION: Bounce dedicated FCC Clean WAV edit"],["Local / Story Hook","National label priority","Regional touring act","Hometown venue headliner","Emphasize upcoming 250-cap club date"]]}],"confirmations":[{"id":"community","text":"One community drill answered (optional but strengthens calibration).","required":false}]}', '{"policy":"all-responses-min-words","minWords":40,"requireAllDrills":true,"requireWorksheetCells":0,"note":""}', '[{"to":"/frequency-dominion/app/campaign","label":"Campaign Builder"},{"to":"/frequency-dominion/app/vault","label":"Proof-stack organizer"}]', 'courses/frequency-dominion/frequency-dominion-course.zip', 1, strftime('%Y-%m-%dT%H:%M:%SZ','now'), strftime('%Y-%m-%dT%H:%M:%SZ','now'))
       ON CONFLICT(id) DO UPDATE SET module_id=excluded.module_id, code=excluded.code, title=excluded.title, minutes=excluded.minutes, exercise_minutes=excluded.exercise_minutes, position=excluded.position, truth=excluded.truth, masterclass_json=excluded.masterclass_json, field_protocol_json=excluded.field_protocol_json, warnings_json=excluded.warnings_json, decoder_json=excluded.decoder_json, worksheets_json=excluded.worksheets_json, community_json=excluded.community_json, exercise_json=excluded.exercise_json, pass_json=excluded.pass_json, tool_links_json=excluded.tool_links_json, version=lessons.version+1, updated_at=strftime('%Y-%m-%dT%H:%M:%SZ','now');
INSERT INTO lessons (id, module_id, code, title, minutes, exercise_minutes, position, published, truth, masterclass_json, field_protocol_json, warnings_json, decoder_json, worksheets_json, community_json, exercise_json, pass_json, tool_links_json, print_asset, version, created_at, updated_at)
       VALUES ('m1l3', 'm1', '1.3', 'The Proof Stack — Build the Evidence Vault That Makes PDs Say Yes', 8, 95, 2, 1, 'Nobody risks airtime on enthusiasm. The Proof Stack is your third-party credibility vault — transforming subjective musical taste into undeniable objective evidence.', '[{"b":"h","level":3,"spans":[{"t":"text","v":"Strategic Foundation & Operational Reality"}]},{"b":"p","spans":[{"t":"text","v":"When a music programmer opens your submission, they apply a subconscious heuristic: "},{"t":"i","v":"\"Can I justify playing this record to my General Manager, my consulting network, and my listeners if it fails?\""}]},{"b":"p","spans":[{"t":"text","v":"If your pitch relies exclusively on your personal conviction—"},{"t":"i","v":"\"This is my best song yet, you will love it\""},{"t":"text","v":"—the programmer bears 100% of the downside risk. But when your pitch cites verifiable third-party receipts—"},{"t":"i","v":"\"Already spinning on KEXP night rotation, 15,000 regional Shazams in target metro, headlined Bowery Ballroom with 400 tickets sold\""},{"t":"text","v":"—the risk transfers from the programmer to the objective market evidence."}]},{"b":"p","spans":[{"t":"text","v":"This is the purpose of the "},{"t":"b","v":"Proof Stack"},{"t":"text","v":". You do not build a career on potential; potential is an empty promise. You build dominion on "},{"t":"i","v":"receipts"},{"t":"text","v":". Every review, spin, sold-out gig, playlist inclusion, editorial quote, and industry endorsement is a negotiable asset."}]},{"b":"h","level":3,"spans":[{"t":"text","v":"The Five Tiers of Proof Architecture"}]},{"b":"p","spans":[{"t":"text","v":"Screeners and programmers evaluate evidence through a rigid credibility hierarchy:"}]},{"b":"list","ordered":false,"items":[{"spans":[{"t":"b","v":"S-Tier (Institutional Authority):"},{"t":"text","v":" Terrestrial broadcast adds on recognized non-comm / AAA / college flagships (e.g., KEXP, KCRW, WXPN, The Current), charting positions on NACC Top 200 or Americana Singles Charts, and verified sync placements in major film/TV. An S-tier receipt virtually guarantees a listening evaluation."}]},{"spans":[{"t":"b","v":"A-Tier (Market Momentum):"},{"t":"text","v":" Verifiable live concert ticket sales in the target station''s metro (minimum 150+ tickets), regional press coverage from respected publications, and verified high-engagement editorial playlist inclusions."}]},{"spans":[{"t":"b","v":"B-Tier (Digital Traction):"},{"t":"text","v":" Organic algorithmic streaming spikes, localized Shazam clustering in specific zip codes, and clean social video traction with high comment-to-view ratios."}]},{"spans":[{"t":"b","v":"C-Tier (Ambient Signal):"},{"t":"text","v":" Local blog features, amateur podcast interviews, and general follower counts. These provide minor color but never lead a serious broadcast pitch."}]},{"spans":[{"t":"b","v":"D-Tier (Anti-Proof — Eliminate Immediately):"},{"t":"text","v":" Pay-to-play blog placements, botted Spotify playlist placements, purchased social follower spikes, and screenshots of mom or friends saying the song is a smash. Programmers spot fabricated traction in 3 seconds."}]}]},{"b":"h","level":3,"spans":[{"t":"text","v":"Assembling the Four-Line Pitch Proof Stack"}]},{"b":"p","spans":[{"t":"text","v":"In your direct communications, you will never overwhelm a gatekeeper with a 10-page press kit. You will distill your strongest evidence into a razor-sharp "},{"t":"b","v":"Four-Line Proof Stack"},{"t":"text","v":":"}]},{"b":"list","ordered":true,"items":[{"spans":[{"t":"i","v":"Line 1 (Broadcast / Institutional):"},{"t":"text","v":" \"Spinning in rotation on WXPN & KUTX specialty blocks.\""}]},{"spans":[{"t":"i","v":"Line 2 (Live / Regional Ground Game):"},{"t":"text","v":" \"280 tickets sold at Metro Chicago; upcoming Lincoln Hall date.\""}]},{"spans":[{"t":"i","v":"Line 3 (Traction / Metric Velocity):"},{"t":"text","v":" \"1,200 regional Shazams centered in Cook County over 14 days.\""}]},{"spans":[{"t":"i","v":"Line 4 (Critical Validation):"},{"t":"text","v":" \"''A blistering return to Midwest indie rock'' — Chicago Reader.\""}]}]},{"b":"p","spans":[{"t":"text","v":"If you currently lack S-Tier broadcast receipts, you do not despair. You harvest what you currently possess—live ticket numbers, local press, hometown support—and use those receipts to secure your first college add. That college add becomes the S-Tier receipt that unlocks regional commercial specialty shows."}]}]', '[{"b":"p","spans":[{"t":"b","v":"WAR-ROOM DIRECTIVE — 1.3 The Proof Stack — Build the Evidence Vault That Makes PDs Say Yes"}]},{"b":"p","spans":[{"t":"b","v":"PROOF IS MARKET-WEIGHTED: THE HYPER-LOCAL RECEIPT PRINCIPLE"},{"t":"text","v":" The most common mistake artists make when pitching regional stations is citing national or disconnected international metrics. If you are pitching a Seattle station (such as KEXP), 500 local Seattle ticket buyers or 50 spins on a neighboring Washington college station (like KUGS in Bellingham) carries 10x more psychological weight than 500,000 passive streams in Germany."}]},{"b":"p","spans":[{"t":"b","v":"THE PROOF ACCELERATION LADDER:"}]},{"b":"list","ordered":true,"items":[{"spans":[{"t":"b","v":"The College Foothold:"},{"t":"text","v":" College and community radio stations (Class D and non-comm educational) do not operate under commercial ratings terror. They exist to curate adventurous new sounds. Securing adds on three regional college stations provides the verifiable broadcast proof needed to approach secondary commercial stations."}]},{"spans":[{"t":"b","v":"The Spinitron Paper Trail:"},{"t":"text","v":" Always track station play logs via Spinitron or station online playlists. Take clean, timestamped screenshots showing your artist name and song title in the official log. A screenshot of an official log is unassailable proof."}]},{"spans":[{"t":"b","v":"Never Lead with Social Follower Counts:"},{"t":"text","v":" Music directors know follower counts are frequently bought or passive. Lead with verified engagement, physical attendance, and broadcast rotation. <!-- WARROOM:END -->"}]}]}]', '["You do not build a career on potential; potential is an empty promise.","Programmers spot fabricated traction in 3 seconds. ### Assembling the Four-Line Pitch Proof Stack In your direct communications, you will never overwhelm a gatekeeper with a 10-page press kit.","Line 4 (Critical Validation): \"''A blistering return to Midwest indie rock'' — Chicago Reader.\" If you currently lack S-Tier broadcast receipts, you do not despair."]', '["The mechanic: third-party evidence transfers risk.","The missing piece: proof is market-weighted — a spin in the target''s metro outranks 100k global streams.","The operator move: tag every receipt with a market and build per-market proof shelves. The Boston pitch never shows Austin receipts. It sounds obvious; almost nobody does it."]', '[{"kind":"note","blocks":[{"b":"p","spans":[{"t":"text","v":"Complete the structured table below as part of your lesson implementation. This worksheet directly replaces legacy spreadsheets with a publication-grade execution protocol."}]}]},{"kind":"table","title":"PROOF STACK INVENTORY & CREDIBILITY CLASSIFIER","headers":["Receipt Description","Proof Tier","Date Verified","Source / Authority","Strategic Deployment Context"],"rows":[["Station add on WNUR 89.3 FM (Chicago)","S-Tier (Broadcast)","Current Quarter","Station Airplay Log / Spinitron","Lead proof point for regional Midwest college push"],["220 tickets sold @ Thalia Hall showcase","A-Tier (Live Market)","Last Month","Ticketmaster / Eventbrite statement","Cite in tour-corridor pitches to Milwaukee/Detroit"],["2,400 organic Spotify saves within 21 days","B-Tier (Traction)","Current Cycle","Spotify for Artists Analytics","Demonstrate listener retention in follow-up emails"],["Featured review in Under The Radar","A-Tier (Press)","Two Months Ago","Editorial Column Link","Quote one sharp sentence in EPK header block"],["Upcoming supporting slot for national act","A-Tier (Co-Sign)","Confirmed Date","Official Venue Announce Poster","Create urgent time-stamped news hook for pitch"]]}]', '["Post your Four-Line Proof Stack for peer review. Group members will grade it for punch, credibility, and fluff.","Share the single strongest receipt you uncovered during your excavation drill.","What specific 7-day action are you taking this week to manufacture your next S-Tier or A-Tier proof receipt?","Identify an anti-proof phrase you previously used in pitches that you have permanently retired today."]', '{"kind":"field-exercise","prompt":"Complete every drill below with real, verifiable answers, then confirm the pass standard.","items":[{"id":"d1","label":"The Deep Receipt Excavation","description":"The Deep Receipt Excavation . Mine your email history, ticketing accounts, DSP analytics, and press archives. Extract at least 10 concrete proof receipts and classify them using the Proof Stack Inventory below.","minutes":45,"type":"response","passStandard":null},{"id":"d2","label":"The Four-Line Proof Stack Construction","description":"The Four-Line Proof Stack Construction . Assemble your best four lines of proof. Ensure each line represents a distinct proof vector (institutional, live, velocity, press).","minutes":20,"type":"response","passStandard":null},{"id":"d3","label":"Anti-Proof Scrubbing Protocol","description":"Anti-Proof Scrubbing Protocol . Review your EPK, social bios, and pitch drafts. Ruthlessly delete every vague, unprovable claim (''buzzing artist'', ''taking the city by storm'', ''next big thing'') and replace with documented facts.","minutes":15,"type":"response","passStandard":null},{"id":"d4","label":"The 7-Day Proof Manufacture Mission","description":"The 7-Day Proof Manufacture Mission . Identify your single weakest proof tier. Schedule one tangible operational action within the next 7 days to manufacture a legitimate receipt (e.g., booking a specific venue date, submitting to college press, pitching a local specialty DJ).","minutes":15,"type":"response","passStandard":null}],"worksheets":[{"kind":"table","title":"PROOF STACK INVENTORY & CREDIBILITY CLASSIFIER","headers":["Receipt Description","Proof Tier","Date Verified","Source / Authority","Strategic Deployment Context"],"rows":[["Station add on WNUR 89.3 FM (Chicago)","S-Tier (Broadcast)","Current Quarter","Station Airplay Log / Spinitron","Lead proof point for regional Midwest college push"],["220 tickets sold @ Thalia Hall showcase","A-Tier (Live Market)","Last Month","Ticketmaster / Eventbrite statement","Cite in tour-corridor pitches to Milwaukee/Detroit"],["2,400 organic Spotify saves within 21 days","B-Tier (Traction)","Current Cycle","Spotify for Artists Analytics","Demonstrate listener retention in follow-up emails"],["Featured review in Under The Radar","A-Tier (Press)","Two Months Ago","Editorial Column Link","Quote one sharp sentence in EPK header block"],["Upcoming supporting slot for national act","A-Tier (Co-Sign)","Confirmed Date","Official Venue Announce Poster","Create urgent time-stamped news hook for pitch"]]}],"confirmations":[{"id":"community","text":"One community drill answered (optional but strengthens calibration).","required":false}]}', '{"policy":"all-responses-min-words","minWords":40,"requireAllDrills":true,"requireWorksheetCells":0,"note":""}', '[{"to":"/frequency-dominion/app/campaign","label":"Campaign Builder"},{"to":"/frequency-dominion/app/vault","label":"Proof-stack organizer"}]', 'courses/frequency-dominion/frequency-dominion-course.zip', 1, strftime('%Y-%m-%dT%H:%M:%SZ','now'), strftime('%Y-%m-%dT%H:%M:%SZ','now'))
       ON CONFLICT(id) DO UPDATE SET module_id=excluded.module_id, code=excluded.code, title=excluded.title, minutes=excluded.minutes, exercise_minutes=excluded.exercise_minutes, position=excluded.position, truth=excluded.truth, masterclass_json=excluded.masterclass_json, field_protocol_json=excluded.field_protocol_json, warnings_json=excluded.warnings_json, decoder_json=excluded.decoder_json, worksheets_json=excluded.worksheets_json, community_json=excluded.community_json, exercise_json=excluded.exercise_json, pass_json=excluded.pass_json, tool_links_json=excluded.tool_links_json, version=lessons.version+1, updated_at=strftime('%Y-%m-%dT%H:%M:%SZ','now');
INSERT INTO lessons (id, module_id, code, title, minutes, exercise_minutes, position, published, truth, masterclass_json, field_protocol_json, warnings_json, decoder_json, worksheets_json, community_json, exercise_json, pass_json, tool_links_json, print_asset, version, created_at, updated_at)
       VALUES ('m1l4', 'm1', '1.4', 'The No-Spam Oath & Identity Shift — From Beggar to Frequency Owner', 8, 65, 3, 1, 'The artists who own radio are the ones who behave like owners — precision, respect, and earned volume. The No-Spam Oath is the line that separates you from 99% of your competition.', '[{"b":"h","level":3,"spans":[{"t":"text","v":"Strategic Foundation & Operational Reality"}]},{"b":"p","spans":[{"t":"text","v":"Every working music director receives between 300 and 800 email pitches every single week. Of those submissions, roughly 95% are automated blasts: generic mail-merged templates, untargeted genre mismatches, broken Dropbox links, and desperate pleas sent to info@ or contact@ addresses."}]},{"b":"p","spans":[{"t":"text","v":"Because the baseline behavior of independent musicians is spam, "},{"t":"b","v":"disciplined precision becomes an overwhelming competitive moat"},{"t":"text","v":"."}]},{"b":"p","spans":[{"t":"text","v":"When you send a personalized, format-scored, proof-backed pitch to a named music director, you do not blend in. You immediately stand apart as a serious music business operator. Spam is not merely an ethical failure; it is a catastrophic financial blunder. When you blast an uncurated contact list, your domain gets flagged by enterprise spam filters (Spamhaus, Barracuda, Google Postmaster), your emails land in quarantine junk folders across the entire radio broadcasting network, and you burn relationships before you ever play in that market."}]},{"b":"h","level":3,"spans":[{"t":"text","v":"The Six Articles of the No-Spam Oath"}]},{"b":"p","spans":[{"t":"text","v":"Dominion operators bind themselves to six unalterable operating laws:"}]},{"b":"list","ordered":true,"items":[{"spans":[{"t":"b","v":"Article I — Strict Curation (Never Blast):"},{"t":"text","v":" Every station on your send list must be manually reviewed and scored for format compatibility. If a station does not play your genre, contacting them is an act of career sabotage."}]},{"spans":[{"t":"b","v":"Article II — Named Human Outreach:"},{"t":"text","v":" Every pitch is addressed to the specific programmer, specialty host, or music director responsible for that specific time slot. Zero generic placeholders."}]},{"spans":[{"t":"b","v":"Article III — Proof Before Ask:"},{"t":"text","v":" Verifiable third-party evidence, run-time, and format context appear in the first screen of the pitch before any request for airplay is made."}]},{"spans":[{"t":"b","v":"Article IV — Respect the Station Clock:"},{"t":"text","v":" Pitch delivery times adhere strictly to station programming schedules. Zero Friday afternoon submissions, zero midnight weekend sends. All payloads land during Tuesday/Wednesday morning programming review windows."}]},{"spans":[{"t":"b","v":"Article V — The Rule of Three (Stop at Three):"},{"t":"text","v":" Follow-up sequences are capped at exactly three touches. If three spaced, high-value touches yield no response, the campaign closes gracefully. Zero begging, zero guilt-tripping, zero emotional outbursts. The relationship well remains unburned for the next release."}]},{"spans":[{"t":"b","v":"Article VI — Comprehensive Operational Logging:"},{"t":"text","v":" Every outbound payload, open event, reply, spin, and note is logged in your central tracking ledger. Unlogged campaigns are unmanaged campaigns."}]}]},{"b":"h","level":3,"spans":[{"t":"text","v":"The Psychological Identity Shift"}]},{"b":"p","spans":[{"t":"text","v":"You are terminating your identity as an aspiring hopeful waiting for an industry gatekeeper to discover you. You are assuming the mantle of a "},{"t":"b","v":"Frequency Owner"},{"t":"text","v":". A frequency owner approaches the marketplace with quiet authority, emotional discipline, and deep respect for the broadcast craft. You do not demand attention; you engineer undeniable alignment."}]}]', '[{"b":"p","spans":[{"t":"b","v":"WAR-ROOM DIRECTIVE — 1.4 The No-Spam Oath & Identity Shift — From Beggar to Frequency Owner"}]},{"b":"p","spans":[{"t":"b","v":"SPAM BURNS THE WELL FOR YOUR ENTIRE FUTURE CATALOG"},{"t":"text","v":" Music directors possess long institutional memories. When an artist blasts a generic mass email to 500 programmers at once, those programmers frequently add the artist''s root domain ("},{"t":"code","v":"artistname.com"},{"t":"text","v":") to their station group''s internal blocklist. Station groups like iHeartMedia, Audacy, Cumulus, and major non-comm networks share spam reports across regional clusters."}]},{"b":"p","spans":[{"t":"b","v":"THE OPERATOR''S DISCIPLINE:"}]},{"b":"list","ordered":true,"items":[{"spans":[{"t":"b","v":"Low Volume, High Conversion:"},{"t":"text","v":" The amateur sends 2,000 blind emails and gets zero adds (0% conversion). The Dominion Operator sends 20 curated, personalized payloads, conducts disciplined follow-ups, and lands 4 to 6 verified adds (20-30% conversion). Low volume with high precision is faster, cheaper, and builds permanent allies."}]},{"spans":[{"t":"b","v":"The Dignity of the Polite Exit:"},{"t":"text","v":" When a programmer replies with \"Not a fit for us right now,\" the amateur argues or sulks. The operator replies within two hours: "},{"t":"i","v":"\"Understood [Name] — thank you for taking the time to review. We''ll keep refining our sound and circle back on the next single when we have a stronger format fit. Best with the upcoming ratings week.\""},{"t":"text","v":" That single gracious reply guarantees your next email will be opened. <!-- WARROOM:END -->"}]}]}]', '["When you send a personalized, format-scored, proof-backed pitch to a named music director, you do not blend in.","Article I — Strict Curation (Never Blast): Every station on your send list must be manually reviewed and scored for format compatibility.","You do not demand attention; you engineer undeniable alignment. ## IMPLEMENTATION DRILLS & PASS STANDARDS - Drill 1 — The No-Spam Covenant Ratification (10 min)."]', '["The mechanic: precision is a differentiator because spam is the baseline.","The missing piece: the oath is also a capacity rule — three touches means your relationship bank stays in credit for the next release, not just this one.","The operator move: keep copies of every polite declined reply. The \"not now\" folder is a recheck calendar — a graveyard of future allies, not a graveyard of failure."]', '[{"kind":"note","blocks":[{"b":"p","spans":[{"t":"text","v":"Complete the structured table below as part of your lesson implementation. This worksheet directly replaces legacy spreadsheets with a publication-grade execution protocol."}]}]},{"kind":"table","title":"THE NO-SPAM OPERATIONAL COVENANT","headers":["Covenant Article","Standard of Compliance","Breach Consequence","Operational Verification Metric"],"rows":[["Article I: Strict Curation","100% format alignment scored >= 75 pts","Zero-response burn; domain penalty","Format Scorecard completed prior to send"],["Article II: Named Gatekeeper","Verified individual name and direct inbox","Instant inbox deletion; automated spam rule","Direct verification via station website or call"],["Article III: Proof Precedence","Four-line proof stack in initial view","Perceived amateur status; high-risk skip","S-Tier or A-Tier receipt integrated in pitch"],["Article IV: Clock Respect","Delivered Tuesday/Wednesday 9:30 AM local","Payload buried under weekend email avalanche","Email scheduler locked to station time zone"],["Article V: Rule of Three","Strict 3-touch maximum follow-up cadence","Harassment flag; permanent blacklisting","Touch counter logged; auto-pause after Touch 3"],["Article VI: Ledger Discipline","100% of interactions logged same day","Loss of attribution data; duplicate sends","Daily tracking ledger updated within 60 minutes"]]}]', '["Publicly affirm your commitment to the No-Spam Oath in the community thread. Post your signed covenant statement.","Share the size of your pruned, verified target list compared to the uncurated list you previously possessed.","Describe a historical email blast mistake you made and calculate how many prospective station relationships were burned.","Confirm that your sending domain has active SPF, DKIM, and DMARC authentication."]', '{"kind":"field-exercise","prompt":"Complete every drill below with real, verifiable answers, then confirm the pass standard.","items":[{"id":"d1","label":"The No-Spam Covenant Ratification","description":"The No-Spam Covenant Ratification . Read the Six Articles of the No-Spam Oath aloud. Sign and date your operational commitment on the protocol sheet below.","minutes":10,"type":"response","passStandard":null},{"id":"d2","label":"Domain Health & Deliverability Audit","description":"Domain Health & Deliverability Audit . Check your sending domain against MXToolbox and Google Postmaster tools. Verify that SPF, DKIM, and DMARC records are correctly configured to ensure inbox delivery.","minutes":20,"type":"response","passStandard":null},{"id":"d3","label":"The Unsubscribe & Scrub Protocol","description":"The Unsubscribe & Scrub Protocol . Review your contact database. Purge every contact where the station callsign, market, format, or programmer name is unverified. Cut your send list to a razor-sharp, verified core.","minutes":20,"type":"response","passStandard":null},{"id":"d4","label":"The Re-Check Calendar Architecture","description":"The Re-Check Calendar Architecture . Establish a dedicated \"Declined / Not Now\" calendar reminder 90 days in the future for any currently cold contacts. Prepare your mindset for long-term pipeline compounding.","minutes":15,"type":"response","passStandard":null}],"worksheets":[{"kind":"table","title":"THE NO-SPAM OPERATIONAL COVENANT","headers":["Covenant Article","Standard of Compliance","Breach Consequence","Operational Verification Metric"],"rows":[["Article I: Strict Curation","100% format alignment scored >= 75 pts","Zero-response burn; domain penalty","Format Scorecard completed prior to send"],["Article II: Named Gatekeeper","Verified individual name and direct inbox","Instant inbox deletion; automated spam rule","Direct verification via station website or call"],["Article III: Proof Precedence","Four-line proof stack in initial view","Perceived amateur status; high-risk skip","S-Tier or A-Tier receipt integrated in pitch"],["Article IV: Clock Respect","Delivered Tuesday/Wednesday 9:30 AM local","Payload buried under weekend email avalanche","Email scheduler locked to station time zone"],["Article V: Rule of Three","Strict 3-touch maximum follow-up cadence","Harassment flag; permanent blacklisting","Touch counter logged; auto-pause after Touch 3"],["Article VI: Ledger Discipline","100% of interactions logged same day","Loss of attribution data; duplicate sends","Daily tracking ledger updated within 60 minutes"]]}],"confirmations":[{"id":"community","text":"One community drill answered (optional but strengthens calibration).","required":false}]}', '{"policy":"all-responses-min-words","minWords":40,"requireAllDrills":true,"requireWorksheetCells":0,"note":""}', '[{"to":"/frequency-dominion/app/campaign","label":"Campaign Builder"},{"to":"/frequency-dominion/app/vault","label":"Proof-stack organizer"}]', 'courses/frequency-dominion/frequency-dominion-course.zip', 1, strftime('%Y-%m-%dT%H:%M:%SZ','now'), strftime('%Y-%m-%dT%H:%M:%SZ','now'))
       ON CONFLICT(id) DO UPDATE SET module_id=excluded.module_id, code=excluded.code, title=excluded.title, minutes=excluded.minutes, exercise_minutes=excluded.exercise_minutes, position=excluded.position, truth=excluded.truth, masterclass_json=excluded.masterclass_json, field_protocol_json=excluded.field_protocol_json, warnings_json=excluded.warnings_json, decoder_json=excluded.decoder_json, worksheets_json=excluded.worksheets_json, community_json=excluded.community_json, exercise_json=excluded.exercise_json, pass_json=excluded.pass_json, tool_links_json=excluded.tool_links_json, version=lessons.version+1, updated_at=strftime('%Y-%m-%dT%H:%M:%SZ','now');
INSERT INTO lessons (id, module_id, code, title, minutes, exercise_minutes, position, published, truth, masterclass_json, field_protocol_json, warnings_json, decoder_json, worksheets_json, community_json, exercise_json, pass_json, tool_links_json, print_asset, version, created_at, updated_at)
       VALUES ('m2l1', 'm2', '2.1', 'The Hometown Heat Map — Find the Stations That Can''t Say No', 8, 105, 0, 1, 'Your first 20 wins are a geography problem, not a music problem. The Hometown Heat Map concentrates your fire where proximity makes you commercially undeniable.', '[{"b":"h","level":3,"spans":[{"t":"text","v":"Strategic Foundation & Operational Reality"}]},{"b":"p","spans":[{"t":"text","v":"Every unguided independent artist attempts to conquer national flagship radio on Day 1. They send unsolicited pitches to KROQ in Los Angeles, Z100 in New York, or BBC Radio 1 in London. These stations operate at the apex of global commercial media. Their playlists are tightly programmed by corporate consulting syndicates, major label priorities, and millions of dollars in marketing momentum. Approaching them without regional leverage is a total waste of operational energy."}]},{"b":"p","spans":[{"t":"text","v":"Radio is fundamentally a "},{"t":"b","v":"regional broadcast utility"},{"t":"text","v":". The Federal Communications Commission (FCC) explicitly mandates that broadcast licensees demonstrate service to their local community of license. Furthermore, program directors in secondary and regional markets pride themselves on breaking homegrown talent before national syndication discovers them."}]},{"b":"p","spans":[{"t":"text","v":"The "},{"t":"b","v":"Hometown Heat Map"},{"t":"text","v":" is your targeting architecture. It organizes the radio landscape into four concentric geographic perimeters centered on your home market:"}]},{"b":"list","ordered":false,"items":[{"spans":[{"t":"b","v":"Ring 1: Immediate Home Metro (0 to 30 miles):"},{"t":"text","v":" Your home city stations, municipal community broadcasters, and local campus radio. You are a taxpayer, a local ticket seller, and a direct community member. You are local news."}]},{"spans":[{"t":"b","v":"Ring 2: Adjacent Commuter Zone (30 to 90 miles):"},{"t":"text","v":" Regional commuter corridors, neighboring college towns, and secondary suburban stations. Listeners here travel into your home metro for weekend entertainment and live events."}]},{"spans":[{"t":"b","v":"Ring 3: Extended Regional Perimeter (90 to 200 miles):"},{"t":"text","v":" Driving-distance cities with shared regional cultural identity. Stations here are hungry for touring acts that can route through their clubs on weekend runs."}]},{"spans":[{"t":"b","v":"Ring 4: Tour Corridor Corridor (200 to 350 miles):"},{"t":"text","v":" Strategic regional hubs on your regular tour circuit where airplay directly primes ticket presales."}]}]},{"b":"h","level":3,"spans":[{"t":"text","v":"Proximity as Commercial Leverage"}]},{"b":"p","spans":[{"t":"text","v":"Why does geographic proximity convert at 5x the rate of distant pitching?"}]},{"b":"list","ordered":true,"items":[{"spans":[{"t":"b","v":"The Walk-In Factor:"},{"t":"text","v":" In Rings 1 and 2, you are a physical human being. You can drop off physical vinyl at the front desk, attend station-sponsored charity events, or drop into an afternoon specialty show for an on-air acoustic performance."}]},{"spans":[{"t":"b","v":"Audience Overlap:"},{"t":"text","v":" A spin on a Ring 1 station reaches listeners who can physically attend your next club gig, buy your merchandise, and request your song on competing local stations."}]},{"spans":[{"t":"b","v":"Low Programmer Risk:"},{"t":"text","v":" When a programmer plays a hometown artist who draws 200 locals to a neighborhood venue, the programmer looks like an astute local tastemaker. When they play an unknown artist from 2,000 miles away, they look reckless."}]}]}]', '[{"b":"p","spans":[{"t":"b","v":"WAR-ROOM DIRECTIVE — 2.1 The Hometown Heat Map — Find the Stations That Can''t Say No"}]},{"b":"p","spans":[{"t":"b","v":"DOMINATE YOUR BACKYARD BEFORE EXPANDING THE MAP"},{"t":"text","v":" If you cannot generate 10 station adds within 150 miles of your hometown, expanding your marketing budget to national promotion is a guaranteed waste of capital. A national programmer at SiriusXM or NPR will immediately review your hometown footprint. If your hometown public and college stations have ignored you, national programmers conclude that your music lacks localized audience resonance."}]},{"b":"p","spans":[{"t":"b","v":"TACTICAL HEAT MAP DRILLS:"}]},{"b":"list","ordered":true,"items":[{"spans":[{"t":"b","v":"The Triangle Tour Method:"},{"t":"text","v":" Identify three Ring 3 cities that form a drivable weekend triangle (e.g., Philadelphia, Baltimore, Washington D.C., or Cleveland, Columbus, Pittsburgh). Coordinate radio pitches across all three markets simultaneously around a three-date weekend run."}]},{"spans":[{"t":"b","v":"Specialty Show Hosts Are Gold:"},{"t":"text","v":" Avoid pitching the station General Manager or general Music Director on your first pass. Identify the host of the Sunday night local music showcase. These hosts have 100% curation autonomy over their 2-hour blocks and actively seek regional talent to interview. <!-- WARROOM:END -->"}]}]}]', '[]', '["The mechanic: geography lowers ask risk.","The missing piece: tier the markets, not just the rings: college towns (hungry, weekly cycles), mid metros (moderate pressure), PPM metros (conservative). Each tier has different physics.","The operator move: map min 2 college towns in the first campaign. The college lane produces proof faster than any commercial station."]', '[{"kind":"note","blocks":[{"b":"p","spans":[{"t":"text","v":"Complete the structured table below as part of your lesson implementation. This worksheet directly replaces legacy spreadsheets with a publication-grade execution protocol."}]}]},{"kind":"table","title":"HOMETOWN HEAT MAP TARGETING MATRIX","headers":["Target Station","Callsign & Dial","Market & City","Ring Radius","Station Format Tier","Local Story Angle Hook"],"rows":[["WLUW 88.7 FM","WLUW (Loyola Univ)","Chicago, IL","Ring 1 (0-15 mi)","College Alternative / Specialty","Hometown album launch @ Empty Bottle"],["WNUR 89.3 FM","WNUR (Northwestern)","Evanston, IL","Ring 1 (15-30 mi)","Non-Comm Progressive / Indie","Live in-studio session offer during load-in"],["WZRD 88.3 FM","WZRD (NE Illinois)","Chicago, IL","Ring 1 (0-15 mi)","Freeform Community / Rock","Local DIY scene residency feature"],["WXAV 88.3 FM","WXAV (Saint Xavier)","Chicago Southside","Ring 2 (30-60 mi)","Modern College Rock","Southside concert date cross-promotion"],["WMSE 91.7 FM","WMSE (MSOE)","Milwaukee, WI","Ring 3 (90 mi)","AAA / Eclectic Regional","Weekend tour corridor date @ Cactus Club"]]}]', '["Post your completed Hometown Heat Map with your Top 5 Ring 1 priority targets.","Share your one-sentence Local Story Angle Hook for peer feedback.","Name the closest college or non-commercial radio station to your residence and state whether you have ever pitched their local music director.","Identify one neighboring city in Ring 3 that you plan to incorporate into your first regional tour corridor."]', '{"kind":"field-exercise","prompt":"Complete every drill below with real, verifiable answers, then confirm the pass standard.","items":[{"id":"d1","label":"The Four-Ring Geographic Sweep","description":"The Four-Ring Geographic Sweep . Plot your primary home address and identify all broadcast stations across Rings 1 through 4 using the Hometown Heat Map Worksheet below. Populate at least 30 verified stations.","minutes":45,"type":"response","passStandard":null},{"id":"d2","label":"The Campus & Community Anchor Sweep","description":"The Campus & Community Anchor Sweep . Identify every university, college, and non-commercial community station within a 60-mile radius. Identify the specific specialty shows catering to your genre.","minutes":25,"type":"response","passStandard":null},{"id":"d3","label":"The Local Story Angle Formulator","description":"The Local Story Angle Formulator . Draft a tailored, one-sentence local story hook for three distinct Ring 1 stations (e.g., tying into a local landmark, landmark gig, or hometown heritage).","minutes":20,"type":"response","passStandard":null},{"id":"d4","label":"The Top-20 Priority Filter","description":"The Top-20 Priority Filter . Filter your full heat map down to the 20 highest-probability stations based on proximity, format fit, and named decision-maker access.","minutes":15,"type":"response","passStandard":null}],"worksheets":[{"kind":"table","title":"HOMETOWN HEAT MAP TARGETING MATRIX","headers":["Target Station","Callsign & Dial","Market & City","Ring Radius","Station Format Tier","Local Story Angle Hook"],"rows":[["WLUW 88.7 FM","WLUW (Loyola Univ)","Chicago, IL","Ring 1 (0-15 mi)","College Alternative / Specialty","Hometown album launch @ Empty Bottle"],["WNUR 89.3 FM","WNUR (Northwestern)","Evanston, IL","Ring 1 (15-30 mi)","Non-Comm Progressive / Indie","Live in-studio session offer during load-in"],["WZRD 88.3 FM","WZRD (NE Illinois)","Chicago, IL","Ring 1 (0-15 mi)","Freeform Community / Rock","Local DIY scene residency feature"],["WXAV 88.3 FM","WXAV (Saint Xavier)","Chicago Southside","Ring 2 (30-60 mi)","Modern College Rock","Southside concert date cross-promotion"],["WMSE 91.7 FM","WMSE (MSOE)","Milwaukee, WI","Ring 3 (90 mi)","AAA / Eclectic Regional","Weekend tour corridor date @ Cactus Club"]]}],"confirmations":[{"id":"community","text":"One community drill answered (optional but strengthens calibration).","required":false}]}', '{"policy":"all-responses-min-words","minWords":40,"requireAllDrills":true,"requireWorksheetCells":0,"note":""}', '[{"to":"/frequency-dominion/app/heatmap","label":"Heat Map workspace"},{"to":"/frequency-dominion/app/stations","label":"Station War Room"}]', 'courses/frequency-dominion/frequency-dominion-course.zip', 1, strftime('%Y-%m-%dT%H:%M:%SZ','now'), strftime('%Y-%m-%dT%H:%M:%SZ','now'))
       ON CONFLICT(id) DO UPDATE SET module_id=excluded.module_id, code=excluded.code, title=excluded.title, minutes=excluded.minutes, exercise_minutes=excluded.exercise_minutes, position=excluded.position, truth=excluded.truth, masterclass_json=excluded.masterclass_json, field_protocol_json=excluded.field_protocol_json, warnings_json=excluded.warnings_json, decoder_json=excluded.decoder_json, worksheets_json=excluded.worksheets_json, community_json=excluded.community_json, exercise_json=excluded.exercise_json, pass_json=excluded.pass_json, tool_links_json=excluded.tool_links_json, version=lessons.version+1, updated_at=strftime('%Y-%m-%dT%H:%M:%SZ','now');
INSERT INTO lessons (id, module_id, code, title, minutes, exercise_minutes, position, published, truth, masterclass_json, field_protocol_json, warnings_json, decoder_json, worksheets_json, community_json, exercise_json, pass_json, tool_links_json, print_asset, version, created_at, updated_at)
       VALUES ('m2l2', 'm2', '2.2', 'Tour Pre-Roll — Manufacture Airplay Demand With Dates', 8, 75, 1, 1, 'A confirmed show date is the single most potent airplay catalyst in independent music — converting an abstract song submission into a time-stamped, ticket-selling community event.', '[{"b":"h","level":3,"spans":[{"t":"text","v":"Strategic Foundation & Operational Reality"}]},{"b":"p","spans":[{"t":"text","v":"The most difficult hurdle in radio promotion is overcoming programmer inertia. A music director listens to dozens of excellent songs every week. Even when they appreciate your sound, they frequently defer action: "},{"t":"i","v":"\"Great track, let''s keep an ear on them for next quarter.\""}]},{"b":"p","spans":[{"t":"text","v":"A confirmed live concert date completely shatters this inertia by introducing a hard "},{"t":"b","v":"countdown clock"},{"t":"text","v":"."}]},{"b":"p","spans":[{"t":"text","v":"When you pitch a station with an upcoming tour date in their market, the entire commercial dynamic flips:"}]},{"b":"list","ordered":false,"items":[{"spans":[{"t":"text","v":"You are no longer asking them to evaluate your song in an academic vacuum."}]},{"spans":[{"t":"text","v":"You are offering their listeners an immediate real-world entertainment experience."}]},{"spans":[{"t":"text","v":"You provide an urgent news hook: the station can conduct an on-air interview, give away ticket pairs to listeners, and brand themselves as the cultural patron behind a vibrant live event."}]}]},{"b":"p","spans":[{"t":"text","v":"This methodology is known as "},{"t":"b","v":"Tour Pre-Roll"},{"t":"text","v":". It synchronizes radio outreach with live performance routing on a disciplined, backwards-engineered countdown starting exactly 21 days prior to venue load-in."}]},{"b":"h","level":3,"spans":[{"t":"text","v":"The 21-Day Tour Pre-Roll Timeline"}]},{"b":"p","spans":[{"t":"text","v":"To extract maximum airplay and ticket conversion, execute this strict 4-phase chronological sequence:"}]},{"b":"list","ordered":false,"items":[{"spans":[{"t":"b","v":"T-21 Days (The Anchor Pitch):"},{"t":"text","v":" Deliver your high-value 90-word pitch to the Music Director and specialty show hosts. Lead with the venue name, performance date, and ticket link. Offer a 10-minute in-studio or phone interview during afternoon drive on the day of show, plus two pairs of guest-list tickets for station listeners."}]},{"spans":[{"t":"b","v":"T-14 Days (The Asset Follow-Up):"},{"t":"text","v":" If unconfirmed, deliver a 30-second live acoustic performance clip or a dynamic 20-second crowd video demonstrating real-world audience energy. Remind the programmer of the upcoming local date."}]},{"spans":[{"t":"b","v":"T-7 Days (The Ticket / Station ID Drop):"},{"t":"text","v":" Provide pre-recorded custom station audio sweepers ("},{"t":"i","v":"\"Hey, this is [Artist Name], catch us live this Friday at [Venue], spinning now on [Station Callsign]\""},{"t":"text","v":"). Secure on-air spin placement during the pre-weekend specialty show."}]},{"spans":[{"t":"b","v":"T+2 Days (The Post-Show Crowd Telegram):"},{"t":"text","v":" Within 48 hours of load-out, email the programmer a high-resolution 15-second crowd video of the audience singing your chorus, thanking the station for supporting local live music. This single gesture cements a lifetime relationship and guarantees immediate adds on your next single."}]}]}]', '[{"b":"p","spans":[{"t":"b","v":"WAR-ROOM DIRECTIVE — 2.2 Tour Pre-Roll — Manufacture Airplay Demand With Dates"}]},{"b":"p","spans":[{"t":"b","v":"HOW TO RUN TOUR PRE-ROLL WITH ZERO EXISTING TOUR DATES"},{"t":"text","v":" If you do not currently have an active tour booked, you do not wait. You "},{"t":"b","v":"manufacture a regional micro-run"},{"t":"text","v":". Book two weekend dates within 90 miles of home (e.g., Friday night in your hometown club, Saturday night at a neighboring college town bar)."}]},{"b":"p","spans":[{"t":"text","v":"Even a single two-venue weekend run provides the legitimate, time-stamped news hook required to execute the Tour Pre-Roll sequence."}]},{"b":"p","spans":[{"t":"b","v":"THE INTERVIEW TIME-WINDOW STRATEGY:"},{"t":"text","v":" When offering an interview to a radio programmer, never ask them to accommodate your schedule. Propose a specific, convenient window that aligns with their broadcast clock:"}]},{"b":"list","ordered":false,"items":[{"spans":[{"t":"i","v":"\"I will be arriving at [Venue] for soundcheck at 4:30 PM. I can drop by your studio between 2:00 PM and 3:30 PM for a 10-minute live chat and acoustic performance, or patch in via phone at your exact convenience.\""},{"t":"text","v":" This signals extreme professional consideration and eliminates scheduling friction. <!-- WARROOM:END -->"}]}]}]', '["THE INTERVIEW TIME-WINDOW STRATEGY: When offering an interview to a radio programmer, never ask them to accommodate your schedule."]', '["The mechanic: dates are story + deadline + market.","The missing piece: the show''s aftermath is the real asset — the crowd telegram converts at show + 48h.","The operator move: send the PD a 20-second vertical clip of the crowd on the night itself. The next-day \"we''re still talking about it\" email is the strongest thank-you in the economy."]', '[{"kind":"note","blocks":[{"b":"p","spans":[{"t":"text","v":"Complete the structured table below as part of your lesson implementation. This worksheet directly replaces legacy spreadsheets with a publication-grade execution protocol."}]}]},{"kind":"table","title":"TOUR PRE-ROLL CAMPAIGN SCHEDULER","headers":["Tour City & Venue","Show Date","Target Station & MD","T-21 Anchor Pitch Date","T-14 Asset Drop Date","T-7 Ticket / Sweeper Date"],"rows":[["Milwaukee, WI (Cactus Club)","October 14","WMSE 91.7 FM (MD: Tom)","September 23","September 30","October 7"],["Madison, WI (High Noon Saloon)","October 15","WSUM 91.7 FM (MD: Sarah)","September 24","October 1","October 8"],["Minneapolis, MN (7th St Entry)","October 17","Radio K 100.7 (MD: Chris)","September 26","October 3","October 10"],["Detroit, MI (Magic Stick)","November 4","WJLB / WDET (MD: Marcus)","October 14","October 21","October 28"],["Cleveland, OH (Grog Shop)","November 6","WCSB 89.3 FM (MD: Elena)","October 16","October 23","October 30"]]}]', '["Post your upcoming tour dates and matching radio station targets from your Pre-Roll Scheduler.","Share the exact script you will record for your station-specific audio sweeper drop.","Discuss how you plan to capture the 15-second Post-Show Crowd Telegram video during your next gig.","If you currently have no dates booked, announce your 14-day deadline to book a regional two-date micro-run."]', '{"kind":"field-exercise","prompt":"Complete every drill below with real, verifiable answers, then confirm the pass standard.","items":[{"id":"d1","label":"The Tour-Date Airplay Sync","description":"The Tour-Date Airplay Sync . Review your calendar for the next 90 days. Select three confirmed or planned dates. Populate the Tour Pre-Roll Calendar Worksheet below with specific T-21, T-14, and T-7 dates.","minutes":30,"type":"response","passStandard":null},{"id":"d2","label":"The Station Ticket-Pack Architecture","description":"The Station Ticket-Pack Architecture . Draft a formal email template offering station ticket giveaways (2 pairs of guest-list passes) and an afternoon interview window during load-in.","minutes":15,"type":"response","passStandard":null},{"id":"d3","label":"The Custom Station Sweeper Script","description":"The Custom Station Sweeper Script . Record a clean 15-second station audio drop on your phone or studio microphone: \"Hey this is [Artist], live at [Venue] on [Date], and you''re locked into [Station]\".","minutes":20,"type":"response","passStandard":null},{"id":"d4","label":"The Post-Show Telegram Protocol","description":"The Post-Show Telegram Protocol . Create a reminder in your phone calendar for Show Night + 24 hours: ''Record crowd clip and dispatch thank-you telegram to station programmer.''","minutes":10,"type":"response","passStandard":null}],"worksheets":[{"kind":"table","title":"TOUR PRE-ROLL CAMPAIGN SCHEDULER","headers":["Tour City & Venue","Show Date","Target Station & MD","T-21 Anchor Pitch Date","T-14 Asset Drop Date","T-7 Ticket / Sweeper Date"],"rows":[["Milwaukee, WI (Cactus Club)","October 14","WMSE 91.7 FM (MD: Tom)","September 23","September 30","October 7"],["Madison, WI (High Noon Saloon)","October 15","WSUM 91.7 FM (MD: Sarah)","September 24","October 1","October 8"],["Minneapolis, MN (7th St Entry)","October 17","Radio K 100.7 (MD: Chris)","September 26","October 3","October 10"],["Detroit, MI (Magic Stick)","November 4","WJLB / WDET (MD: Marcus)","October 14","October 21","October 28"],["Cleveland, OH (Grog Shop)","November 6","WCSB 89.3 FM (MD: Elena)","October 16","October 23","October 30"]]}],"confirmations":[{"id":"community","text":"One community drill answered (optional but strengthens calibration).","required":false}]}', '{"policy":"all-responses-min-words","minWords":40,"requireAllDrills":true,"requireWorksheetCells":0,"note":""}', '[{"to":"/frequency-dominion/app/heatmap","label":"Heat Map workspace"},{"to":"/frequency-dominion/app/stations","label":"Station War Room"}]', 'courses/frequency-dominion/frequency-dominion-course.zip', 1, strftime('%Y-%m-%dT%H:%M:%SZ','now'), strftime('%Y-%m-%dT%H:%M:%SZ','now'))
       ON CONFLICT(id) DO UPDATE SET module_id=excluded.module_id, code=excluded.code, title=excluded.title, minutes=excluded.minutes, exercise_minutes=excluded.exercise_minutes, position=excluded.position, truth=excluded.truth, masterclass_json=excluded.masterclass_json, field_protocol_json=excluded.field_protocol_json, warnings_json=excluded.warnings_json, decoder_json=excluded.decoder_json, worksheets_json=excluded.worksheets_json, community_json=excluded.community_json, exercise_json=excluded.exercise_json, pass_json=excluded.pass_json, tool_links_json=excluded.tool_links_json, version=lessons.version+1, updated_at=strftime('%Y-%m-%dT%H:%M:%SZ','now');
INSERT INTO lessons (id, module_id, code, title, minutes, exercise_minutes, position, published, truth, masterclass_json, field_protocol_json, warnings_json, decoder_json, worksheets_json, community_json, exercise_json, pass_json, tool_links_json, print_asset, version, created_at, updated_at)
       VALUES ('m2l3', 'm2', '2.3', 'The Format Scoring System — Rank Every Station Like an Analyst', 8, 85, 2, 1, 'Format fit accounts for 50% of every programming rejection. Scoring stations with mathematical rigor prevents you from wasting A-tier pitches on zero-probability rooms.', '[{"b":"h","level":3,"spans":[{"t":"text","v":"Strategic Foundation & Operational Reality"}]},{"b":"p","spans":[{"t":"text","v":"The most demoralizing experience in music promotion is sending 100 passionate emails and receiving 100 deafening silences. When this happens, artists inevitably conclude that their art is inadequate. In 90% of cases, the music was never the issue; the campaign suffered from catastrophic "},{"t":"b","v":"format misalignment"},{"t":"text","v":"."}]},{"b":"p","spans":[{"t":"text","v":"Radio formats are rigid, mathematically optimized consumer products. An Urban Contemporary programmer will not play an Americana folk ballad, no matter how emotionally profound the lyrics are. A Classical public station will not air an 808-heavy trap single."}]},{"b":"p","spans":[{"t":"text","v":"To eliminate wasted effort, Dominion operators evaluate every prospective station through a clinical "},{"t":"b","v":"100-Point Format Scoring System"},{"t":"text","v":" across six weighted factors before a single email is dispatched."}]},{"b":"h","level":3,"spans":[{"t":"text","v":"The Six Weighted Scoring Factors (100-Point Scale)"}]},{"b":"list","ordered":false,"items":[{"spans":[{"t":"b","v":"Genre & Sonic Architecture Compatibility (30 Points Max):"},{"t":"text","v":" Does your song''s instrumentation, tempo, vocal production, and dynamic range match the current charting records on the station''s playlist?"}]},{"spans":[{"t":"i","v":"30 pts:"},{"t":"text","v":" Perfect sonic twin of core charting rotation."}]},{"spans":[{"t":"i","v":"20 pts:"},{"t":"text","v":" Compatible sub-genre fitting evening specialty blocks."}]},{"spans":[{"t":"i","v":"10 pts:"},{"t":"text","v":" Marginal fit requiring specialized programming context."}]},{"spans":[{"t":"i","v":"0 pts:"},{"t":"text","v":" Glaring format clash."}]},{"spans":[{"t":"b","v":"Geographic Proximity & Regional Equity (20 Points Max):"},{"t":"text","v":" Station proximity to your home market or active tour corridor."}]},{"spans":[{"t":"i","v":"20 pts:"},{"t":"text","v":" Ring 1 home city or active local venue market."}]},{"spans":[{"t":"i","v":"15 pts:"},{"t":"text","v":" Ring 2 commuter zone (30-90 miles)."}]},{"spans":[{"t":"i","v":"10 pts:"},{"t":"text","v":" Ring 3 regional tour corridor."}]},{"spans":[{"t":"i","v":"0 pts:"},{"t":"text","v":" Distant market with zero tour or regional narrative."}]},{"spans":[{"t":"b","v":"Verified Individual Human Contact (15 Points Max):"},{"t":"text","v":" Quality of gatekeeper access."}]},{"spans":[{"t":"i","v":"15 pts:"},{"t":"text","v":" Direct email address of named Music Director or specialty show host."}]},{"spans":[{"t":"i","v":"10 pts:"},{"t":"text","v":" Direct email of Assistant MD or verified personal social channel."}]},{"spans":[{"t":"i","v":"5 pts:"},{"t":"text","v":" General music department inbox ("},{"t":"code","v":"music@station.org"},{"t":"text","v":")."}]},{"spans":[{"t":"i","v":"0 pts:"},{"t":"text","v":" Generic "},{"t":"code","v":"info@"},{"t":"text","v":" or broken online submission form."}]},{"spans":[{"t":"b","v":"Historical Appetite for Independent Adds (15 Points Max):"},{"t":"text","v":" Does the station actively add independent, self-released artists, or do they exclusively air major-label syndicated priorities?"}]},{"spans":[{"t":"i","v":"15 pts:"},{"t":"text","v":" Verified independent artist spins documented on Spinitron / playlist."}]},{"spans":[{"t":"i","v":"10 pts:"},{"t":"text","v":" Regular dedicated weekly local/indie music spotlight hour."}]},{"spans":[{"t":"i","v":"5 pts:"},{"t":"text","v":" Occasional off-peak independent spins."}]},{"spans":[{"t":"i","v":"0 pts:"},{"t":"text","v":" 100% corporate syndication with zero local curation power."}]},{"spans":[{"t":"b","v":"Broadcast Clock & Daypart Viability (10 Points Max):"},{"t":"text","v":" Run-time and tempo compliance."}]},{"spans":[{"t":"i","v":"10 pts:"},{"t":"text","v":" Run-time between 2:40 and 3:30; immediate vocal entry within 15 seconds."}]},{"spans":[{"t":"i","v":"5 pts:"},{"t":"text","v":" Run-time up to 4:00 requiring specialized editing."}]},{"spans":[{"t":"i","v":"0 pts:"},{"t":"text","v":" Exceeds 4:30 or features extended instrumental ambient passages."}]},{"spans":[{"t":"b","v":"Commercial Counter-Programming Value (10 Points Max):"},{"t":"text","v":" Does your track provide the station with a unique sonic angle to compete against rival stations?"}]},{"spans":[{"t":"i","v":"10 pts:"},{"t":"text","v":" Fills an unserved niche that drives fresh listener curiosity."}]},{"spans":[{"t":"i","v":"5 pts:"},{"t":"text","v":" Standard format entry."}]},{"spans":[{"t":"i","v":"0 pts:"},{"t":"text","v":" Redundant clone of heavily saturated charting tracks."}]}]},{"b":"h","level":3,"spans":[{"t":"text","v":"Tier Classification & Resource Allocation"}]},{"b":"list","ordered":false,"items":[{"spans":[{"t":"b","v":"Tier 1 (85 – 100 Points) — Priority Firing Squad:"},{"t":"text","v":" High-priority A-list targets. Receive customized 3-layer subject lines, tailored audio packages, phone follow-ups, and tour integration."}]},{"spans":[{"t":"b","v":"Tier 2 (70 – 84 Points) — Secondary Wave:"},{"t":"text","v":" Reliable B-list targets. Receive standard 90-word pitches and 3-touch follow-up sequences."}]},{"spans":[{"t":"b","v":"Tier 3 (50 – 69 Points) — Nurture / Hold Queue:"},{"t":"text","v":" Log in database for future catalog releases or after S-tier proof has been established."}]},{"spans":[{"t":"b","v":"Tier 4 (< 50 Points) — The Dead Zone:"},{"t":"text","v":" "},{"t":"b","v":"DO NOT CONTACT."},{"t":"text","v":" Pitching these stations wastes time and damages sender reputation."}]}]}]', '[{"b":"p","spans":[{"t":"b","v":"WAR-ROOM DIRECTIVE — 2.3 The Format Scoring System — Rank Every Station Like an Analyst"}]},{"b":"p","spans":[{"t":"b","v":"SCORE THE PLAYLIST, NOT THE STATION''S ABOUT PAGE"},{"t":"text","v":" Stations frequently brand themselves with aspirational slogans: "},{"t":"i","v":"\"Playing the best new eclectic independent music.\""},{"t":"text","v":" In reality, their daytime programming may be 80% 1990s recurrent rock hits, with only two hours of genuine independent discovery buried at 11:00 PM on Sunday night."}]},{"b":"p","spans":[{"t":"b","v":"THE OPERATOR''S RECONNAISSANCE RULE:"},{"t":"text","v":" Never evaluate a station by what they claim to play. Evaluate them exclusively by their "},{"t":"b","v":"actual broadcast logs over the past 72 hours"},{"t":"text","v":"."}]},{"b":"list","ordered":true,"items":[{"spans":[{"t":"text","v":"Look at their 10:00 AM, 2:00 PM, and 8:00 PM logs."}]},{"spans":[{"t":"text","v":"If you see zero independent artists across daytime hours, your pitch belongs exclusively to their evening specialty show host."}]},{"spans":[{"t":"text","v":"Pitching a daytime music director with an underground track when their daytime clock is locked to gold recurrents guarantees instant deletion. <!-- WARROOM:END -->"}]}]}]', '["In 90% of cases, the music was never the issue; the campaign suffered from catastrophic format misalignment.","THE OPERATOR''S RECONNAISSANCE RULE: Never evaluate a station by what they claim to play."]', '["The mechanic: fit is measurable.","The missing piece: score the playlist, not the website. A station''s stream history is the truth; the format label is a rumor.","The operator move: pull the last 10–15 played songs via online stream logs and plot tempo + energy + era. You''ll find the \"neighborhood\" of your genre — that''s your actual target definition."]', '[{"kind":"note","blocks":[{"b":"p","spans":[{"t":"text","v":"Complete the structured table below as part of your lesson implementation. This worksheet directly replaces legacy spreadsheets with a publication-grade execution protocol."}]}]},{"kind":"table","title":"100-POINT FORMAT FIT SCORECARD","headers":["Station & Market","Genre Fit (30)","Geo Proximity (20)","Named Contact (15)","Indie Adds (15)","Clock Fit (10)","Counter Prog (10)","Total (100)","Tier Rank"],"rows":[["WNUR 89.3 FM (Chicago)","28","20","15","15","10","8","96","Tier 1 (Priority)"],["WLUW 88.7 FM (Chicago)","30","20","15","15","10","6","96","Tier 1 (Priority)"],["WMSE 91.7 FM (Milwaukee)","26","15","15","12","10","7","85","Tier 1 (Priority)"],["WXRT 93.1 FM (Commercial AAA)","22","20","15","8","10","5","80","Tier 2 (Secondary)"],["WKQX 101.1 FM (Alt Commercial)","15","20","10","4","10","4","63","Tier 3 (Hold)"]]}]', '["Post your highest-scoring station and break down its point tally across the six factors.","Share a station that scored below 50 points and explain why you purged it from your campaign.","What was the biggest surprise you encountered when auditing station play logs on Spinitron?","How many total Tier 1 stations do you currently have locked for your upcoming campaign?"]', '{"kind":"field-exercise","prompt":"Complete every drill below with real, verifiable answers, then confirm the pass standard.","items":[{"id":"d1","label":"The Playlist Stream Audit","description":"The Playlist Stream Audit . Select 10 stations from your Hometown Heat Map. Pull their last 7 days of playlist history via their website or Spinitron. Verify their actual sound versus their marketing slogan.","minutes":30,"type":"response","passStandard":null},{"id":"d2","label":"The 100-Point Scoring Calibration","description":"The 100-Point Scoring Calibration . Score all 10 stations using the Format Scorecard Worksheet below. Calculate total points and assign Tier classifications.","minutes":30,"type":"response","passStandard":null},{"id":"d3","label":"The Dead Zone Purge","description":"The Dead Zone Purge . Ruthlessly identify and strike any station scoring below 50 points from your active 21-day campaign target list.","minutes":10,"type":"response","passStandard":null},{"id":"d4","label":"The Tier 1 Tactical Plan","description":"The Tier 1 Tactical Plan . For your top 3 scoring stations (90+ points), write a one-sentence justification detailing why their music director cannot afford to ignore your submission.","minutes":15,"type":"response","passStandard":null}],"worksheets":[{"kind":"table","title":"100-POINT FORMAT FIT SCORECARD","headers":["Station & Market","Genre Fit (30)","Geo Proximity (20)","Named Contact (15)","Indie Adds (15)","Clock Fit (10)","Counter Prog (10)","Total (100)","Tier Rank"],"rows":[["WNUR 89.3 FM (Chicago)","28","20","15","15","10","8","96","Tier 1 (Priority)"],["WLUW 88.7 FM (Chicago)","30","20","15","15","10","6","96","Tier 1 (Priority)"],["WMSE 91.7 FM (Milwaukee)","26","15","15","12","10","7","85","Tier 1 (Priority)"],["WXRT 93.1 FM (Commercial AAA)","22","20","15","8","10","5","80","Tier 2 (Secondary)"],["WKQX 101.1 FM (Alt Commercial)","15","20","10","4","10","4","63","Tier 3 (Hold)"]]}],"confirmations":[{"id":"community","text":"One community drill answered (optional but strengthens calibration).","required":false}]}', '{"policy":"all-responses-min-words","minWords":40,"requireAllDrills":true,"requireWorksheetCells":0,"note":""}', '[{"to":"/frequency-dominion/app/heatmap","label":"Heat Map workspace"},{"to":"/frequency-dominion/app/stations","label":"Station War Room"}]', 'courses/frequency-dominion/frequency-dominion-course.zip', 1, strftime('%Y-%m-%dT%H:%M:%SZ','now'), strftime('%Y-%m-%dT%H:%M:%SZ','now'))
       ON CONFLICT(id) DO UPDATE SET module_id=excluded.module_id, code=excluded.code, title=excluded.title, minutes=excluded.minutes, exercise_minutes=excluded.exercise_minutes, position=excluded.position, truth=excluded.truth, masterclass_json=excluded.masterclass_json, field_protocol_json=excluded.field_protocol_json, warnings_json=excluded.warnings_json, decoder_json=excluded.decoder_json, worksheets_json=excluded.worksheets_json, community_json=excluded.community_json, exercise_json=excluded.exercise_json, pass_json=excluded.pass_json, tool_links_json=excluded.tool_links_json, version=lessons.version+1, updated_at=strftime('%Y-%m-%dT%H:%M:%SZ','now');
INSERT INTO lessons (id, module_id, code, title, minutes, exercise_minutes, position, published, truth, masterclass_json, field_protocol_json, warnings_json, decoder_json, worksheets_json, community_json, exercise_json, pass_json, tool_links_json, print_asset, version, created_at, updated_at)
       VALUES ('m2l4', 'm2', '2.4', 'The 20-Station War Room — Build the Command Center That Never Sleeps', 8, 100, 3, 1, 'Dominion is concentration of force. A locked war room of 20 scored, personalized stations will produce 5x more adds than an undisciplined database of 500 names.', '[{"b":"h","level":3,"spans":[{"t":"text","v":"Strategic Foundation & Operational Reality"}]},{"b":"p","spans":[{"t":"text","v":"Amateur artists believe that successful radio promotion is a numbers game governed by sheer volume. They buy contact lists of 5,000 email addresses, copy-paste a generic pitch, and hit send. Within 72 hours, their email deliverability collapses, zero meaningful adds materialize, and the artist collapses in exhaustion, convinced that radio is an impenetrable cartel."}]},{"b":"p","spans":[{"t":"text","v":"Dominion operators operate under the military principle of "},{"t":"b","v":"Concentration of Force"},{"t":"text","v":"."}]},{"b":"p","spans":[{"t":"text","v":"Instead of spreading thin across hundreds of unvetted contacts, you concentrate your operational bandwidth on a tightly curated "},{"t":"b","v":"20-Station War Room"},{"t":"text","v":". Twenty stations is the exact mathematical sweet spot for an independent operator:"}]},{"b":"list","ordered":false,"items":[{"spans":[{"t":"text","v":"Large enough to guarantee statistical airplay yield (a 20% to 30% add conversion rate yields 4 to 6 solid station adds)."}]},{"spans":[{"t":"text","v":"Small enough that every single gatekeeper receives deep, tailored personalization, individual track analysis, and meticulous multi-touch follow-up."}]},{"spans":[{"t":"text","v":"Fully manageable within 45 minutes of daily operational execution."}]}]},{"b":"h","level":3,"spans":[{"t":"text","v":"The Anatomy of the 20-Station War Room"}]},{"b":"p","spans":[{"t":"text","v":"Your War Room is not a passive spreadsheet; it is an active tactical cockpit. Every station in your War Room advances through a rigid "},{"t":"b","v":"6-Stage Lifecycle Ladder"},{"t":"text","v":":"}]},{"b":"list","ordered":true,"items":[{"spans":[{"t":"b","v":"Queued (Stage 1):"},{"t":"text","v":" Scored >= 75 points. Named gatekeeper verified. 3-layer subject line drafted. Audio package staged."}]},{"spans":[{"t":"b","v":"Dispatched (Stage 2):"},{"t":"text","v":" Touch 1 payload delivered during optimal morning programming window. Timestamp logged."}]},{"spans":[{"t":"b","v":"Engaged / Opened (Stage 3):"},{"t":"text","v":" Payload opened or link clicked. Monitored via privacy-compliant analytics."}]},{"spans":[{"t":"b","v":"Dialogue / In Review (Stage 4):"},{"t":"text","v":" Gatekeeper replied, requested assets, or acknowledged submission. Immediate high-value reply dispatched."}]},{"spans":[{"t":"b","v":"Confirmed Add / Spin (Stage 5):"},{"t":"text","v":" Track placed in rotation, scheduled for specialty play, or booked for an on-air interview. Spinitron confirmation captured."}]},{"spans":[{"t":"b","v":"Retired / Re-Check (Stage 6):"},{"t":"text","v":" Polite decline received, or 3-touch sequence completed without engagement. Transferred to 90-day re-check calendar."}]}]},{"b":"h","level":3,"spans":[{"t":"text","v":"The Daily 45-Minute Battle Rhythm"}]},{"b":"p","spans":[{"t":"text","v":"To operate your War Room with peak efficiency, execute this daily protocol four days per week (Monday through Thursday):"}]},{"b":"list","ordered":false,"items":[{"spans":[{"t":"i","v":"Minute 0 – 10 (Reconnaissance):"},{"t":"text","v":" Review Spinitron and playlist logs for target stations to check for spontaneous spins. Log all incoming replies."}]},{"spans":[{"t":"i","v":"Minute 10 – 25 (Execution Wave):"},{"t":"text","v":" Dispatch scheduled Touch 1 initial sends or Touch 2/3 follow-ups strictly per the campaign calendar."}]},{"spans":[{"t":"i","v":"Minute 25 – 40 (Asset & Dialogue Response):"},{"t":"text","v":" Respond to programmer inquiries, provide clean broadcast WAV files, coordinate interview windows, and dispatch custom station sweepers."}]},{"spans":[{"t":"i","v":"Minute 40 – 45 (Ledger Reconciliation):"},{"t":"text","v":" Update every status column, log next-touch dates, and audit pipeline velocity."}]}]}]', '[{"b":"p","spans":[{"t":"b","v":"WAR-ROOM DIRECTIVE — 2.4 The 20-Station War Room — Build the Command Center That Never Sleeps"}]},{"b":"p","spans":[{"t":"b","v":"NEVER EXPAND BEYOND 20 UNTIL 20 ARE CONVERTED OR RETIRED"},{"t":"text","v":" The fatal operational failure of independent operators is pipeline creep. They start with 20 stations, get excited, add 50 more, lose track of follow-up dates, send Touch 2 twelve days late, fail to log replies, and collapse the entire system into chaotic noise."}]},{"b":"p","spans":[{"t":"b","v":"THE OPERATOR''S DISCIPLINE:"}]},{"b":"list","ordered":true,"items":[{"spans":[{"t":"b","v":"The 20-Cap Rule:"},{"t":"text","v":" You are prohibited from adding station #21 until one of your active 20 stations either confirms an add (graduating to the Thank-You & Proof compounding loops) or completes Touch 3 and enters the 90-day cold archive."}]},{"spans":[{"t":"b","v":"Visual Command:"},{"t":"text","v":" Print your 20-Station War Room Cockpit and physically mount it to your studio wall. Marking stations from "},{"t":"i","v":"Dispatched"},{"t":"text","v":" to "},{"t":"i","v":"Dialogue"},{"t":"text","v":" to "},{"t":"i","v":"Confirmed Add"},{"t":"text","v":" with a physical marker creates psychological momentum that digital spreadsheets cannot replicate. <!-- WARROOM:END -->"}]}]}]', '["# 2.4 The 20-Station War Room — Build the Command Center That Never Sleeps > THE ONE-LINE TRUTH: Dominion is concentration of force."]', '["The mechanic: concentration beats breadth.","The missing piece: allocate by outcome — 10 slot shops (college/specialty), 6 ladder shops (can upgrade you), 3 market-makers, 1 wildcard.","The operator move: keep the war room to exactly 20 rows even when the map grows. Growth = new campaigns, not bigger rows."]', '[{"kind":"note","blocks":[{"b":"p","spans":[{"t":"text","v":"Complete the structured table below as part of your lesson implementation. This worksheet directly replaces legacy spreadsheets with a publication-grade execution protocol."}]}]},{"kind":"table","title":"20-STATION WAR ROOM OPERATIONAL COCKPIT","headers":["Station Callsign","Metro & Dial","Format & Program","Decision Maker","Current Status","Last Touch Date","Next Scheduled Action","Verification Source"],"rows":[["WLUW 88.7 FM","Chicago, IL","Indie Rock / Drive","Sarah Jenkins (MD)","Queued","Pending Day 1","Launch Touch 1 @ 9:30 AM","Station Staff Directory"],["WNUR 89.3 FM","Evanston, IL","Progressive / Night","Alex Rivera (MD)","Queued","Pending Day 1","Launch Touch 1 @ 9:30 AM","Direct Email Verified"],["WMSE 91.7 FM","Milwaukee, WI","AAA / Local Focus","Tom Crawford (PD)","Queued","Pending Day 3","Stage Touch 1 Wave 2","Spinitron Contact Header"],["KUTX 98.9 FM","Austin, TX","Eclectic College","Rick McNulty (MD)","Queued","Pending Day 3","Stage Touch 1 Wave 2","KUTX Music Submission Page"],["WXPN 88.5 FM","Philadelphia, PA","AAA / World Cafe","Bruce Warren (PD)","Queued","Pending Day 3","Specialty Host Pitch Prep","Direct Programming Directory"]]}]', '["Post a screenshot or transcript of your 20-Station War Room Cockpit roster.","Identify which 3 stations in your War Room represent your highest-conviction airplay opportunities.","State your confirmed Launch Day (Day 1) date when Touch 1 dispatches to your first wave.","Commit to the 45-Minute Daily Battle Rhythm by sharing the exact time block scheduled in your calendar."]', '{"kind":"field-exercise","prompt":"Complete every drill below with real, verifiable answers, then confirm the pass standard.","items":[{"id":"d1","label":"War Room Target Lockdown","description":"War Room Target Lockdown . Review your Hometown Heat Map and Format Scorecards. Select your definitive 20 stations (12 Tier-1 priority targets, 8 Tier-2 regional targets). Populate the War Room Cockpit Worksheet below.","minutes":45,"type":"response","passStandard":null},{"id":"d2","label":"Gatekeeper Verification Sweep","description":"Gatekeeper Verification Sweep . Verify the direct email address and exact professional title of the music director or specialty show host for all 20 stations. Zero generic emails permitted.","minutes":30,"type":"response","passStandard":null},{"id":"d3","label":"The Status Board Initialization","description":"The Status Board Initialization . Confirm that all 20 stations are classified as ''Queued'' with scheduled launch dates locked into your calendar.","minutes":15,"type":"response","passStandard":null},{"id":"d4","label":"Accountability Partnership Activation","description":"Accountability Partnership Activation . Share your 20-Station War Room roster with one trusted peer or community accountability partner.","minutes":10,"type":"response","passStandard":null}],"worksheets":[{"kind":"table","title":"20-STATION WAR ROOM OPERATIONAL COCKPIT","headers":["Station Callsign","Metro & Dial","Format & Program","Decision Maker","Current Status","Last Touch Date","Next Scheduled Action","Verification Source"],"rows":[["WLUW 88.7 FM","Chicago, IL","Indie Rock / Drive","Sarah Jenkins (MD)","Queued","Pending Day 1","Launch Touch 1 @ 9:30 AM","Station Staff Directory"],["WNUR 89.3 FM","Evanston, IL","Progressive / Night","Alex Rivera (MD)","Queued","Pending Day 1","Launch Touch 1 @ 9:30 AM","Direct Email Verified"],["WMSE 91.7 FM","Milwaukee, WI","AAA / Local Focus","Tom Crawford (PD)","Queued","Pending Day 3","Stage Touch 1 Wave 2","Spinitron Contact Header"],["KUTX 98.9 FM","Austin, TX","Eclectic College","Rick McNulty (MD)","Queued","Pending Day 3","Stage Touch 1 Wave 2","KUTX Music Submission Page"],["WXPN 88.5 FM","Philadelphia, PA","AAA / World Cafe","Bruce Warren (PD)","Queued","Pending Day 3","Specialty Host Pitch Prep","Direct Programming Directory"]]}],"confirmations":[{"id":"community","text":"One community drill answered (optional but strengthens calibration).","required":false}]}', '{"policy":"all-responses-min-words","minWords":40,"requireAllDrills":true,"requireWorksheetCells":0,"note":""}', '[{"to":"/frequency-dominion/app/heatmap","label":"Heat Map workspace"},{"to":"/frequency-dominion/app/stations","label":"Station War Room"}]', 'courses/frequency-dominion/frequency-dominion-course.zip', 1, strftime('%Y-%m-%dT%H:%M:%SZ','now'), strftime('%Y-%m-%dT%H:%M:%SZ','now'))
       ON CONFLICT(id) DO UPDATE SET module_id=excluded.module_id, code=excluded.code, title=excluded.title, minutes=excluded.minutes, exercise_minutes=excluded.exercise_minutes, position=excluded.position, truth=excluded.truth, masterclass_json=excluded.masterclass_json, field_protocol_json=excluded.field_protocol_json, warnings_json=excluded.warnings_json, decoder_json=excluded.decoder_json, worksheets_json=excluded.worksheets_json, community_json=excluded.community_json, exercise_json=excluded.exercise_json, pass_json=excluded.pass_json, tool_links_json=excluded.tool_links_json, version=lessons.version+1, updated_at=strftime('%Y-%m-%dT%H:%M:%SZ','now');
INSERT INTO lessons (id, module_id, code, title, minutes, exercise_minutes, position, published, truth, masterclass_json, field_protocol_json, warnings_json, decoder_json, worksheets_json, community_json, exercise_json, pass_json, tool_links_json, print_asset, version, created_at, updated_at)
       VALUES ('m3l1', 'm3', '3.1', 'Subject Lines That Cut Through Noise — The 30-Formula Vault', 8, 75, 0, 1, 'A music director decides whether to open your submission in 1.4 seconds. Your subject line is not a creative headline — it is an operational routing code.', '[{"b":"h","level":3,"spans":[{"t":"text","v":"Strategic Foundation & Operational Reality"}]},{"b":"p","spans":[{"t":"text","v":"A radio station music director''s inbox is a battlefield of unread clutter. Between 7:00 AM and 11:00 AM every Tuesday morning, 400 new emails flood the gatekeeper''s inbox. Over 80% of these emails carry generic, amateurish subject lines:"}]},{"b":"list","ordered":false,"items":[{"spans":[{"t":"i","v":"\"New single for your consideration!\""}]},{"spans":[{"t":"i","v":"\"Check out this hot new track from an upcoming artist\""}]},{"spans":[{"t":"i","v":"\"MUSIC SUBMISSION: Band Name - Song Title (Indie/Rock)\""}]},{"spans":[{"t":"i","v":"\"Hey! Love your station, please listen to my record\""}]}]},{"b":"p","spans":[{"t":"text","v":"These subject lines are deleted without opening. Why? Because they communicate zero context, zero technical parameters, and demand that the programmer spend their own scarce time guessing what the payload contains."}]},{"b":"p","spans":[{"t":"text","v":"Dominion operators treat the subject line as an "},{"t":"b","v":"Operational Routing Code"},{"t":"text","v":"."}]},{"b":"p","spans":[{"t":"text","v":"A high-converting subject line proves three things before the programmer ever clicks open:"}]},{"b":"list","ordered":true,"items":[{"spans":[{"t":"text","v":"You know exactly who they are and what specific program block they curate."}]},{"spans":[{"t":"text","v":"You know their technical clock parameters (genre, BPM, run-time)."}]},{"spans":[{"t":"text","v":"You bring verifiable regional relevance or immediate broadcast proof."}]}]},{"b":"h","level":3,"spans":[{"t":"text","v":"The Three-Layer Personalization Engine"}]},{"b":"p","spans":[{"t":"text","v":"Every elite radio subject line combines three specific data layers:"}]},{"b":"list","ordered":false,"items":[{"spans":[{"t":"b","v":"Layer 1: Individual Gatekeeper / Show Targeting:"},{"t":"text","v":" Names the specific programmer, specialty show, or station callsign (e.g., "},{"t":"code","v":"For Sarah / WXRT Local Anesthetic:"},{"t":"text","v":")."}]},{"spans":[{"t":"b","v":"Layer 2: Technical Clock & Format Specification:"},{"t":"text","v":" Provides exact run-time, BPM, and sub-genre fit (e.g., "},{"t":"code","v":"Indie-PostPunk · 2:58 · 124 BPM"},{"t":"text","v":")."}]},{"spans":[{"t":"b","v":"Layer 3: The Unassailable Proof or Local Anchor:"},{"t":"text","v":" Cites upcoming local tour date, hometown origin, or existing broadcast validation (e.g., "},{"t":"code","v":"Metro Chicago 10/14 · Added KEXP"},{"t":"text","v":")."}]}]},{"b":"p","spans":[{"t":"text","v":"When assembled, the resulting subject line reads like a tailored internal memo rather than cold spam: "},{"t":"code","v":"For Sarah / WXRT: Chicago Indie-Rock (2:58 / 124 BPM) · Metro Date 10/14 · Added KEXP"}]},{"b":"h","level":3,"spans":[{"t":"text","v":"Core Subject Line Archetypes That Force Opens"}]},{"b":"list","ordered":true,"items":[{"spans":[{"t":"b","v":"The Regional Tour Anchor:"},{"t":"text","v":" "},{"t":"code","v":"[City] Indie-Pop for [Show Name]: [Run-time] · Live at [Venue] [Date]"}]},{"spans":[{"t":"b","v":"The Clock & Format Twin:"},{"t":"text","v":" "},{"t":"code","v":"[Station Callsign] Specialty Add: [Genre] (Clean Edit · 3:04 · 120 BPM)"}]},{"spans":[{"t":"b","v":"The Compounding Proof Cascade:"},{"t":"text","v":" "},{"t":"code","v":"Added at [Station 1] & [Station 2] · [Genre] (2:49) for [Gatekeeper Name]"}]},{"spans":[{"t":"b","v":"The Direct Local Origin:"},{"t":"text","v":" "},{"t":"code","v":"Hometown [City] [Genre] for [Show Name] · 2:56 Radio Edit · [Proof Point]"}]}]}]', '[{"b":"p","spans":[{"t":"b","v":"WAR-ROOM DIRECTIVE — 3.1 Subject Lines That Cut Through Noise — The 30-Formula Vault"}]},{"b":"p","spans":[{"t":"b","v":"THE MOBILE TRUNCATION TRAP"},{"t":"text","v":" Over 70% of radio programmers review pitches on their smartphones during transit, between meetings, or while standing in the studio control room. On iOS Mail and mobile Gmail, any subject line exceeding 45 characters gets truncated with ellipses."}]},{"b":"p","spans":[{"t":"b","v":"HOW TO ENGINEER FOR MOBILE SURVIVAL:"}]},{"b":"list","ordered":true,"items":[{"spans":[{"t":"b","v":"Front-Load the High-Value Signal:"},{"t":"text","v":" Put the programmer''s name, station callsign, and format at the very front of the line."}]},{"spans":[{"t":"i","v":"Bad:"},{"t":"text","v":" "},{"t":"code","v":"Check out the new single from Chicago alternative band The Replicas for WXRT review"},{"t":"text","v":" (truncated to "},{"t":"code","v":"Check out the new single from Chicago alternative..."},{"t":"text","v":" — deleted immediately)."}]},{"spans":[{"t":"i","v":"Dominion Standard:"},{"t":"text","v":" "},{"t":"code","v":"For Sarah / WXRT: Chicago Indie (2:58) · Metro 10/14"},{"t":"text","v":" (gatekeeper sees their name, their station, genre, run-time, and local show immediately)."}]},{"spans":[{"t":"b","v":"Never Use All-Caps or Emojis:"},{"t":"text","v":" Programmers associate emojis (🔥, 🚀, 🎵) and capitalized exclamation marks with desperate spam bots and consumer marketing blasts. Clinical typography communicates enterprise competence. <!-- WARROOM:END -->"}]}]}]', '["Never Use All-Caps or Emojis: Programmers associate emojis (🔥, 🚀, 🎵) and capitalized exclamation marks with desperate spam bots and consumer marketing blasts."]', '["The mechanic: 1.4 seconds, one engine.","The missing piece: the subject line that wins is station-type matched — proof lines for commercial, format-line references for specialty, name-drops for established contacts.","The operator move: log every subject by station type. After two campaigns you''ll have a personal playbook that beats any generic list."]', '[{"kind":"note","blocks":[{"b":"p","spans":[{"t":"text","v":"Complete the structured table below as part of your lesson implementation. This worksheet directly replaces legacy spreadsheets with a publication-grade execution protocol."}]}]},{"kind":"table","title":"SUBJECT LINE ARCHITECTURE & TESTING LOG","headers":["Target Station & MD","Formula Archetype","Layer 1 (Target)","Layer 2 (Technical)","Layer 3 (Proof/Local)","Full Assembled Subject Line"],"rows":[["WLUW 88.7 (Sarah)","Regional Tour Anchor","For Sarah / WLUW","Indie-Rock (3:08 / 120 BPM)","Lincoln Hall Date 10/18","For Sarah / WLUW: Chicago Indie (3:08) · Lincoln Hall 10/18"],["WNUR 89.3 (Alex)","Clock & Format Twin","WNUR Specialty Add","Post-Punk (2:54 / 126 BPM)","FCC Clean Broadcast WAV","WNUR Specialty: Post-Punk (2:54 · Clean WAV) · Evanston Local"],["WMSE 91.7 (Tom)","Compounding Proof","For Tom / WMSE","Alt-Country (3:12)","Spins on WXPN & KUTX","For Tom / WMSE: Alt-Country (3:12) · Added WXPN & KUTX"],["Radio K (Marcus)","Regional Tour Anchor","Radio K Local Block","Dream-Pop (3:02)","7th St Entry Date 10/22","Radio K Feature: Dream-Pop (3:02) · Live @ 7th St Entry 10/22"],["KUTX 98.9 (Rick)","Hometown Anchor","For Rick / KUTX","Austin Psych-Rock (2:49)","Barracuda Date / ACL Fest","For Rick / KUTX: Austin Psych-Rock (2:49) · Fall Residency Hook"]]}]', '["Post your 3 strongest customized subject lines. Community members will evaluate them on mobile truncation and punch.","Share the formula archetype that produced your highest open rate in past campaigns.","Which subject line element (local date, run-time, or prior add) do you believe gives you the sharpest competitive edge?","Commit to your A/B test parameters for your upcoming 20-station launch wave."]', '{"kind":"field-exercise","prompt":"Complete every drill below with real, verifiable answers, then confirm the pass standard.","items":[{"id":"d1","label":"The Subject Line Autopsy","description":"The Subject Line Autopsy . Review every subject line you have used in your music career. Identify every instance of generic phrasing (''for your consideration'', ''check out'', ''new music''). Permanently retire them.","minutes":15,"type":"response","passStandard":null},{"id":"d2","label":"The 3-Layer Construction Sprint","description":"The 3-Layer Construction Sprint . Draft 10 customized 3-layer subject lines for your top 10 War Room stations using the Subject Line Matrix below.","minutes":30,"type":"response","passStandard":null},{"id":"d3","label":"The 1.4-Second Character Economy Test","description":"The 1.4-Second Character Economy Test . Test all 10 subject lines against a mobile preview screen (under 45 characters on primary display). Ensure the gatekeeper name, format, and run-time remain visible before truncation.","minutes":15,"type":"response","passStandard":null},{"id":"d4","label":"The A/B Testing Cohort Lock","description":"The A/B Testing Cohort Lock . Divide your 20 War Room stations into two cohorts of 10. Select two distinct subject line formulas (e.g., Regional Tour Anchor vs. Clock & Format Twin) to test open and reply rates.","minutes":15,"type":"response","passStandard":null}],"worksheets":[{"kind":"table","title":"SUBJECT LINE ARCHITECTURE & TESTING LOG","headers":["Target Station & MD","Formula Archetype","Layer 1 (Target)","Layer 2 (Technical)","Layer 3 (Proof/Local)","Full Assembled Subject Line"],"rows":[["WLUW 88.7 (Sarah)","Regional Tour Anchor","For Sarah / WLUW","Indie-Rock (3:08 / 120 BPM)","Lincoln Hall Date 10/18","For Sarah / WLUW: Chicago Indie (3:08) · Lincoln Hall 10/18"],["WNUR 89.3 (Alex)","Clock & Format Twin","WNUR Specialty Add","Post-Punk (2:54 / 126 BPM)","FCC Clean Broadcast WAV","WNUR Specialty: Post-Punk (2:54 · Clean WAV) · Evanston Local"],["WMSE 91.7 (Tom)","Compounding Proof","For Tom / WMSE","Alt-Country (3:12)","Spins on WXPN & KUTX","For Tom / WMSE: Alt-Country (3:12) · Added WXPN & KUTX"],["Radio K (Marcus)","Regional Tour Anchor","Radio K Local Block","Dream-Pop (3:02)","7th St Entry Date 10/22","Radio K Feature: Dream-Pop (3:02) · Live @ 7th St Entry 10/22"],["KUTX 98.9 (Rick)","Hometown Anchor","For Rick / KUTX","Austin Psych-Rock (2:49)","Barracuda Date / ACL Fest","For Rick / KUTX: Austin Psych-Rock (2:49) · Fall Residency Hook"]]}],"confirmations":[{"id":"community","text":"One community drill answered (optional but strengthens calibration).","required":false}]}', '{"policy":"all-responses-min-words","minWords":40,"requireAllDrills":true,"requireWorksheetCells":0,"note":""}', '[{"to":"/frequency-dominion/app/vault","label":"Pitch & subject-line tools"}]', 'courses/frequency-dominion/frequency-dominion-course.zip', 1, strftime('%Y-%m-%dT%H:%M:%SZ','now'), strftime('%Y-%m-%dT%H:%M:%SZ','now'))
