INSERT INTO lessons (id, module_id, code, title, minutes, exercise_minutes, position, published, truth, masterclass_json, field_protocol_json, warnings_json, decoder_json, worksheets_json, community_json, exercise_json, pass_json, tool_links_json, print_asset, version, created_at, updated_at)
       VALUES ('m3l2', 'm3', '3.2', 'The 90-Word Pitch — The Only Email That Matters', 8, 65, 1, 1, 'A music director reads your pitch for four seconds. The 90-word pitch is an operational payload — delivering maximum technical clarity, proof, and a single frictionless ask.', '[{"b":"h","level":3,"spans":[{"t":"text","v":"Strategic Foundation & Operational Reality"}]},{"b":"p","spans":[{"t":"text","v":"The default instinct of musicians is to tell their life story. They write sprawling 500-word biographies explaining their childhood musical influences, their spiritual awakening in the recording studio, their creative philosophy, and detailed track-by-track analyses."}]},{"b":"p","spans":[{"t":"text","v":"A radio programmer will not read an essay. They have 4 seconds of initial visual patience. If your email requires scrolling on a mobile device to locate the listening link or the core proposition, your submission is dead on arrival."}]},{"b":"p","spans":[{"t":"text","v":"The "},{"t":"b","v":"90-Word Pitch"},{"t":"text","v":" is an engineered communication weapon. It strips away all narrative fluff, artistic posturing, and emotional pleading. It delivers an unassailable commercial proposition structured in six modular blocks."}]},{"b":"h","level":3,"spans":[{"t":"text","v":"The Six-Block Modular Anatomy (Strictly Under 90 Words)"}]},{"b":"list","ordered":true,"items":[{"spans":[{"t":"b","v":"Block 1: Personal Salutation & Show Identification (10 words):"},{"t":"text","v":" Confirms you know the recipient and target their specific show: "},{"t":"i","v":"\"Hi [Name] — caught your Sunday specialty spotlight on [Station]; loved the [Artist] spin.\""}]},{"spans":[{"t":"b","v":"Block 2: Immediate Local or Format Rationale (15 words):"},{"t":"text","v":" States why this record belongs on their frequency this week: "},{"t":"i","v":"\"Targeting your evening indie rotation with our new Chicago release, ''[Song Title]''.\""}]},{"spans":[{"t":"b","v":"Block 3: One-Sentence Sonic Hook & Run-Time (18 words):"},{"t":"text","v":" Clean comparative reference and clock fit: "},{"t":"i","v":"\"High-energy post-punk driven by angular guitars (2:56 run-time, 126 BPM, FCC clean broadcast mix).\""}]},{"spans":[{"t":"b","v":"Block 4: The Undeniable Proof Receipt (17 words):"},{"t":"text","v":" Concrete third-party validation: "},{"t":"i","v":"\"Currently in rotation on WNUR; headlining Empty Bottle on October 14th (250 cap, 80% advance).\""}]},{"spans":[{"t":"b","v":"Block 5: Frictionless Streaming Link (8 words):"},{"t":"text","v":" One dedicated private streaming link with zero download walls: "},{"t":"i","v":"\"Stream & Broadcast WAV: [Short Private Link]\""}]},{"spans":[{"t":"b","v":"Block 6: The Single, Low-Risk Ask (14 words):"},{"t":"text","v":" One single call to action — never ask for three things at once: "},{"t":"i","v":"\"Open to considering this for next week''s specialty add or an upcoming show feature?\""}]}]},{"b":"h","level":3,"spans":[{"t":"text","v":"Total Word Count: Exactly 82 Words."}]},{"b":"p","spans":[{"t":"text","v":"Notice what is absent:"}]},{"b":"list","ordered":false,"items":[{"spans":[{"t":"text","v":"No requests for their phone number or general life feedback."}]},{"spans":[{"t":"text","v":"No demands that they add you to heavy daytime rotation immediately."}]},{"spans":[{"t":"text","v":"No 50MB attachments that crash corporate inboxes."}]},{"spans":[{"t":"text","v":"Just clean, respectful, surgical B2B communication."}]}]}]', '[{"b":"p","spans":[{"t":"b","v":"WAR-ROOM DIRECTIVE — 3.2 The 90-Word Pitch — The Only Email That Matters"}]},{"b":"p","spans":[{"t":"b","v":"NEVER ATTACH AUDIO FILES TO COLD TOUCH 1 EMAILS"},{"t":"text","v":" One of the fastest ways to guarantee your email is never seen is attaching an MP3 or WAV file to your initial email. Enterprise mail servers for universities, public broadcasters, and commercial radio networks automatically quarantine incoming emails with external attachments over 5MB or from unverified domains."}]},{"b":"p","spans":[{"t":"b","v":"THE OPERATOR''S LINK ARCHITECTURE:"}]},{"b":"list","ordered":true,"items":[{"spans":[{"t":"b","v":"The Clean Private Link:"},{"t":"text","v":" Use a single, custom, clean private link (e.g., a branded private Soundcloud, DISCO, or clean Dropbox link)."}]},{"spans":[{"t":"b","v":"The Stream + Download Hybrid:"},{"t":"text","v":" Ensure the destination page allows the programmer to stream the track instantly with one click "},{"t":"i","v":"and"},{"t":"text","v":" provides a direct \"Download High-Res WAV\" button with complete broadcast metadata."}]},{"spans":[{"t":"b","v":"Never Use Expirable File Transfers:"},{"t":"text","v":" Sending a WeTransfer link that expires in 7 days is amateur suicide. Programmers frequently review candidate queues 10 to 14 days after initial receipt. When they click an expired WeTransfer link, your submission is permanently dead. <!-- WARROOM:END -->"}]}]}]', '["Never Use Expirable File Transfers: Sending a WeTransfer link that expires in 7 days is amateur suicide."]', '["The mechanic: 4-second stack, one ask.","The missing piece: the reply you want is a question — \"send the WAV?\" is an 80%-made yes.","The operator move: answer any PD question within 4 hours with a phone number and a 12-minute call offer. Speed here is the proof of professionalism."]', '[{"kind":"note","blocks":[{"b":"p","spans":[{"t":"text","v":"Complete the structured table below as part of your lesson implementation. This worksheet directly replaces legacy spreadsheets with a publication-grade execution protocol."}]}]},{"kind":"table","title":"90-WORD PITCH MODULAR BUILDER","headers":["Modular Block","Target Objective","Word Count Limit","Your Draft Copy","Compliance Pass/Fail"],"rows":[["Block 1: Salutation","Direct human name & show mention","10 words max","Hi Sarah — loved your Sunday local feature on WXRT.","PASS (10 words)"],["Block 2: Target Rationale","State specific show / format target","15 words max","Submitting our new single ''[Track]'' for your evening specialty block.","PASS (11 words)"],["Block 3: Sonic Hook & Clock","Genre, BPM, run-time, clean tag","20 words max","Driving Midwest indie-rock (2:58 / 122 BPM / FCC Clean Master).","PASS (10 words)"],["Block 4: Proof Receipt","Cite station add, ticket date, or press","20 words max","Currently spinning on WNUR; headlining Metro Chicago on October 18th.","PASS (11 words)"],["Block 5: Frictionless Link","One streaming + broadcast WAV link","10 words max","Listen & Download Broadcast WAV: [Private Link]","PASS (6 words)"],["Block 6: The Single Ask","Clear, low-risk, courteous question","15 words max","Would you consider this for next week''s local add queue?","PASS (10 words)"]]}]', '["Post your complete 90-Word Pitch. Verify your official word count in parentheses at the bottom.","Roast a peer''s pitch draft for word count bloat, emotional language, or compound asks.","Share your chosen streaming platform destination (DISCO, SoundCloud, or private landing page) and explain why it provides the lowest listening friction.","Confirm that your pitch passes the 15-Second Spoken Cadence Test."]', '{"kind":"field-exercise","prompt":"Complete every drill below with real, verifiable answers, then confirm the pass standard.","items":[{"id":"d1","label":"The Brutal 90-Word Redaction","description":"The Brutal 90-Word Redaction . Take your existing email pitch. Paste it into a word counter. Aggressively strike every extraneous adjective, autobiographical sentence, and duplicate link until the entire text sits under 90 words.","minutes":30,"type":"response","passStandard":null},{"id":"d2","label":"The Out-Loud 15-Second Cadence Test","description":"The Out-Loud 15-Second Cadence Test . Read your revised pitch aloud at a normal conversational pace. You must be able to complete the entire reading in under 22 seconds without stumbling.","minutes":10,"type":"response","passStandard":null},{"id":"d3","label":"The Single Ask Alignment","description":"The Single Ask Alignment . Audit your closing sentence. Ensure it makes exactly ONE ask (e.g., specialty show consideration OR interview window). Delete any compound requests.","minutes":10,"type":"response","passStandard":null},{"id":"d4","label":"The Mobile Visual Hierarchy Check","description":"The Mobile Visual Hierarchy Check . Send the draft pitch to your personal smartphone. Verify that the greeting, sonic hook, proof line, and streaming link are 100% visible on a single screen without finger scrolling.","minutes":15,"type":"response","passStandard":null}],"worksheets":[{"kind":"table","title":"90-WORD PITCH MODULAR BUILDER","headers":["Modular Block","Target Objective","Word Count Limit","Your Draft Copy","Compliance Pass/Fail"],"rows":[["Block 1: Salutation","Direct human name & show mention","10 words max","Hi Sarah — loved your Sunday local feature on WXRT.","PASS (10 words)"],["Block 2: Target Rationale","State specific show / format target","15 words max","Submitting our new single ''[Track]'' for your evening specialty block.","PASS (11 words)"],["Block 3: Sonic Hook & Clock","Genre, BPM, run-time, clean tag","20 words max","Driving Midwest indie-rock (2:58 / 122 BPM / FCC Clean Master).","PASS (10 words)"],["Block 4: Proof Receipt","Cite station add, ticket date, or press","20 words max","Currently spinning on WNUR; headlining Metro Chicago on October 18th.","PASS (11 words)"],["Block 5: Frictionless Link","One streaming + broadcast WAV link","10 words max","Listen & Download Broadcast WAV: [Private Link]","PASS (6 words)"],["Block 6: The Single Ask","Clear, low-risk, courteous question","15 words max","Would you consider this for next week''s local add queue?","PASS (10 words)"]]}],"confirmations":[{"id":"community","text":"One community drill answered (optional but strengthens calibration).","required":false}]}', '{"policy":"all-responses-min-words","minWords":40,"requireAllDrills":true,"requireWorksheetCells":0,"note":""}', '[{"to":"/frequency-dominion/app/vault","label":"Pitch & subject-line tools"}]', 'courses/frequency-dominion/frequency-dominion-course.zip', 1, strftime('%Y-%m-%dT%H:%M:%SZ','now'), strftime('%Y-%m-%dT%H:%M:%SZ','now'))
       ON CONFLICT(id) DO UPDATE SET module_id=excluded.module_id, code=excluded.code, title=excluded.title, minutes=excluded.minutes, exercise_minutes=excluded.exercise_minutes, position=excluded.position, truth=excluded.truth, masterclass_json=excluded.masterclass_json, field_protocol_json=excluded.field_protocol_json, warnings_json=excluded.warnings_json, decoder_json=excluded.decoder_json, worksheets_json=excluded.worksheets_json, community_json=excluded.community_json, exercise_json=excluded.exercise_json, pass_json=excluded.pass_json, tool_links_json=excluded.tool_links_json, version=lessons.version+1, updated_at=strftime('%Y-%m-%dT%H:%M:%SZ','now');
INSERT INTO lessons (id, module_id, code, title, minutes, exercise_minutes, position, published, truth, masterclass_json, field_protocol_json, warnings_json, decoder_json, worksheets_json, community_json, exercise_json, pass_json, tool_links_json, print_asset, version, created_at, updated_at)
       VALUES ('m3l3', 'm3', '3.3', 'The One-Page EPK That Commands Attention', 8, 90, 2, 1, 'Your Electronic Press Kit is not a promotional brochure — it is a single-screen Command Deck designed to give a gatekeeper all critical operational facts in 20 seconds.', '[{"b":"h","level":3,"spans":[{"t":"text","v":"Strategic Foundation & Operational Reality"}]},{"b":"p","spans":[{"t":"text","v":"The traditional independent artist Electronic Press Kit (EPK) is a catastrophic failure of information architecture. Artists assemble multi-page PDF documents packed with high-resolution 10MB photo collages, extensive poetic philosophical essays on their upbringing, broken YouTube video embeds, and convoluted quote walls."}]},{"b":"p","spans":[{"t":"text","v":"No working radio programmer, festival talent buyer, or music journalist has ever read a 12-page EPK."}]},{"b":"p","spans":[{"t":"text","v":"In the Dominion operating doctrine, your EPK is a "},{"t":"b","v":"One-Page Command Deck"},{"t":"text","v":". It is engineered for a gatekeeper operating under extreme time pressure. A music director must be able to glance at your Command Deck and absorb six critical data blocks in under 20 seconds without zooming, panning, or navigating complex sub-menus."}]},{"b":"h","level":3,"spans":[{"t":"text","v":"The Six Mandatory Blocks of the Command Deck"}]},{"b":"list","ordered":true,"items":[{"spans":[{"t":"b","v":"Block 1: Hero Identity & Visual Authority:"},{"t":"text","v":" A single, razor-sharp, horizontal landscape photograph displaying high visual charisma and distinct artistic styling. Overlay your artist name, hometown metro, and genre classification. Zero cluttered logos or amateur text treatments."}]},{"spans":[{"t":"b","v":"Block 2: The 80-Word Executive Bio:"},{"t":"text","v":" An objective, third-person executive summary answering three questions: "},{"t":"i","v":"Who are you? What is your signature sonic proposition? What major commercial or live milestones have you achieved?"},{"t":"text","v":" Strike all poetic musings."}]},{"spans":[{"t":"b","v":"Block 3: Embedded Broadcast Audio Player:"},{"t":"text","v":" An immediate, zero-friction audio player featuring your lead radio single prominently at the top, complete with an instant \"Download Broadcast Master WAV\" button. Include two secondary focus tracks below."}]},{"spans":[{"t":"b","v":"Block 4: The Verifiable Proof Wall:"},{"t":"text","v":" Four visual receipt badges: station callsigns currently spinning your record, verified quote excerpts from reputable publications, and confirmed ticket sales receipts."}]},{"spans":[{"t":"b","v":"Block 5: Confirmed Live Routing & Tour Dates:"},{"t":"text","v":" A clean chronological listing of upcoming live dates displaying Date, City, Venue, and Capacity. If routing is regional, clearly highlight hometown dates."}]},{"spans":[{"t":"b","v":"Block 6: Direct Commercial Contact Information:"},{"t":"text","v":" Direct email and mobile telephone numbers for the artist, management, or booking representative. Eliminate generic contact forms."}]}]}]', '[{"b":"p","spans":[{"t":"b","v":"WAR-ROOM DIRECTIVE — 3.3 The One-Page EPK That Commands Attention"}]},{"b":"p","spans":[{"t":"b","v":"THE HOSTING ARCHITECTURE: NEVER SEND AN ATTACHED PDF AS AN EPK"},{"t":"text","v":" Sending an attached PDF as your primary press kit is a legacy practice from 2008. PDFs render poorly on mobile screens, require pinch-to-zoom navigation, cannot embed live responsive audio players, and consume mobile data allowances."}]},{"b":"p","spans":[{"t":"b","v":"DOMINION EPK PROTOCOL:"}]},{"b":"list","ordered":true,"items":[{"spans":[{"t":"b","v":"The Web-Native Single URL:"},{"t":"text","v":" Host your One-Page Command Deck at a dedicated clean URL: "},{"t":"code","v":"artistname.com/epk"},{"t":"text","v":" or "},{"t":"code","v":"artistname.com/radio"},{"t":"text","v":"."}]},{"spans":[{"t":"b","v":"Password-Free Access:"},{"t":"text","v":" Never put a password on your press kit. A gatekeeper arriving from a cold pitch will immediately close the tab if confronted with a password gate."}]},{"spans":[{"t":"b","v":"Dedicated Radio Focus:"},{"t":"text","v":" If possible, create a sub-variant at "},{"t":"code","v":"artistname.com/radio"},{"t":"text","v":" that places the Broadcast WAV download link and station quote badges directly in the hero block above all other elements. <!-- WARROOM:END -->"}]}]}]', '["Password-Free Access: Never put a password on your press kit."]', '["The mechanic: a decision interface, not art.","The missing piece: the EPK''s receipts should be regional editions — a master deck with per-market proof variants.","The operator move: keep the master EPK at 6 blocks, but build 3 regional \"decks\" (west/east/mid) that swap only the proof block. Effort: 1 hour. Conversion delta: meaningful."]', '[{"kind":"note","blocks":[{"b":"p","spans":[{"t":"text","v":"Complete the structured table below as part of your lesson implementation. This worksheet directly replaces legacy spreadsheets with a publication-grade execution protocol."}]}]},{"kind":"table","title":"ONE-PAGE EPK ARCHITECTURE SPECIFICATION","headers":["Command Deck Block","Required Content Elements","Technical Specification","Target Read-Time","Verification Metric"],"rows":[["Block 1: Hero Visual","Charismatic promo photo, genre tag, city","1920x1080 compressed WebP (<250kb)","3 seconds","High-contrast visual authority"],["Block 2: Executive Bio","80-word objective commercial summary","Clean typography, 15px+ body font","7 seconds","Zero poetic fluff; 2 verified facts"],["Block 3: Audio Deck","Lead single stream + Broadcast WAV button","HTML5 embedded player + metadata","4 seconds","1-click instant playback, no signup"],["Block 4: Proof Wall","Station logos, quote snippets, ticket counts","4 visual proof cards with source links","3 seconds","Third-party validation visible"],["Block 5: Tour Routing","Upcoming 90-day dates, venues, capacities","Clean tabular chronological list","2 seconds","Proves active market ground game"],["Block 6: Direct Contact","Direct phone, email, management details","Click-to-call / click-to-email links","1 second","Zero barrier to gatekeeper outreach"]]}]', '["Post your live One-Page Command Deck URL for peer testing.","Share your 80-Word Executive Bio for line-by-line editorial feedback.","Report your Command Deck mobile page speed score from Google PageSpeed Insights.","Did your Command Deck pass the 20-Second Civilian Comprehension Test? What did your test subject remember?"]', '{"kind":"field-exercise","prompt":"Complete every drill below with real, verifiable answers, then confirm the pass standard.","items":[{"id":"d1","label":"The 80-Word Bio Surgery","description":"The 80-Word Bio Surgery . Draft an 80-word executive bio for Block 2 using the template below. Ensure it contains zero empty hype adjectives and at least two verifiable objective facts.","minutes":30,"type":"response","passStandard":null},{"id":"d2","label":"The Single-Screen Layout Audit","description":"The Single-Screen Layout Audit . Assemble your One-Page Command Deck using HTML/CSS or a clean responsive landing page builder. Verify that Blocks 1, 2, and 3 are visible above the fold on desktop and tablet screens.","minutes":30,"type":"response","passStandard":null},{"id":"d3","label":"The Dead Link & Speed Audit","description":"The Dead Link & Speed Audit . Test every single hyperlink, audio player button, and download link on your Command Deck. Page load time must clock under 1.5 seconds on mobile data.","minutes":15,"type":"response","passStandard":null},{"id":"d4","label":"The 20-Second Civilian Comprehension Test","description":"The 20-Second Civilian Comprehension Test . Hand your phone with your Command Deck open to a friend or colleague for exactly 20 seconds, then take it back. Ask them: What genre do I play? Where am I from? What station plays me? If they cannot answer, redesign for clarity.","minutes":15,"type":"response","passStandard":null}],"worksheets":[{"kind":"table","title":"ONE-PAGE EPK ARCHITECTURE SPECIFICATION","headers":["Command Deck Block","Required Content Elements","Technical Specification","Target Read-Time","Verification Metric"],"rows":[["Block 1: Hero Visual","Charismatic promo photo, genre tag, city","1920x1080 compressed WebP (<250kb)","3 seconds","High-contrast visual authority"],["Block 2: Executive Bio","80-word objective commercial summary","Clean typography, 15px+ body font","7 seconds","Zero poetic fluff; 2 verified facts"],["Block 3: Audio Deck","Lead single stream + Broadcast WAV button","HTML5 embedded player + metadata","4 seconds","1-click instant playback, no signup"],["Block 4: Proof Wall","Station logos, quote snippets, ticket counts","4 visual proof cards with source links","3 seconds","Third-party validation visible"],["Block 5: Tour Routing","Upcoming 90-day dates, venues, capacities","Clean tabular chronological list","2 seconds","Proves active market ground game"],["Block 6: Direct Contact","Direct phone, email, management details","Click-to-call / click-to-email links","1 second","Zero barrier to gatekeeper outreach"]]}],"confirmations":[{"id":"community","text":"One community drill answered (optional but strengthens calibration).","required":false}]}', '{"policy":"all-responses-min-words","minWords":40,"requireAllDrills":true,"requireWorksheetCells":0,"note":""}', '[{"to":"/frequency-dominion/app/vault","label":"Pitch & subject-line tools"}]', 'courses/frequency-dominion/frequency-dominion-course.zip', 1, strftime('%Y-%m-%dT%H:%M:%SZ','now'), strftime('%Y-%m-%dT%H:%M:%SZ','now'))
       ON CONFLICT(id) DO UPDATE SET module_id=excluded.module_id, code=excluded.code, title=excluded.title, minutes=excluded.minutes, exercise_minutes=excluded.exercise_minutes, position=excluded.position, truth=excluded.truth, masterclass_json=excluded.masterclass_json, field_protocol_json=excluded.field_protocol_json, warnings_json=excluded.warnings_json, decoder_json=excluded.decoder_json, worksheets_json=excluded.worksheets_json, community_json=excluded.community_json, exercise_json=excluded.exercise_json, pass_json=excluded.pass_json, tool_links_json=excluded.tool_links_json, version=lessons.version+1, updated_at=strftime('%Y-%m-%dT%H:%M:%SZ','now');
INSERT INTO lessons (id, module_id, code, title, minutes, exercise_minutes, position, published, truth, masterclass_json, field_protocol_json, warnings_json, decoder_json, worksheets_json, community_json, exercise_json, pass_json, tool_links_json, print_asset, version, created_at, updated_at)
       VALUES ('m3l4', 'm3', '3.4', 'Radio-Ready Audio — The 90-Second Weapon That Forces Replies', 8, 105, 3, 1, 'A programmer does not have time to sit through a five-minute album cut. The 90-second audio weapon and compliant broadcast master remove every technical barrier between your music and their transmitter.', '[{"b":"h","level":3,"spans":[{"t":"text","v":"Strategic Foundation & Operational Reality"}]},{"b":"p","spans":[{"t":"text","v":"Nothing destroys an artist''s credibility faster than delivering technically non-compliant audio files. When a programmer agrees to air your track, they expect to drag the file directly into their station automation software (such as WideOrbit, RCS Master Control, ENCO, or Dalet) and have it play flawlessly on the station''s broadcast chain."}]},{"b":"p","spans":[{"t":"text","v":"If your file is an uncensored master with explicit language, an unmastered quiet bounce at -24 LUFS, an over-compressed file clipping past 0.0 dBFS, or an amateur MP3 titled "},{"t":"code","v":"song_final_v3.mp3"},{"t":"text","v":" with missing ID3 metadata, the station engineer or DJ will delete it rather than spend 15 minutes fixing your packaging."}]},{"b":"p","spans":[{"t":"text","v":"Dominion operators understand the technical physics of broadcast processing and deliver a complete, turn-key "},{"t":"b","v":"Radio-Ready Audio Package"},{"t":"text","v":"."}]},{"b":"h","level":3,"spans":[{"t":"text","v":"Broadcast Audio Specifications & Standards"}]},{"b":"p","spans":[{"t":"text","v":"To ensure seamless integration across FM transmitters, digital HD sidebands, and web streams, your master deliverables must strictly adhere to industry standards:"}]},{"b":"list","ordered":true,"items":[{"spans":[{"t":"b","v":"Loudness Standards (LUFS):"},{"t":"text","v":" While streaming platforms normalize to -14 LUFS, FM radio broadcast chains utilize aggressive multi-band hardware limiters (such as Orban Optimod or Omnia processors). Deliver an integrated loudness of "},{"t":"b","v":"-12 to -14 LUFS"},{"t":"text","v":" with a maximum True Peak of "},{"t":"b","v":"-1.0 dBTP"},{"t":"text","v":" to prevent inter-sample clipping when passed through broadcast transmission encoders."}]},{"spans":[{"t":"b","v":"Dedicated FCC Clean Radio Edit:"},{"t":"text","v":" An absolute requirement for daytime terrestrial broadcast. Every profane or suggestive lyric must be cleanly reversed, muted, or re-recorded with alternate phrasing. Never assume a college or community station can air explicit language during daytime hours; the FCC levies severe fines for broadcast obscenity between 6:00 AM and 10:00 PM."}]},{"spans":[{"t":"b","v":"The 90-Second Audio Weapon:"},{"t":"text","v":" In addition to the full radio edit, create a dedicated 90-second promotional sampler that cuts directly from an abbreviated 5-second intro into Verse 1, leaps straight to the chorus hook, showcases the dynamic bridge peak, and concludes with a crisp button outro. This is the file you link in your pitch when targeting busy programmers."}]},{"spans":[{"t":"b","v":"The 30-Second Sweeper Hook:"},{"t":"text","v":" A 30-second high-energy hook segment bookended by silence, designed specifically for station imaging producers to build promotional sweepers and upcoming concert teasers."}]}]}]', '[{"b":"p","spans":[{"t":"b","v":"WAR-ROOM DIRECTIVE — 3.4 Radio-Ready Audio — The 90-Second Weapon That Forces Replies"}]},{"b":"p","spans":[{"t":"b","v":"THE ID3 METADATA DISASTER THAT COST 10,000 SPINS"},{"t":"text","v":" When station automation software ingests an audio file, it reads the internal ID3 metadata tags (Artist, Title, Album, Year, ISRC, Composer, Record Label) to automatically generate on-air RDS dashboard displays (the text showing on car dashboards) and report spins to ASCAP/BMI and SoundExchange."}]},{"b":"p","spans":[{"t":"text","v":"If your audio file has blank ID3 tags, the automation system logs the spin as "},{"t":"code","v":"Unknown Artist — Track 01"},{"t":"text","v":"."}]},{"b":"list","ordered":false,"items":[{"spans":[{"t":"text","v":"You receive zero public royalties."}]},{"spans":[{"t":"text","v":"Car dashboards display zero artist information to listeners."}]},{"spans":[{"t":"text","v":"The DJ cannot announce your name because the computer screen shows a blank field."}]}]},{"b":"p","spans":[{"t":"b","v":"MANDATORY METADATA EMBEDDING:"},{"t":"text","v":" Use a dedicated metadata editor (such as MP3Tag or Kid3) to permanently write:"}]},{"b":"list","ordered":false,"items":[{"spans":[{"t":"text","v":"Track Title (include "},{"t":"code","v":"(Clean Radio Edit)"},{"t":"text","v":")"}]},{"spans":[{"t":"text","v":"Artist Name"}]},{"spans":[{"t":"text","v":"Album Name & Release Year"}]},{"spans":[{"t":"text","v":"Composer / Songwriter Full Legal Names"}]},{"spans":[{"t":"text","v":"ISRC Code (International Standard Recording Code)"}]},{"spans":[{"t":"text","v":"Publisher & PRO Affiliation (e.g., "},{"t":"code","v":"BMI / Work ID #"},{"t":"text","v":") <!-- WARROOM:END -->"}]}]}]', '["Never assume a college or community station can air explicit language during daytime hours; the FCC levies severe fines for broadcast obscenity between 6:00 AM and 10:00 PM. 3."]', '["The mechanic: logistics dominate decisions.","The missing piece: the 30-sec payload is the forwarding asset — the one that goes from the PD to the promo team.","The operator move: always include the 30-sec cut in the package. It''s the smallest file and the one that gets passed around."]', '[{"kind":"note","blocks":[{"b":"p","spans":[{"t":"text","v":"Complete the structured table below as part of your lesson implementation. This worksheet directly replaces legacy spreadsheets with a publication-grade execution protocol."}]}]},{"kind":"table","title":"BROADCAST AUDIO SPECIFICATION & DELIVERABLE MATRIX","headers":["Deliverable Asset","Technical Format","Loudness & Peak Target","Standardized File Naming Convention","Operational Deployment"],"rows":[["Broadcast Master (Full)","24-bit / 44.1kHz WAV","-12 to -14 LUFS / -1.0 dBTP","ArtistName_TrackTitle_RadioEdit_Clean.wav","Direct automation playout file"],["FCC Clean Radio Edit","24-bit / 44.1kHz WAV","-12 to -14 LUFS / -1.0 dBTP","ArtistName_TrackTitle_FCC_Clean.wav","Daytime terrestrial rotation safe"],["90-Second Audio Weapon","320kbps MP3 (Clean)","-12 LUFS / -1.0 dBTP","ArtistName_TrackTitle_90Sec_Weapon.mp3","Direct streaming link in 90-word pitch"],["30-Second Sweeper Hook","24-bit / 44.1kHz WAV","-12 LUFS / -1.0 dBTP","ArtistName_TrackTitle_30s_Hook.wav","Station imaging & on-air concert promo"],["Instrumental Broadcast Bed","24-bit / 44.1kHz WAV","-14 LUFS / -1.0 dBTP","ArtistName_TrackTitle_Instrumental.wav","DJ talkover bed during voice breaks"]]}]', '["Post a screenshot of your audio metering tool showing integrated LUFS and True Peak on your master bounce.","Confirm that your audio file names conform 100% to the Standardized File Naming Convention.","Share your 90-Second Audio Weapon link with the community for pacing and hook impact feedback.","Verify that your ISRC codes and PRO publisher details are embedded in your master metadata."]', '{"kind":"field-exercise","prompt":"Complete every drill below with real, verifiable answers, then confirm the pass standard.","items":[{"id":"d1","label":"Broadcast Master Specification Audit","description":"Broadcast Master Specification Audit . Open your primary single in your digital audio workstation (DAW) or mastering meter. Measure Integrated LUFS, Short-Term Max, and True Peak. Verify True Peak does not exceed -1.0 dBTP.","minutes":25,"type":"response","passStandard":null},{"id":"d2","label":"The FCC Clean Edit Protocol","description":"The FCC Clean Edit Protocol . If your track contains explicit lyrics, bounce a dedicated FCC Clean Radio Edit. Ensure vocal cuts or reversals sound musical and seamless.","minutes":30,"type":"response","passStandard":null},{"id":"d3","label":"The 90-Second Weapon Cut","description":"The 90-Second Weapon Cut . Edit a dedicated 90-second audio weapon file: 0:00–0:05 intro, 0:05–0:30 verse, 0:30–1:00 chorus, 1:00–1:30 bridge + final hook.","minutes":30,"type":"response","passStandard":null},{"id":"d4","label":"Standardized ID3 Metadata Stamping","description":"Standardized ID3 Metadata Stamping . Tag all audio deliverables with comprehensive broadcast metadata using the Standardized Naming Convention below.","minutes":20,"type":"response","passStandard":null}],"worksheets":[{"kind":"table","title":"BROADCAST AUDIO SPECIFICATION & DELIVERABLE MATRIX","headers":["Deliverable Asset","Technical Format","Loudness & Peak Target","Standardized File Naming Convention","Operational Deployment"],"rows":[["Broadcast Master (Full)","24-bit / 44.1kHz WAV","-12 to -14 LUFS / -1.0 dBTP","ArtistName_TrackTitle_RadioEdit_Clean.wav","Direct automation playout file"],["FCC Clean Radio Edit","24-bit / 44.1kHz WAV","-12 to -14 LUFS / -1.0 dBTP","ArtistName_TrackTitle_FCC_Clean.wav","Daytime terrestrial rotation safe"],["90-Second Audio Weapon","320kbps MP3 (Clean)","-12 LUFS / -1.0 dBTP","ArtistName_TrackTitle_90Sec_Weapon.mp3","Direct streaming link in 90-word pitch"],["30-Second Sweeper Hook","24-bit / 44.1kHz WAV","-12 LUFS / -1.0 dBTP","ArtistName_TrackTitle_30s_Hook.wav","Station imaging & on-air concert promo"],["Instrumental Broadcast Bed","24-bit / 44.1kHz WAV","-14 LUFS / -1.0 dBTP","ArtistName_TrackTitle_Instrumental.wav","DJ talkover bed during voice breaks"]]}],"confirmations":[{"id":"community","text":"One community drill answered (optional but strengthens calibration).","required":false}]}', '{"policy":"all-responses-min-words","minWords":40,"requireAllDrills":true,"requireWorksheetCells":0,"note":""}', '[{"to":"/frequency-dominion/app/vault","label":"Pitch & subject-line tools"}]', 'courses/frequency-dominion/frequency-dominion-course.zip', 1, strftime('%Y-%m-%dT%H:%M:%SZ','now'), strftime('%Y-%m-%dT%H:%M:%SZ','now'))
       ON CONFLICT(id) DO UPDATE SET module_id=excluded.module_id, code=excluded.code, title=excluded.title, minutes=excluded.minutes, exercise_minutes=excluded.exercise_minutes, position=excluded.position, truth=excluded.truth, masterclass_json=excluded.masterclass_json, field_protocol_json=excluded.field_protocol_json, warnings_json=excluded.warnings_json, decoder_json=excluded.decoder_json, worksheets_json=excluded.worksheets_json, community_json=excluded.community_json, exercise_json=excluded.exercise_json, pass_json=excluded.pass_json, tool_links_json=excluded.tool_links_json, version=lessons.version+1, updated_at=strftime('%Y-%m-%dT%H:%M:%SZ','now');
INSERT INTO lessons (id, module_id, code, title, minutes, exercise_minutes, position, published, truth, masterclass_json, field_protocol_json, warnings_json, decoder_json, worksheets_json, community_json, exercise_json, pass_json, tool_links_json, print_asset, version, created_at, updated_at)
       VALUES ('m4l1', 'm4', '4.1', 'The Load Sequence — Arm Every Station Before You Send', 8, 95, 0, 1, 'The first email is not the launch — the Load Sequence is. A campaign executed without passing all seven pre-flight gates will collapse into chaotic improvisation.', '[{"b":"h","level":3,"spans":[{"t":"text","v":"Strategic Foundation & Operational Reality"}]},{"b":"p","spans":[{"t":"text","v":"Amateur campaigns fail because they start sending emails the moment a master bounce is exported. An artist writes a pitch on a whim, discovers their streaming link is private, realizes they have no clean radio edit, spends three days chasing an engineer for a master file, forgets who they emailed, and misses follow-up windows."}]},{"b":"p","spans":[{"t":"text","v":"Professional military operations and enterprise software releases adhere to a strict "},{"t":"b","v":"Load Sequence"},{"t":"text","v":"."}]},{"b":"p","spans":[{"t":"text","v":"Nothing is dispatched to a target station until every operational asset, tracking mechanism, technical file, and calendar block has been fully verified and locked down. When Day 1 arrives, you are not writing copy or designing press kits. You are pulling the trigger on an armed, tested, high-precision system."}]},{"b":"h","level":3,"spans":[{"t":"text","v":"The Seven Pre-Flight Operational Gates"}]},{"b":"p","spans":[{"t":"text","v":"Before Day 1 of your campaign, you must achieve 100% green-light verification across all seven gates:"}]},{"b":"list","ordered":false,"items":[{"spans":[{"t":"b","v":"Gate 1: Audio Asset Integrity:"},{"t":"text","v":" Full Broadcast WAV (-14 LUFS, -1.0 dBTP), FCC Clean Radio Edit, 90-Second Audio Weapon, and 30-Second Sweeper Hook exported, named to standard, and ID3 tagged."}]},{"spans":[{"t":"b","v":"Gate 2: Command Deck Online:"},{"t":"text","v":" One-Page EPK live at dedicated clean URL. Zero broken links, mobile page speed verified under 1.5 seconds, instant streaming player functional."}]},{"spans":[{"t":"b","v":"Gate 3: 20 War Room Targets Locked:"},{"t":"text","v":" 20 stations scored >= 75 points, named individual gatekeepers verified, direct email addresses checked, and secondary station contacts logged."}]},{"spans":[{"t":"b","v":"Gate 4: 3-Layer Subject Lines Pre-Drafted:"},{"t":"text","v":" All 20 customized subject lines written, mobile truncation tested (< 45 chars), and assigned to specific target programmers."}]},{"spans":[{"t":"b","v":"Gate 5: 90-Word Pitches Staged:"},{"t":"text","v":" Individual 90-word payloads written and tailored to each programmer''s recent playlist additions and local angles."}]},{"spans":[{"t":"b","v":"Gate 6: Campaign Execution Calendar Blocked:"},{"t":"text","v":" Four 45-minute daily operational execution blocks scheduled and locked in your calendar across the entire 21-day timeline."}]},{"spans":[{"t":"b","v":"Gate 7: Post-Add & Thank-You Assets Prepared:"},{"t":"text","v":" Thank-you email templates drafted, physical station postcards pre-addressed, and social celebration graphics staged."}]}]}]', '[{"b":"p","spans":[{"t":"b","v":"WAR-ROOM DIRECTIVE — 4.1 The Load Sequence — Arm Every Station Before You Send"}]},{"b":"p","spans":[{"t":"b","v":"THE T-MINUS 48 HOUR LOCKDOWN"},{"t":"text","v":" Forty-eight hours prior to Day 1, declare a total "},{"t":"b","v":"Code Freeze"},{"t":"text","v":"."}]},{"b":"list","ordered":false,"items":[{"spans":[{"t":"text","v":"No more tweaking the vocal mix."}]},{"spans":[{"t":"text","v":"No more altering the master EQ balance."}]},{"spans":[{"t":"text","v":"No more redesigning the album artwork."}]},{"spans":[{"t":"text","v":"No more changing the EPK typography."}]}]},{"b":"p","spans":[{"t":"text","v":"Perfectionism at T-48 hours is a psychological defense mechanism driven by fear of market rejection. The record is done. The packaging is frozen. The weapons are armed. Trust the engineering and execute the sequence."}]}]', '[]', '["The mechanic: fire only armed stations.","The missing piece: the industry''s \"impact date\" framing — tell the PD the add is scheduled for a specific week.","The operator move: give the campaign an official impact date and service 1–2 weeks ahead of it. PDs are calendar animals; a date converts \"maybe\" into \"when?\""]', '[{"kind":"note","blocks":[{"b":"p","spans":[{"t":"text","v":"Complete the structured table below as part of your lesson implementation. This worksheet directly replaces legacy spreadsheets with a publication-grade execution protocol."}]}]},{"kind":"table","title":"THE SEVEN-GATE LOAD SEQUENCE ARMING BOARD","headers":["Gate Number & Asset","Operational Standard","Verification Status","Blocker / Deficiency","Remediation Action Plan"],"rows":[["Gate 1: Audio Deliverables","WAV, Clean Edit, 90s Weapon, 30s Hook","PASSED","None","Files staged in private Dropbox"],["Gate 2: Command Deck EPK","Responsive URL, <1.5s load, zero dead links","PASSED","None","Verified on desktop & mobile iOS"],["Gate 3: 20 Scored Stations","20 stations scored >= 75 pts with named MD","PASSED","None","All 20 contacts verified via Spinitron"],["Gate 4: 3-Layer Subject Lines","20 tailored lines, < 45 chars mobile","PASSED","None","Pre-loaded in campaign drafts"],["Gate 5: Staged 90-Word Pitches","Personalized copy, single clear ask","PASSED","None","All drafts reviewed under 90 words"],["Gate 6: Calendar Blocks Locked","4x 45-min weekly execution blocks","PASSED","None","Synchronized in Google Calendar"],["Gate 7: Gratitude Pipeline Staged","Thank-you drafts & physical cards ready","PASSED","None","Station studio addresses logged"]]}]', '["Post your completed Seven-Gate Arming Board showing 100% Passed status across all gates.","Share the date and time of your scheduled Day 1 launch.","What was the most critical deficiency you identified and corrected during your pre-flight audit?","Affirm that your calendar execution blocks are locked and non-negotiable."]', '{"kind":"field-exercise","prompt":"Complete every drill below with real, verifiable answers, then confirm the pass standard.","items":[{"id":"d1","label":"The Seven-Gate System Audit","description":"The Seven-Gate System Audit . Walk through the Load Sequence Arming Board below. Mark every gate as Pass, Pending, or Fail. Zero sends permitted until all seven gates are marked Pass.","minutes":45,"type":"response","passStandard":null},{"id":"d2","label":"The Broken Link & Permission Sweep","description":"The Broken Link & Permission Sweep . Open an incognito browser window on your phone. Click every link in your staged pitches. Verify that audio streams immediately with zero password prompts or login gates.","minutes":20,"type":"response","passStandard":null},{"id":"d3","label":"The Calendar Lockdown Protocol","description":"The Calendar Lockdown Protocol . Block out exactly 45 minutes every Monday, Tuesday, Wednesday, and Thursday morning for the next three weeks. Label the blocks: ''Dominion Campaign Battle Rhythm.''","minutes":15,"type":"response","passStandard":null},{"id":"d4","label":"The Pre-Flight Failure Simulation","description":"The Pre-Flight Failure Simulation . Identify your single most vulnerable operational bottleneck (e.g., slow email response time, missing clean lyrics, unverified gatekeeper email) and execute an immediate contingency fix today.","minutes":15,"type":"response","passStandard":null}],"worksheets":[{"kind":"table","title":"THE SEVEN-GATE LOAD SEQUENCE ARMING BOARD","headers":["Gate Number & Asset","Operational Standard","Verification Status","Blocker / Deficiency","Remediation Action Plan"],"rows":[["Gate 1: Audio Deliverables","WAV, Clean Edit, 90s Weapon, 30s Hook","PASSED","None","Files staged in private Dropbox"],["Gate 2: Command Deck EPK","Responsive URL, <1.5s load, zero dead links","PASSED","None","Verified on desktop & mobile iOS"],["Gate 3: 20 Scored Stations","20 stations scored >= 75 pts with named MD","PASSED","None","All 20 contacts verified via Spinitron"],["Gate 4: 3-Layer Subject Lines","20 tailored lines, < 45 chars mobile","PASSED","None","Pre-loaded in campaign drafts"],["Gate 5: Staged 90-Word Pitches","Personalized copy, single clear ask","PASSED","None","All drafts reviewed under 90 words"],["Gate 6: Calendar Blocks Locked","4x 45-min weekly execution blocks","PASSED","None","Synchronized in Google Calendar"],["Gate 7: Gratitude Pipeline Staged","Thank-you drafts & physical cards ready","PASSED","None","Station studio addresses logged"]]}],"confirmations":[{"id":"community","text":"One community drill answered (optional but strengthens calibration).","required":false}]}', '{"policy":"all-responses-min-words","minWords":40,"requireAllDrills":true,"requireWorksheetCells":0,"note":""}', '[{"to":"/frequency-dominion/app/campaign","label":"21-Day Campaign board"}]', 'courses/frequency-dominion/frequency-dominion-course.zip', 1, strftime('%Y-%m-%dT%H:%M:%SZ','now'), strftime('%Y-%m-%dT%H:%M:%SZ','now'))
       ON CONFLICT(id) DO UPDATE SET module_id=excluded.module_id, code=excluded.code, title=excluded.title, minutes=excluded.minutes, exercise_minutes=excluded.exercise_minutes, position=excluded.position, truth=excluded.truth, masterclass_json=excluded.masterclass_json, field_protocol_json=excluded.field_protocol_json, warnings_json=excluded.warnings_json, decoder_json=excluded.decoder_json, worksheets_json=excluded.worksheets_json, community_json=excluded.community_json, exercise_json=excluded.exercise_json, pass_json=excluded.pass_json, tool_links_json=excluded.tool_links_json, version=lessons.version+1, updated_at=strftime('%Y-%m-%dT%H:%M:%SZ','now');
INSERT INTO lessons (id, module_id, code, title, minutes, exercise_minutes, position, published, truth, masterclass_json, field_protocol_json, warnings_json, decoder_json, worksheets_json, community_json, exercise_json, pass_json, tool_links_json, print_asset, version, created_at, updated_at)
       VALUES ('m4l2', 'm4', '4.2', 'First Sends — Timing, Waves, and the 4-Hour Rule', 8, 75, 1, 1, 'When you dispatch a payload matters as much as what is inside it. Two waves, Tuesday/Wednesday morning timing, and the four-hour monitoring window dictate initial conversion.', '[{"b":"h","level":3,"spans":[{"t":"text","v":"Strategic Foundation & Operational Reality"}]},{"b":"p","spans":[{"t":"text","v":"Dispatched at the wrong hour, the most brilliant pitch email on earth will drown unnoticed beneath hundreds of corporate press releases, label solicitations, and administrative memos."}]},{"b":"p","spans":[{"t":"text","v":"Radio programming departments operate on a universal industry cadence:"}]},{"b":"list","ordered":false,"items":[{"spans":[{"t":"b","v":"Monday:"},{"t":"text","v":" The weekend recovery and programming audit. Music directors compile weekend ratings data, reconcile commercial logs, and handle administrative fires. Cold pitches sent Monday morning are deleted or ignored."}]},{"spans":[{"t":"b","v":"Tuesday Morning (The Sacred Window):"},{"t":"text","v":" The weekly Music Meeting window. Commercial, AAA, and major non-comm stations review candidates for the weekly add board. Pitches landing between "},{"t":"b","v":"9:15 AM and 10:30 AM in the station''s local time zone"},{"t":"text","v":" sit right at the top of the inbox when the programmer sits down with their coffee."}]},{"spans":[{"t":"b","v":"Wednesday Morning (The Secondary Window):"},{"t":"text","v":" College, community, and alternative specialty music directors review new music submissions and update their weekly charts for NACC reporting."}]},{"spans":[{"t":"b","v":"Friday Afternoon (The Cemetery):"},{"t":"text","v":" Programmers are wrapping up production and heading into weekend shifts. Any pitch sent Friday afternoon is buried under 300 emails by Monday morning."}]}]},{"b":"h","level":3,"spans":[{"t":"text","v":"The Two-Wave Firing Strategy"}]},{"b":"p","spans":[{"t":"text","v":"Do not dispatch all 20 War Room emails in a single manic morning. Execute in "},{"t":"b","v":"Two Staggered Waves"},{"t":"text","v":":"}]},{"b":"list","ordered":false,"items":[{"spans":[{"t":"b","v":"Wave 1 (Day 1 — Tuesday Morning, 9:30 AM Local):"},{"t":"text","v":" Target your "},{"t":"b","v":"Top 10 Tier-1 Stations"},{"t":"text","v":" (your highest-conviction Ring 1 and Ring 2 targets). These receive maximum focus, immediate monitoring, and real-time dialogue handling."}]},{"spans":[{"t":"b","v":"Wave 2 (Day 3 — Thursday Morning, 9:30 AM Local):"},{"t":"text","v":" Target your "},{"t":"b","v":"Remaining 10 Stations"},{"t":"text","v":" (Tier-2 regional targets and tour corridor targets). Staggering allows you to incorporate any initial technical feedback or diagnostic insights gained from Wave 1."}]}]},{"b":"h","level":3,"spans":[{"t":"text","v":"The Four-Hour Monitoring Window"}]},{"b":"p","spans":[{"t":"text","v":"When you hit send on a wave, you do not abandon your workstation. You initiate the "},{"t":"b","v":"Four-Hour Monitoring Window"},{"t":"text","v":"."}]},{"b":"p","spans":[{"t":"text","v":"If a programmer opens your email, clicks the streaming link, and replies with a question or asset request, their buying intent is active at that exact second. A response delivered within 15 minutes converts to an immediate on-air add at 4x the rate of a response sent the following day. Maintain rapid response readiness for clean broadcast WAV deliveries, lyric clarifications, or interview scheduling."}]}]', '[{"b":"p","spans":[{"t":"b","v":"WAR-ROOM DIRECTIVE — 4.2 First Sends — Timing, Waves, and the 4-Hour Rule"}]},{"b":"p","spans":[{"t":"b","v":"DIAGNOSTIC TRIAGE: INTERPRETING INITIAL RESULTS"},{"t":"text","v":" Between Day 1 and Day 7, monitor your initial send metrics with clinical detachment:"}]},{"b":"list","ordered":true,"items":[{"spans":[{"t":"b","v":"Low Open Rates (< 20%):"},{"t":"text","v":" Indicates your subject line was truncated on mobile, your sender domain triggered a spam quarantine filter, or the gatekeeper''s email address is obsolete. Re-verify the contact and test an alternate subject line archetype."}]},{"spans":[{"t":"b","v":"High Open Rate, Zero Link Clicks (> 50% open, 0% click):"},{"t":"text","v":" Indicates your subject line worked, but your opening two sentences in the 90-word pitch were boring or irrelevant. Sharpen the hook and tighten the proof line."}]},{"spans":[{"t":"b","v":"High Link Clicks, Zero Replies:"},{"t":"text","v":" Indicates the programmer opened the pitch, listened to the song, but either found a format mismatch or felt no urgency to reply. This is the exact scenario designed for the "},{"t":"b","v":"Touch 2 Asset Drop"},{"t":"text","v":" in Lesson 4.3. <!-- WARROOM:END -->"}]}]}]', '["Any pitch sent Friday afternoon is buried under 300 emails by Monday morning. ### The Two-Wave Firing Strategy Do not dispatch all 20 War Room emails in a single manic morning.","Staggering allows you to incorporate any initial technical feedback or diagnostic insights gained from Wave 1. ### The Four-Hour Monitoring Window When you hit send on a wave, you do not abandon your workstation."]', '["The mechanic: two waves, 4-hour rule.","The missing piece: the campaign rides the weekly rotation cycle — wave 1 on Tuesday, wave 2 on Thursday, touch-3 the next Monday (fresh board).","The operator move: treat the campaign as a weekly machine. Every Monday is the \"refresh\" heartbeat: board refreshed, grace closes land, proof drops."]', '[{"kind":"note","blocks":[{"b":"p","spans":[{"t":"text","v":"Complete the structured table below as part of your lesson implementation. This worksheet directly replaces legacy spreadsheets with a publication-grade execution protocol."}]}]},{"kind":"table","title":"FIRST-SEND DISPATCH LOG & TIME ZONE SCHEDULE","headers":["Target Station","Decision Maker","Local Time Zone","Scheduled Dispatch Time","Wave Cohort","Initial Outcome (Day 1-4)"],"rows":[["WLUW 88.7 FM","Sarah Jenkins (MD)","Central (CST)","Tuesday 9:30 AM CST","Wave 1 (Priority)","Opened 10:14 AM; Link Clicked"],["WNUR 89.3 FM","Alex Rivera (MD)","Central (CST)","Tuesday 9:30 AM CST","Wave 1 (Priority)","Replied 11:20 AM; WAV Requested"],["WMSE 91.7 FM","Tom Crawford (PD)","Central (CST)","Tuesday 9:30 AM CST","Wave 1 (Priority)","Awaiting Touch 2 Follow-Up"],["WXPN 88.5 FM","Bruce Warren (PD)","Eastern (EST)","Thursday 9:30 AM EST","Wave 2 (Regional)","Opened 9:45 AM; No Reply"],["KUTX 98.9 FM","Rick McNulty (MD)","Central (CST)","Thursday 9:30 AM CST","Wave 2 (Regional)","Awaiting Touch 2 Follow-Up"]]}]', '["Announce the official dispatch of your Wave 1 payload in the community forum.","Report your 24-hour open and engagement metrics from Wave 1.","Did you receive an immediate reply or asset request during your 4-Hour Monitoring Window? Share the outcome.","Discuss any unexpected delivery bounces and how you resolved the contact data."]', '{"kind":"field-exercise","prompt":"Complete every drill below with real, verifiable answers, then confirm the pass standard.","items":[{"id":"d1","label":"Time Zone Synchronization","description":"Time Zone Synchronization . Organize your 20 War Room stations by local time zone (Eastern, Central, Mountain, Pacific). Calculate the exact dispatch time in your home time zone for each station to ensure delivery at 9:30 AM local.","minutes":20,"type":"response","passStandard":null},{"id":"d2","label":"Wave 1 & Wave 2 Cohort Assignment","description":"Wave 1 & Wave 2 Cohort Assignment . Assign 10 stations to Wave 1 (Tuesday) and 10 stations to Wave 2 (Thursday) in the First-Send Launch Log below.","minutes":15,"type":"response","passStandard":null},{"id":"d3","label":"Dispatch Simulation & Template Staging","description":"Dispatch Simulation & Template Staging . Pre-populate email drafts for all 10 Wave 1 targets with verified subject lines, customized 90-word body copy, and recipient inboxes.","minutes":25,"type":"response","passStandard":null},{"id":"d4","label":"The Four-Hour Readiness Drill","description":"The Four-Hour Readiness Drill . Prepare your rapid-response asset folder on your local desktop: Broadcast WAV, high-res promo image, FCC clean lyrics PDF, and 1-paragraph show date brief ready for instantaneous dispatch.","minutes":15,"type":"response","passStandard":null}],"worksheets":[{"kind":"table","title":"FIRST-SEND DISPATCH LOG & TIME ZONE SCHEDULE","headers":["Target Station","Decision Maker","Local Time Zone","Scheduled Dispatch Time","Wave Cohort","Initial Outcome (Day 1-4)"],"rows":[["WLUW 88.7 FM","Sarah Jenkins (MD)","Central (CST)","Tuesday 9:30 AM CST","Wave 1 (Priority)","Opened 10:14 AM; Link Clicked"],["WNUR 89.3 FM","Alex Rivera (MD)","Central (CST)","Tuesday 9:30 AM CST","Wave 1 (Priority)","Replied 11:20 AM; WAV Requested"],["WMSE 91.7 FM","Tom Crawford (PD)","Central (CST)","Tuesday 9:30 AM CST","Wave 1 (Priority)","Awaiting Touch 2 Follow-Up"],["WXPN 88.5 FM","Bruce Warren (PD)","Eastern (EST)","Thursday 9:30 AM EST","Wave 2 (Regional)","Opened 9:45 AM; No Reply"],["KUTX 98.9 FM","Rick McNulty (MD)","Central (CST)","Thursday 9:30 AM CST","Wave 2 (Regional)","Awaiting Touch 2 Follow-Up"]]}],"confirmations":[{"id":"community","text":"One community drill answered (optional but strengthens calibration).","required":false}]}', '{"policy":"all-responses-min-words","minWords":40,"requireAllDrills":true,"requireWorksheetCells":0,"note":""}', '[{"to":"/frequency-dominion/app/campaign","label":"21-Day Campaign board"}]', 'courses/frequency-dominion/frequency-dominion-course.zip', 1, strftime('%Y-%m-%dT%H:%M:%SZ','now'), strftime('%Y-%m-%dT%H:%M:%SZ','now'))
       ON CONFLICT(id) DO UPDATE SET module_id=excluded.module_id, code=excluded.code, title=excluded.title, minutes=excluded.minutes, exercise_minutes=excluded.exercise_minutes, position=excluded.position, truth=excluded.truth, masterclass_json=excluded.masterclass_json, field_protocol_json=excluded.field_protocol_json, warnings_json=excluded.warnings_json, decoder_json=excluded.decoder_json, worksheets_json=excluded.worksheets_json, community_json=excluded.community_json, exercise_json=excluded.exercise_json, pass_json=excluded.pass_json, tool_links_json=excluded.tool_links_json, version=lessons.version+1, updated_at=strftime('%Y-%m-%dT%H:%M:%SZ','now');
INSERT INTO lessons (id, module_id, code, title, minutes, exercise_minutes, position, published, truth, masterclass_json, field_protocol_json, warnings_json, decoder_json, worksheets_json, community_json, exercise_json, pass_json, tool_links_json, print_asset, version, created_at, updated_at)
       VALUES ('m4l3', 'm4', '4.3', 'The 3-Touch Follow-Up System — Persistence Without the Stench', 8, 65, 2, 1, 'The first email is a knock on the door. The second is proof you are serious. The third is a dignified exit. Over 65% of all independent radio adds occur on Touch 2 and Touch 3.', '[{"b":"h","level":3,"spans":[{"t":"text","v":"Strategic Foundation & Operational Reality"}]},{"b":"p","spans":[{"t":"text","v":"Amateurs view follow-up emails as awkward, intrusive begging. They wait two weeks, feel guilty, and eventually send a cringe-inducing message: "},{"t":"i","v":"\"Just bumping this to the top of your inbox!\""},{"t":"text","v":" or "},{"t":"i","v":"\"Did you get a chance to listen to my single yet?\""}]},{"b":"p","spans":[{"t":"text","v":"This language communicates zero value, demands emotional labor from the programmer, and creates instant resentment."}]},{"b":"p","spans":[{"t":"text","v":"Dominion operators know that "},{"t":"b","v":"programmers rely on follow-ups to filter out the tourists"},{"t":"text","v":". A music director receives 500 pitches a week; they intentionally ignore cold first-time emails to see which artists actually possess an organized campaign system and which ones disappear forever after one try."}]},{"b":"p","spans":[{"t":"text","v":"The "},{"t":"b","v":"3-Touch Follow-Up System"},{"t":"text","v":" is a disciplined, multi-stage value escalation cadence. It never bumps. It never asks if they listened. Every single touch introduces a "},{"t":"b","v":"brand-new, high-value commercial asset or proof receipt"},{"t":"text","v":"."}]},{"b":"h","level":3,"spans":[{"t":"text","v":"The Strict 3-Touch Cadence & Asset Escalation Architecture"}]},{"b":"list","ordered":false,"items":[{"spans":[{"t":"b","v":"Touch 1 (Day 1 / Day 3 — The Initial Payload):"},{"t":"text","v":" The complete 90-word pitch, 3-layer subject line, proof stack, and private streaming link. Sets the commercial baseline."}]},{"spans":[{"t":"b","v":"Touch 2 (Day 8 to Day 10 — The Value Drop):"},{"t":"text","v":" Dispatched 7 to 8 days after Touch 1. Keeps the original email thread intact so the programmer sees context. Delivers a brand-new asset that lowers listening friction:"}]},{"spans":[{"t":"i","v":"Copy Structure (Under 45 Words):"},{"t":"text","v":" "},{"t":"i","v":"\"Hi [Name] — in case it''s quicker during your music meeting, here''s a 30-second direct hook stream: [Link]. Also confirmed upcoming [Hometown Club] showcase on [Date]. Would love to see this in rotation for [Show Name].\""}]},{"spans":[{"t":"i","v":"Asset Introduced:"},{"t":"text","v":" The 30-Second Sweeper Hook or 90-Second Audio Weapon, plus a newly confirmed tour date or press quote."}]},{"spans":[{"t":"b","v":"Touch 3 (Day 14 to Day 16 — The Dignified Exit & Final Proof Point):"},{"t":"text","v":" Dispatched 6 to 7 days after Touch 2. Cites new momentum and provides a clean, respectful off-ramp:"}]},{"spans":[{"t":"i","v":"Copy Structure (Under 50 Words):"},{"t":"text","v":" "},{"t":"i","v":"\"Hi [Name] — quick update: [Song Title] was just added into rotation at [Station A] and [Station B] this week. If it''s not a fit for [Station Callsign] right now, no problem at all — we''ll reconnect on the next release cycle. Keep up the great programming.\""}]}]},{"b":"h","level":3,"spans":[{"t":"text","v":"The Iron Law of the Exit: Stop at Three"}]},{"b":"p","spans":[{"t":"text","v":"If Touch 3 produces no response, "},{"t":"b","v":"the campaign is closed"},{"t":"text","v":". You do not send a fourth email. You do not send a passive-aggressive message. You log the contact as ''Cold / 90-Day Hold'' and exit with total dignity. You have established yourself as a courteous, professional operator who respects their boundaries. When you return with your next single in 90 days, your email will be greeted with respect."}]}]', '[{"b":"p","spans":[{"t":"b","v":"WAR-ROOM DIRECTIVE — 4.3 The 3-Touch Follow-Up System — Persistence Without the Stench"}]},{"b":"p","spans":[{"t":"b","v":"WHY THREADING YOUR REPLIES IS A NON-NEGOTIABLE LAW"},{"t":"text","v":" When dispatching Touch 2 and Touch 3, "},{"t":"b","v":"always reply directly to the sent message thread of Touch 1"},{"t":"text","v":"."}]},{"b":"list","ordered":false,"items":[{"spans":[{"t":"text","v":"Do NOT generate a brand new email with a new subject line."}]},{"spans":[{"t":"text","v":"When the programmer opens Touch 2, they must be able to scroll down and immediately see your original 90-word pitch, original proof lines, and contact information."}]},{"spans":[{"t":"text","v":"Threading proves continuity. It shows the programmer that you have a deliberate, multi-week campaign architecture rather than sporadic, disorganized thoughts. <!-- WARROOM:END -->"}]}]}]', '["It never asks if they listened.","You do not send a fourth email.","You do not send a passive-aggressive message."]', '["The mechanic: value, then grace.","The missing piece: rotation upgrades are the real follow-up — light → medium is a category change ask, and it''s the most winnable ask in radio.","The operator move: 4 weeks after an add, ask for the upgrade with supporting receipts. Almost no independent makes this ask; that''s why it works."]', '[{"kind":"note","blocks":[{"b":"p","spans":[{"t":"text","v":"Complete the structured table below as part of your lesson implementation. This worksheet directly replaces legacy spreadsheets with a publication-grade execution protocol."}]}]},{"kind":"table","title":"3-TOUCH FOLLOW-UP COCKPIT & VALUE ESCALATION LOG","headers":["Target Station","Touch 1 Dispatch Date","Touch 2 Date & Asset Delivered","Touch 3 Date & Proof Point","Response / Final Status","Next Cycle Action"],"rows":[["WLUW 88.7 FM","Day 1 (Tuesday)","Day 8: 30s Hook Clip + Metro Date","Day 15: Added at WNUR & WMSE","CONFIRMED ADD (Day 16)","Initiate Thank-You Loop"],["WNUR 89.3 FM","Day 1 (Tuesday)","Day 8: Unreleased Acoustic Cut","N/A (Replied on Touch 2)","CONFIRMED ADD (Day 9)","Initiate Thank-You Loop"],["WMSE 91.7 FM","Day 1 (Tuesday)","Day 8: Milwaukee Tour Date Pass","Day 15: Regional Press Quote","CONFIRMED ADD (Day 15)","Initiate Thank-You Loop"],["WXPN 88.5 FM","Day 3 (Thursday)","Day 10: 90s Audio Weapon","Day 17: NACC Chart Debut","Declined (Polite Exit)","Log to 90-Day Archive"],["KUTX 98.9 FM","Day 3 (Thursday)","Day 10: Live Video Clip","Day 17: Austin Club Date","No Reply (Closed)","Log to 90-Day Archive"]]}]', '["Post your tailored Touch 2 copy for peer review. Check that it delivers a fresh asset under 45 words.","Share a historical win where a follow-up email secured an add after the initial pitch was ignored.","Affirm your commitment to the ''Stop at Three'' law in the community discussion.","Report your conversion rate from Touch 2 and Touch 3 across your active campaigns."]', '{"kind":"field-exercise","prompt":"Complete every drill below with real, verifiable answers, then confirm the pass standard.","items":[{"id":"d1","label":"Touch 2 & Touch 3 Script Pre-Drafting","description":"Touch 2 & Touch 3 Script Pre-Drafting . Draft customized Touch 2 and Touch 3 templates for your top 5 War Room stations using the Follow-Up Cockpit below. Ensure each touch carries a distinct, verifiable proof asset.","minutes":25,"type":"response","passStandard":null},{"id":"d2","label":"The Bumping Language Scrub","description":"The Bumping Language Scrub . Search your drafts for the words ''bump'', ''checking in'', ''following up'', ''wondering if''. Permanently delete them and replace with new asset delivery statements.","minutes":15,"type":"response","passStandard":null},{"id":"d3","label":"Calendar Follow-Up Scheduling","description":"Calendar Follow-Up Scheduling . Set exact calendar reminders for Day 8 (Touch 2) and Day 15 (Touch 3) for all 20 War Room targets.","minutes":15,"type":"response","passStandard":null},{"id":"d4","label":"The Dignified Exit Mental Rehearsal","description":"The Dignified Exit Mental Rehearsal . Read the Touch 3 script aloud. Practice the emotional discipline of accepting non-engagement without resentment.","minutes":10,"type":"response","passStandard":null}],"worksheets":[{"kind":"table","title":"3-TOUCH FOLLOW-UP COCKPIT & VALUE ESCALATION LOG","headers":["Target Station","Touch 1 Dispatch Date","Touch 2 Date & Asset Delivered","Touch 3 Date & Proof Point","Response / Final Status","Next Cycle Action"],"rows":[["WLUW 88.7 FM","Day 1 (Tuesday)","Day 8: 30s Hook Clip + Metro Date","Day 15: Added at WNUR & WMSE","CONFIRMED ADD (Day 16)","Initiate Thank-You Loop"],["WNUR 89.3 FM","Day 1 (Tuesday)","Day 8: Unreleased Acoustic Cut","N/A (Replied on Touch 2)","CONFIRMED ADD (Day 9)","Initiate Thank-You Loop"],["WMSE 91.7 FM","Day 1 (Tuesday)","Day 8: Milwaukee Tour Date Pass","Day 15: Regional Press Quote","CONFIRMED ADD (Day 15)","Initiate Thank-You Loop"],["WXPN 88.5 FM","Day 3 (Thursday)","Day 10: 90s Audio Weapon","Day 17: NACC Chart Debut","Declined (Polite Exit)","Log to 90-Day Archive"],["KUTX 98.9 FM","Day 3 (Thursday)","Day 10: Live Video Clip","Day 17: Austin Club Date","No Reply (Closed)","Log to 90-Day Archive"]]}],"confirmations":[{"id":"community","text":"One community drill answered (optional but strengthens calibration).","required":false}]}', '{"policy":"all-responses-min-words","minWords":40,"requireAllDrills":true,"requireWorksheetCells":0,"note":""}', '[{"to":"/frequency-dominion/app/campaign","label":"21-Day Campaign board"}]', 'courses/frequency-dominion/frequency-dominion-course.zip', 1, strftime('%Y-%m-%dT%H:%M:%SZ','now'), strftime('%Y-%m-%dT%H:%M:%SZ','now'))
       ON CONFLICT(id) DO UPDATE SET module_id=excluded.module_id, code=excluded.code, title=excluded.title, minutes=excluded.minutes, exercise_minutes=excluded.exercise_minutes, position=excluded.position, truth=excluded.truth, masterclass_json=excluded.masterclass_json, field_protocol_json=excluded.field_protocol_json, warnings_json=excluded.warnings_json, decoder_json=excluded.decoder_json, worksheets_json=excluded.worksheets_json, community_json=excluded.community_json, exercise_json=excluded.exercise_json, pass_json=excluded.pass_json, tool_links_json=excluded.tool_links_json, version=lessons.version+1, updated_at=strftime('%Y-%m-%dT%H:%M:%SZ','now');
INSERT INTO lessons (id, module_id, code, title, minutes, exercise_minutes, position, published, truth, masterclass_json, field_protocol_json, warnings_json, decoder_json, worksheets_json, community_json, exercise_json, pass_json, tool_links_json, print_asset, version, created_at, updated_at)
       VALUES ('m4l4', 'm4', '4.4', 'Adds & Next-Market Expansion Loops — One Station Into a Cascade', 8, 80, 3, 1, 'An add is not the finish line — it is a live seed. The Expansion Loop converts a single station victory into a domino cascade across neighboring regional markets.', '[{"b":"h","level":3,"spans":[{"t":"text","v":"Strategic Foundation & Operational Reality"}]},{"b":"p","spans":[{"t":"text","v":"When amateur artists secure a radio add, they celebrate on social media for 24 hours and consider the campaign finished. This is like striking oil and walking away without drilling a pipeline."}]},{"b":"p","spans":[{"t":"text","v":"In the music broadcasting industry, radio programmers monitor each other relentlessly. Non-comm and college music directors review Spinitron charts and NACC Top 200 reports weekly. Commercial programmers track Mediabase and BDS spin logs. When a recognized tastemaker station in a regional cluster adds a record, every neighboring station in that geographic corridor immediately experiences a drop in perceived risk."}]},{"b":"p","spans":[{"t":"text","v":"Dominion operators execute the "},{"t":"b","v":"Cascade Expansion Loop"},{"t":"text","v":"."}]},{"b":"p","spans":[{"t":"text","v":"The instant an add is confirmed at Station 1, that add becomes the lead S-Tier proof weapon to breach Stations 2, 3, 4, and 5 in the surrounding market perimeter."}]},{"b":"h","level":3,"spans":[{"t":"text","v":"The Anatomy of the Cascade Expansion Pitch"}]},{"b":"p","spans":[{"t":"text","v":"When you secure an add at a respected anchor station (e.g., WNUR in Chicago), you immediately dispatch a targeted "},{"t":"b","v":"Cascade Payload"},{"t":"text","v":" to adjacent Ring 2 and Ring 3 stations (e.g., WMSE in Milwaukee, WERG in Erie, WLRA in Romeoville):"}]},{"b":"list","ordered":false,"items":[{"spans":[{"t":"i","v":"The Subject Line:"},{"t":"text","v":" "},{"t":"code","v":"WNUR Add Cascade: Midwest Indie-Rock (2:58) · For [Target MD Name] / [Target Station]"}]},{"spans":[{"t":"i","v":"The Body Copy (Under 65 Words):"},{"t":"text","v":" "},{"t":"i","v":"\"Hi [Name] — thought you''d want this for your evening specialty queue: our single ''[Track Title]'' was added into rotation at WNUR this week following our sold-out Empty Bottle showcase. 2:58 run-time, FCC Clean, driving post-punk. Streaming link & Broadcast WAV: [Link]. Open to bringing this to [Target Station] listeners this week?\""}]}]},{"b":"h","level":3,"spans":[{"t":"text","v":"The 4-Phase Geographic Expansion Architecture"}]},{"b":"list","ordered":true,"items":[{"spans":[{"t":"b","v":"Phase 1: The Anchor Add (Ring 1 Foothold):"},{"t":"text","v":" Secure your primary station add in your home metro. Document the spin with official Spinitron timestamp screenshots."}]},{"spans":[{"t":"b","v":"Phase 2: The Corridor Cascade (Ring 2/3 Sweep):"},{"t":"text","v":" Within 48 hours of the anchor add, pitch the 10 closest regional stations in the same broadcast district citing the anchor add as lead validation."}]},{"spans":[{"t":"b","v":"Phase 3: The Chart Stacking (NACC / Specialty Aggregation):"},{"t":"text","v":" When 3 to 5 regional stations report spins, aggregate your spin totals to break onto regional college charts (e.g., NACC 200 or Regional Roots Charts)."}]},{"spans":[{"t":"b","v":"Phase 4: The Commercial Specialty Bridge:"},{"t":"text","v":" Deploy your college chart standing and multi-station broadcast proof to pitch evening specialty spotlight shows on commercial powerhouse stations (e.g., WXRT, KROQ, KNDD)."}]}]}]', '[{"b":"p","spans":[{"t":"b","v":"WAR-ROOM DIRECTIVE — 4.4 Adds & Next-Market Expansion Loops — One Station Into a Cascade"}]},{"b":"p","spans":[{"t":"b","v":"LEVERAGING A ROTATION UPGRADE AS A SECONDARY WIN"},{"t":"text","v":" When a station adds your song into light rotation or specialty play, your job at that station is not finished. You now initiate the "},{"t":"b","v":"Rotation Upgrade Sequence"},{"t":"text","v":":"}]},{"b":"list","ordered":true,"items":[{"spans":[{"t":"b","v":"Monitor On-Air Reaction:"},{"t":"text","v":" When your track airs, rally your regional community to tweet or text polite appreciation to the station studio line ("},{"t":"i","v":"\"Loved hearing [Artist Name] on the evening drive block!\""},{"t":"text","v":")."}]},{"spans":[{"t":"b","v":"The Listener Feedback Receipt:"},{"t":"text","v":" Within 10 days of the first spin, email the music director a brief note: "},{"t":"i","v":"\"Hi [Name] — thank you again for the spins on [Track Title]. We''ve seen a 30% spike in local Shazams across [City] and our club date on [Date] just sold out. If listener response warrants, we''d be thrilled to be considered for regular daytime medium rotation.\""}]},{"spans":[{"t":"text","v":"Moving from light specialty play to medium daytime rotation increases your weekly broadcast impressions by 400%. <!-- WARROOM:END -->"}]}]}]', '[]', '["The mechanic: adds are seeds.","The missing piece: adds happen in waves — when 2–3 land in one morning, the cycle is turning; that''s when the second wave fires with fresh proof.","The operator move: watch the wave, then escalate immediately. One morning of adds can become 11 by Friday if you re-fire with the receipts same-day."]', '[{"kind":"note","blocks":[{"b":"p","spans":[{"t":"text","v":"Complete the structured table below as part of your lesson implementation. This worksheet directly replaces legacy spreadsheets with a publication-grade execution protocol."}]}]},{"kind":"table","title":"CASCADE EXPANSION LOOP TARGETING TRACKER","headers":["Anchor Station Win","Add Confirmation Date","Cascade Target Station","Market & Dial","Cascade Angle & Hook","Deployment Status"],"rows":[["WNUR 89.3 (Evanston)","Day 9 Verified Add","WMSE 91.7 FM","Milwaukee, WI","Midwest regional I-94 corridor tie","Cascade Dispatched Day 10"],["WNUR 89.3 (Evanston)","Day 9 Verified Add","WICB 91.7 FM","Ithaca, NY","Leading college chart sibling format","Cascade Dispatched Day 10"],["WLUW 88.7 (Chicago)","Day 16 Verified Add","WERG 90.5 FM","Erie, PA","Rust Belt independent rock connection","Staged for Wave 3"],["WLUW 88.7 (Chicago)","Day 16 Verified Add","WSUM 91.7 FM","Madison, WI","Big Ten campus corridor synergy","Staged for Wave 3"],["WMSE 91.7 (Milwaukee)","Day 15 Verified Add","Radio K 100.7 FM","Minneapolis, MN","Twin Cities Midwest powerhouse hook","Staged for Wave 3"]]}]', '["Share your primary Anchor Station add and the five Cascade targets you have mapped around it.","Post your Cascade Pitch copy for critique. Ensure the anchor add is highlighted in the first 10 words.","Celebrate a peer''s recent station add by helping them identify adjacent sibling stations to target in their expansion loop.","Discuss your strategy for converting specialty show spins into permanent daytime rotation upgrades."]', '{"kind":"field-exercise","prompt":"Complete every drill below with real, verifiable answers, then confirm the pass standard.","items":[{"id":"d1","label":"The Expansion Target Mapping Sprint","description":"The Expansion Target Mapping Sprint . For your #1 target anchor station, identify five direct geographic or format sibling stations in adjacent markets. Populate the Cascade Expansion Worksheet below.","minutes":25,"type":"response","passStandard":null},{"id":"d2","label":"The Cascade Pitch Template Construction","description":"The Cascade Pitch Template Construction . Draft a customized Cascade Payload referencing your anchor station''s confirmed spin. Ensure the copy sits strictly under 65 words.","minutes":20,"type":"response","passStandard":null},{"id":"d3","label":"The Airplay Receipt Capture Drill","description":"The Airplay Receipt Capture Drill . Set up real-time Google Alerts and Spinitron tracking for your artist name and song title. Prepare a high-resolution screenshot template for logging on-air proof.","minutes":15,"type":"response","passStandard":null},{"id":"d4","label":"The Tour Corridor Linkage","description":"The Tour Corridor Linkage . Map how your cascading radio adds connect directly into your upcoming live performance tour routing.","minutes":20,"type":"response","passStandard":null}],"worksheets":[{"kind":"table","title":"CASCADE EXPANSION LOOP TARGETING TRACKER","headers":["Anchor Station Win","Add Confirmation Date","Cascade Target Station","Market & Dial","Cascade Angle & Hook","Deployment Status"],"rows":[["WNUR 89.3 (Evanston)","Day 9 Verified Add","WMSE 91.7 FM","Milwaukee, WI","Midwest regional I-94 corridor tie","Cascade Dispatched Day 10"],["WNUR 89.3 (Evanston)","Day 9 Verified Add","WICB 91.7 FM","Ithaca, NY","Leading college chart sibling format","Cascade Dispatched Day 10"],["WLUW 88.7 (Chicago)","Day 16 Verified Add","WERG 90.5 FM","Erie, PA","Rust Belt independent rock connection","Staged for Wave 3"],["WLUW 88.7 (Chicago)","Day 16 Verified Add","WSUM 91.7 FM","Madison, WI","Big Ten campus corridor synergy","Staged for Wave 3"],["WMSE 91.7 (Milwaukee)","Day 15 Verified Add","Radio K 100.7 FM","Minneapolis, MN","Twin Cities Midwest powerhouse hook","Staged for Wave 3"]]}],"confirmations":[{"id":"community","text":"One community drill answered (optional but strengthens calibration).","required":false}]}', '{"policy":"all-responses-min-words","minWords":40,"requireAllDrills":true,"requireWorksheetCells":0,"note":""}', '[{"to":"/frequency-dominion/app/campaign","label":"21-Day Campaign board"}]', 'courses/frequency-dominion/frequency-dominion-course.zip', 1, strftime('%Y-%m-%dT%H:%M:%SZ','now'), strftime('%Y-%m-%dT%H:%M:%SZ','now'))
       ON CONFLICT(id) DO UPDATE SET module_id=excluded.module_id, code=excluded.code, title=excluded.title, minutes=excluded.minutes, exercise_minutes=excluded.exercise_minutes, position=excluded.position, truth=excluded.truth, masterclass_json=excluded.masterclass_json, field_protocol_json=excluded.field_protocol_json, warnings_json=excluded.warnings_json, decoder_json=excluded.decoder_json, worksheets_json=excluded.worksheets_json, community_json=excluded.community_json, exercise_json=excluded.exercise_json, pass_json=excluded.pass_json, tool_links_json=excluded.tool_links_json, version=lessons.version+1, updated_at=strftime('%Y-%m-%dT%H:%M:%SZ','now');
INSERT INTO lessons (id, module_id, code, title, minutes, exercise_minutes, position, published, truth, masterclass_json, field_protocol_json, warnings_json, decoder_json, worksheets_json, community_json, exercise_json, pass_json, tool_links_json, print_asset, version, created_at, updated_at)
       VALUES ('m5l1', 'm5', '5.1', 'High-Value Calls — The 12-Minute Relationship Call', 8, 70, 0, 1, 'One disciplined 12-minute phone conversation accomplishes more than twenty unread emails. The call is not a sales pitch — it is an elite relationship reconnaissance mission.', '[{"b":"h","level":3,"spans":[{"t":"text","v":"Strategic Foundation & Operational Reality"}]},{"b":"p","spans":[{"t":"text","v":"In an era where every independent artist hides behind automated software, DMs, and generic email blasts, picking up the telephone has become a superpower. A phone call humanizes you instantly. It cuts through digital noise, establishes instant vocal rapport, and signals profound professional confidence."}]},{"b":"p","spans":[{"t":"text","v":"However, cold calling a busy commercial program director without an operational protocol is professional suicide. If you call uninvited, ramble for 10 minutes about your creative vision, and demand that they listen to your song, you will be permanently branded as an obnoxious pest."}]},{"b":"p","spans":[{"t":"text","v":"Dominion operators execute "},{"t":"b","v":"High-Value Relationship Calls"},{"t":"text","v":" strictly under defined tactical conditions."}]},{"b":"h","level":3,"spans":[{"t":"text","v":"When to Call (The Three Green-Light Triggers)"}]},{"b":"p","spans":[{"t":"text","v":"Never cold-call a commercial programmer out of the blue. Execute a call strictly when one of these three operational triggers has been met:"}]},{"b":"list","ordered":true,"items":[{"spans":[{"t":"b","v":"The Warm Dialogue Trigger:"},{"t":"text","v":" The programmer has opened your pitch, replied via email, or requested assets, but has not yet confirmed an add."}]},{"spans":[{"t":"b","v":"The Confirmed Tour Hook Trigger:"},{"t":"text","v":" You are confirmed to perform in their market within 14 days, and you are calling to coordinate on-air ticket giveaways or a studio drop-in during load-in."}]},{"spans":[{"t":"b","v":"The Published Call-In Hours Window:"},{"t":"text","v":" College, community, and non-commercial music directors explicitly publish \"Music Tracking Hours\" (e.g., "},{"t":"i","v":"Wednesdays 2:00 PM – 4:00 PM EST"},{"t":"text","v":") specifically to take calls from independent artists and promoters."}]}]},{"b":"h","level":3,"spans":[{"t":"text","v":"The 12-Minute Call Anatomy & Agenda"}]},{"b":"p","spans":[{"t":"text","v":"A high-value radio call is brief, focused, and respectful of the clock. Execute across five chronological phases:"}]},{"b":"list","ordered":false,"items":[{"spans":[{"t":"b","v":"Phase 1: The 20-Second Opening Hook (0:00 – 0:40):"},{"t":"text","v":" Name, artist identity, quick reference to recent email or local date, and immediate confirmation of availability: "},{"t":"i","v":"\"Hi Tom — this is Alex from The Replicas. Following up on the Chicago show date and email I sent Tuesday. Do you have three quick minutes between programming clocks?\""}]},{"spans":[{"t":"b","v":"Phase 2: The Sincere Station Commendation (0:40 – 2:00):"},{"t":"text","v":" Mention a specific recent spin, specialty show feature, or station initiative you genuinely heard and appreciated. Prove you actually listen to their broadcast."}]},{"spans":[{"t":"b","v":"Phase 3: The Discovery Question (2:00 – 5:00):"},{"t":"text","v":" Ask the critical programming question: "},{"t":"i","v":"\"What specific sonic niche or tempo does your evening block need right now that current label submissions are missing?\""},{"t":"text","v":" Listen intently. Take verbatim notes."}]},{"spans":[{"t":"b","v":"Phase 4: The Aligned Solution Bridge (5:00 – 9:00):"},{"t":"text","v":" Connect their stated programming need directly to your record or upcoming live tour date. Offer the tailored solution."}]},{"spans":[{"t":"b","v":"Phase 5: The Frictionless Close & Next Action (9:00 – 12:00):"},{"t":"text","v":" Agree on one immediate next step. Never force an on-the-spot commitment. Confirm delivery of the requested asset and gracefully exit before 12 minutes elapse."}]}]}]', '[{"b":"p","spans":[{"t":"b","v":"WAR-ROOM DIRECTIVE — 5.1 High-Value Calls — The 12-Minute Relationship Call"}]},{"b":"p","spans":[{"t":"b","v":"THE THREE FATAL MISTAKES OF CALLING MUSIC DIRECTORS"}]},{"b":"list","ordered":true,"items":[{"spans":[{"t":"b","v":"Calling on Monday Morning or Friday Afternoon:"},{"t":"text","v":" These are administrative nightmare hours. Call strictly during published tracking hours or mid-week afternoons (Tuesday through Thursday between 2:00 PM and 4:30 PM local)."}]},{"spans":[{"t":"b","v":"Asking ''Did you listen to my CD/email?'':"},{"t":"text","v":" This puts the programmer on the defensive and makes them feel guilty. Instead, ask: "},{"t":"i","v":"\"Calling to verify you have everything you need for our upcoming show date at [Venue] on [Date].\""}]},{"spans":[{"t":"b","v":"Overstaying Your Welcome:"},{"t":"text","v":" The moment the clock strikes 11 or 12 minutes, proactively wrap up: "},{"t":"i","v":"\"Tom, I know you have a programming meeting at the top of the hour. Thank you so much for your time. I''ll get that clean WAV over to your inbox within ten minutes.\""},{"t":"text","v":" Exiting early demonstrates immense respect for their professional schedule. <!-- WARROOM:END -->"}]}]}]', '["Dominion operators execute High-Value Relationship Calls strictly under defined tactical conditions. ### When to Call (The Three Green-Light Triggers) Never cold-call a commercial programmer out of the blue.","Never force an on-the-spot commitment."]', '["The mechanic: 12 minutes, one ask.","The missing piece: the call''s third question — \"when''s your add cycle?\" — unlocks the calendar for every future campaign.","The operator move: end every call with a date, not a hope. \"Checking back [date]\" is the next-step weapon."]', '[{"kind":"note","blocks":[{"b":"p","spans":[{"t":"text","v":"Complete the structured table below as part of your lesson implementation. This worksheet directly replaces legacy spreadsheets with a publication-grade execution protocol."}]}]},{"kind":"table","title":"12-MINUTE RELATIONSHIP CALL BRIEFING SHEET","headers":["Target Gatekeeper","Station & Direct Office Phone","Tracking Call Window","20-Second Opening Hook","Discovery Question Hook","Agreed Next Operational Step"],"rows":[["Sarah Jenkins (MD)","WLUW (773-508-8080)","Tuesdays 2:00-4:00 PM CST","Following up on Empty Bottle gig brief","What tempos are missing in evening drive?","Send 30s hook cut by 5:00 PM"],["Alex Rivera (MD)","WNUR (847-866-9687)","Wednesdays 1:00-3:00 PM CST","Referencing Evanston campus showcase","Looking for upcoming live studio sessions?","Deliver broadcast WAV master"],["Tom Crawford (PD)","WMSE (414-277-7247)","Thursdays 10:00 AM-Noon CST","Touching base on Cactus Club tour date","How is local ticket reaction tracking?","Deliver listener ticket giveaway pack"],["Marcus Vance (MD)","Radio K (612-626-4600)","Mondays 3:00-5:00 PM CST","Following up on Twin Cities indie push","Reviewing new college chart entries?","Confirm add on Friday NACC chart"],["Elena Rostova (MD)","WCSB (216-687-3523)","Tuesdays 1:00-3:00 PM EST","Following up on Cleveland Grog Shop date","Curating local specialty indie block?","Provide custom station ID drop"]]}]', '["Post your recorded 20-Second Phone Opening Hook audio or transcript for feedback.","Share an experience of your first successful radio phone call and what insights you uncovered.","Identify the published music tracking hours for three college or non-comm stations on your target list.","Discuss how you overcame call reluctance and transitioned into high-conviction communication."]', '{"kind":"field-exercise","prompt":"Complete every drill below with real, verifiable answers, then confirm the pass standard.","items":[{"id":"d1","label":"The 20-Second Phone Opening Script","description":"The 20-Second Phone Opening Script . Draft and rehearse your 20-second opening hook aloud. Record yourself on your phone. Refine until your delivery sounds natural, authoritative, and relaxed.","minutes":20,"type":"response","passStandard":null},{"id":"d2","label":"The Station Call Sheet Pre-Flight","description":"The Station Call Sheet Pre-Flight . Complete the 12-Minute Call Briefing Sheet below for your top warm target station. Document gatekeeper name, direct studio/office line, recent station spins, and local tie-in.","minutes":20,"type":"response","passStandard":null},{"id":"d3","label":"The Active Listening Rehearsal","description":"The Active Listening Rehearsal . Practice asking the Discovery Question (\"What is your programming missing right now?\") without interrupting for 90 seconds of simulated silence.","minutes":15,"type":"response","passStandard":null},{"id":"d4","label":"The Follow-Up Recap Email Sprint","description":"The Follow-Up Recap Email Sprint . Draft an immediate post-call confirmation email summarizing the conversation and delivering the exact agreed asset within 30 minutes of call conclusion.","minutes":15,"type":"response","passStandard":null}],"worksheets":[{"kind":"table","title":"12-MINUTE RELATIONSHIP CALL BRIEFING SHEET","headers":["Target Gatekeeper","Station & Direct Office Phone","Tracking Call Window","20-Second Opening Hook","Discovery Question Hook","Agreed Next Operational Step"],"rows":[["Sarah Jenkins (MD)","WLUW (773-508-8080)","Tuesdays 2:00-4:00 PM CST","Following up on Empty Bottle gig brief","What tempos are missing in evening drive?","Send 30s hook cut by 5:00 PM"],["Alex Rivera (MD)","WNUR (847-866-9687)","Wednesdays 1:00-3:00 PM CST","Referencing Evanston campus showcase","Looking for upcoming live studio sessions?","Deliver broadcast WAV master"],["Tom Crawford (PD)","WMSE (414-277-7247)","Thursdays 10:00 AM-Noon CST","Touching base on Cactus Club tour date","How is local ticket reaction tracking?","Deliver listener ticket giveaway pack"],["Marcus Vance (MD)","Radio K (612-626-4600)","Mondays 3:00-5:00 PM CST","Following up on Twin Cities indie push","Reviewing new college chart entries?","Confirm add on Friday NACC chart"],["Elena Rostova (MD)","WCSB (216-687-3523)","Tuesdays 1:00-3:00 PM EST","Following up on Cleveland Grog Shop date","Curating local specialty indie block?","Provide custom station ID drop"]]}],"confirmations":[{"id":"community","text":"One community drill answered (optional but strengthens calibration).","required":false}]}', '{"policy":"all-responses-min-words","minWords":40,"requireAllDrills":true,"requireWorksheetCells":0,"note":""}', '[{"to":"/frequency-dominion/app/stations","label":"Station records & touch log"}]', 'courses/frequency-dominion/frequency-dominion-course.zip', 1, strftime('%Y-%m-%dT%H:%M:%SZ','now'), strftime('%Y-%m-%dT%H:%M:%SZ','now'))
       ON CONFLICT(id) DO UPDATE SET module_id=excluded.module_id, code=excluded.code, title=excluded.title, minutes=excluded.minutes, exercise_minutes=excluded.exercise_minutes, position=excluded.position, truth=excluded.truth, masterclass_json=excluded.masterclass_json, field_protocol_json=excluded.field_protocol_json, warnings_json=excluded.warnings_json, decoder_json=excluded.decoder_json, worksheets_json=excluded.worksheets_json, community_json=excluded.community_json, exercise_json=excluded.exercise_json, pass_json=excluded.pass_json, tool_links_json=excluded.tool_links_json, version=lessons.version+1, updated_at=strftime('%Y-%m-%dT%H:%M:%SZ','now');
INSERT INTO lessons (id, module_id, code, title, minutes, exercise_minutes, position, published, truth, masterclass_json, field_protocol_json, warnings_json, decoder_json, worksheets_json, community_json, exercise_json, pass_json, tool_links_json, print_asset, version, created_at, updated_at)
       VALUES ('m5l2', 'm5', '5.2', 'The Thank-You Economy — Tiny Gestures, Lifelong Allies', 8, 75, 1, 1, 'The difference between a station that plays you once and a station that champions your entire ten-year career is what you do in the 48 hours after they add your song.', '[{"b":"h","level":3,"spans":[{"t":"text","v":"Strategic Foundation & Operational Reality"}]},{"b":"p","spans":[{"t":"text","v":"The average independent artist behaves like an emotional consumer: when they want something, they are hyper-attentive; the second they receive an add, they vanish until their next release nine months later."}]},{"b":"p","spans":[{"t":"text","v":"Music directors and DJs frequently remark that radio promotion is a thankless grind. They take professional risks on unproven independent records, carve out airtime on their shows, and in 95% of cases, receive zero acknowledgment, zero listener feedback, and zero gratitude from the artist."}]},{"b":"p","spans":[{"t":"text","v":"Dominion operators dominate through the "},{"t":"b","v":"Thank-You Economy"},{"t":"text","v":"."}]},{"b":"p","spans":[{"t":"text","v":"Gratitude is not merely good manners; it is a profound commercial weapon. When a programmer takes a risk on your music and experiences immediate, overwhelming, authentic gratitude, you permanently imprint yourself on their memory. You transform a one-off transactional spin into a multi-year institutional alliance."}]},{"b":"h","level":3,"spans":[{"t":"text","v":"The Four Tiers of the Gratitude Protocol"}]},{"b":"p","spans":[{"t":"text","v":"Execute this four-stage gratitude cascade the moment a station confirms an add or airs your record:"}]},{"b":"list","ordered":false,"items":[{"spans":[{"t":"b","v":"Tier 1: Immediate Public Social Amplification (Within 2 Hours of Airplay):"},{"t":"text","v":" Tag the station, the specific DJ, and the show across your social channels. Do not simply post "},{"t":"i","v":"\"We''re on the radio!\""},{"t":"text","v":" Post an authentic, station-first tribute: "},{"t":"i","v":"\"Huge love to @WLUW and @DJName for championing local independent music on the Afternoon Drive. Tune into 88.7 FM or stream live at wluw.org.\""},{"t":"text","v":" Drive your audience to "},{"t":"i","v":"their"},{"t":"text","v":" stream."}]},{"spans":[{"t":"b","v":"Tier 2: The Direct Executive Thank-You Email (Within 24 Hours):"},{"t":"text","v":" Dispatch a personalized, private email to the Music Director: "},{"t":"i","v":"\"Hi Sarah — heard the spin on today''s 4:00 PM block. The sound quality was incredible. Thank you for believing in this record and putting your trust in our music. We''re indebted to you and the WLUW family.\""},{"t":"text","v":" Zero asks attached."}]},{"spans":[{"t":"b","v":"Tier 3: The Custom Station ID / Sweeper Drop (Within 48 Hours):"},{"t":"text","v":" Deliver a studio-grade customized station identification drop: "},{"t":"i","v":"\"Hey, this is [Artist Name], and whenever we''re driving through [City], our dial is locked to [Station Callsign].\""},{"t":"text","v":"(See Lesson 3.4 specs)."}]},{"spans":[{"t":"b","v":"Tier 4: The Physical Handwritten Postcard (Show Week / Month 1):"},{"t":"text","v":" Mail a physical, handwritten postcard or letter directly to the station studio address addressed to the specific DJ or MD. In a world of 50,000 digital notifications, a physical card sitting on a DJ''s broadcast console is permanent, physical real estate."}]}]}]', '[{"b":"p","spans":[{"t":"b","v":"WAR-ROOM DIRECTIVE — 5.2 The Thank-You Economy — Tiny Gestures, Lifelong Allies"}]},{"b":"p","spans":[{"t":"b","v":"NEVER ATTACH AN ASK TO A THANK-YOU MESSAGE"},{"t":"text","v":" The fatal mistake artists make in the Thank-You Economy is contaminating their gratitude with a secondary pitch:"}]},{"b":"list","ordered":false,"items":[{"spans":[{"t":"i","v":"Fatal Approach:"},{"t":"text","v":" "},{"t":"i","v":"\"Thanks so much for adding our single! By the way, can you also play our acoustic b-side and interview us this Friday?\""}]}]},{"b":"p","spans":[{"t":"text","v":"The instant you attach an ask to a thank-you note, the programmer realizes your gratitude was transactional manipulation."}]},{"b":"p","spans":[{"t":"b","v":"THE LAW OF UNCONTAMINATED GRATITUDE:"},{"t":"text","v":" When you express gratitude, make it "},{"t":"b","v":"100% pure"},{"t":"text","v":"."}]},{"b":"list","ordered":false,"items":[{"spans":[{"t":"text","v":"Zero requests."}]},{"spans":[{"t":"text","v":"Zero links to new music."}]},{"spans":[{"t":"text","v":"Zero commercial demands. Leave the programmer feeling appreciated, validated, and respected. They will remember your purity of intent when you return with your next release. <!-- WARROOM:END -->"}]}]}]', '["Do not simply post \"We''re on the radio!\" Post an authentic, station-first tribute: \"Huge love to @WLUW and @DJName for championing local independent music on the Afternoon Drive."]', '["The mechanic: specific gratitude, then assets, then one ask.","The missing piece: the gesture is one rung above the ask — if you want champion behavior, give confidant respect first.","The operator move: never attach an ask to a thank-you. The zero-ask window is the strategic move; the ask at week 5 lands on a relationship, not a transaction."]', '[{"kind":"note","blocks":[{"b":"p","spans":[{"t":"text","v":"Complete the structured table below as part of your lesson implementation. This worksheet directly replaces legacy spreadsheets with a publication-grade execution protocol."}]}]},{"kind":"table","title":"THE GRATITUDE CASCADE & ALLY LEDGER","headers":["Station Callsign","Decision Maker / DJ","Add Confirmation Date","Social Tag Dispatched","Email Thank-You Sent","Physical Card Delivered"],"rows":[["WLUW 88.7 FM","Sarah Jenkins (MD)","October 12","COMPLETED (Day 0)","COMPLETED (Day 1)","MAILED (Day 3)"],["WNUR 89.3 FM","Alex Rivera (MD)","October 14","COMPLETED (Day 0)","COMPLETED (Day 1)","MAILED (Day 3)"],["WMSE 91.7 FM","Tom Crawford (PD)","October 18","COMPLETED (Day 0)","COMPLETED (Day 1)","MAILED (Day 4)"],["Radio K 100.7","Marcus Vance (MD)","Pending Wave 2","Staged Draft Ready","Staged Draft Ready","Card Pre-Addressed"],["KUTX 98.9 FM","Rick McNulty (MD)","Pending Wave 2","Staged Draft Ready","Staged Draft Ready","Card Pre-Addressed"]]}]', '["Share your station-first Social Amplification post celebrating a recent add or feature.","Post a photo of your handwritten station postcards ready for mailing.","Discuss how expressing genuine gratitude changed your relationship with a specific industry gatekeeper.","Confirm that your Gratitude Ledger is synchronized with your active War Room Cockpit."]', '{"kind":"field-exercise","prompt":"Complete every drill below with real, verifiable answers, then confirm the pass standard.","items":[{"id":"d1","label":"The Social Amplification Template Suite","description":"The Social Amplification Template Suite . Pre-draft three distinct social media gratitude templates that elevate the radio station, the DJ, and the broadcast frequency before mentioning yourself.","minutes":20,"type":"response","passStandard":null},{"id":"d2","label":"The Station Studio Physical Address Vault","description":"The Station Studio Physical Address Vault . Look up the physical mailing addresses for the broadcast studios of your top 10 War Room stations. Populate the Gratitude Ledger below.","minutes":25,"type":"response","passStandard":null},{"id":"d3","label":"The Handwritten Postcard Stocking","description":"The Handwritten Postcard Stocking . Purchase a pack of 20 high-quality local postcards or custom artist stationery. Pre-stamp them and keep them in your studio desk.","minutes":15,"type":"response","passStandard":null},{"id":"d4","label":"The Gratitude Ledger Audit","description":"The Gratitude Ledger Audit . Review all historical station spins you have ever received. Confirm that 100% of past supporters have received a formal thank-you message.","minutes":15,"type":"response","passStandard":null}],"worksheets":[{"kind":"table","title":"THE GRATITUDE CASCADE & ALLY LEDGER","headers":["Station Callsign","Decision Maker / DJ","Add Confirmation Date","Social Tag Dispatched","Email Thank-You Sent","Physical Card Delivered"],"rows":[["WLUW 88.7 FM","Sarah Jenkins (MD)","October 12","COMPLETED (Day 0)","COMPLETED (Day 1)","MAILED (Day 3)"],["WNUR 89.3 FM","Alex Rivera (MD)","October 14","COMPLETED (Day 0)","COMPLETED (Day 1)","MAILED (Day 3)"],["WMSE 91.7 FM","Tom Crawford (PD)","October 18","COMPLETED (Day 0)","COMPLETED (Day 1)","MAILED (Day 4)"],["Radio K 100.7","Marcus Vance (MD)","Pending Wave 2","Staged Draft Ready","Staged Draft Ready","Card Pre-Addressed"],["KUTX 98.9 FM","Rick McNulty (MD)","Pending Wave 2","Staged Draft Ready","Staged Draft Ready","Card Pre-Addressed"]]}],"confirmations":[{"id":"community","text":"One community drill answered (optional but strengthens calibration).","required":false}]}', '{"policy":"all-responses-min-words","minWords":40,"requireAllDrills":true,"requireWorksheetCells":0,"note":""}', '[{"to":"/frequency-dominion/app/stations","label":"Station records & touch log"}]', 'courses/frequency-dominion/frequency-dominion-course.zip', 1, strftime('%Y-%m-%dT%H:%M:%SZ','now'), strftime('%Y-%m-%dT%H:%M:%SZ','now'))
       ON CONFLICT(id) DO UPDATE SET module_id=excluded.module_id, code=excluded.code, title=excluded.title, minutes=excluded.minutes, exercise_minutes=excluded.exercise_minutes, position=excluded.position, truth=excluded.truth, masterclass_json=excluded.masterclass_json, field_protocol_json=excluded.field_protocol_json, warnings_json=excluded.warnings_json, decoder_json=excluded.decoder_json, worksheets_json=excluded.worksheets_json, community_json=excluded.community_json, exercise_json=excluded.exercise_json, pass_json=excluded.pass_json, tool_links_json=excluded.tool_links_json, version=lessons.version+1, updated_at=strftime('%Y-%m-%dT%H:%M:%SZ','now');
INSERT INTO lessons (id, module_id, code, title, minutes, exercise_minutes, position, published, truth, masterclass_json, field_protocol_json, warnings_json, decoder_json, worksheets_json, community_json, exercise_json, pass_json, tool_links_json, print_asset, version, created_at, updated_at)
       VALUES ('m5l3', 'm5', '5.3', 'Burned-Well Repair — The 5-Step Protocol for Salvaged Relationships', 8, 70, 2, 1, 'Every working artist has burned wells — past spam blasts, ghosted interviews, broken deadlines. The 5-Step Repair Protocol reopens doors you thought were locked forever.', '[{"b":"h","level":3,"spans":[{"t":"text","v":"Strategic Foundation & Operational Reality"}]},{"b":"p","spans":[{"t":"text","v":"If you have been active in the independent music industry for more than two years, you have almost certainly committed amateur mistakes:"}]},{"b":"list","ordered":false,"items":[{"spans":[{"t":"text","v":"You sent an impersonal mass BCC email blast to 500 radio stations."}]},{"spans":[{"t":"text","v":"You pitched a track with a broken download link and never followed up."}]},{"spans":[{"t":"text","v":"You were offered an on-air phone interview and overslept or missed the time slot."}]},{"spans":[{"t":"text","v":"You reacted defensively or impatiently when a programmer declined your submission."}]}]},{"b":"p","spans":[{"t":"text","v":"Most artists believe that once a relationship is burned, the station is lost forever. They feel intense embarrassment, permanently avoid the station, and surrender that media market."}]},{"b":"p","spans":[{"t":"text","v":"Dominion operators practice "},{"t":"b","v":"Relational Engineering"},{"t":"text","v":"."}]},{"b":"p","spans":[{"t":"text","v":"Programmers understand that young artists make mistakes. What programmers cannot tolerate is chronic arrogance and denial. When an artist demonstrates radical professional accountability, takes unreserved ownership of a past error, and approaches with quiet humility, a burned well can be transformed into one of your staunchest institutional allies."}]},{"b":"h","level":3,"spans":[{"t":"text","v":"The 5-Step Burned-Well Repair Protocol"}]},{"b":"p","spans":[{"t":"text","v":"To salvage and restore a compromised station relationship, execute this disciplined sequence:"}]},{"b":"list","ordered":true,"items":[{"spans":[{"t":"b","v":"Step 1: The 90-Day Mandatory Cooling Window:"},{"t":"text","v":" Do not attempt immediate repair while emotions or annoyance are fresh. Initiate a mandatory 90-day silent cooling period. Zero outreach."}]},{"spans":[{"t":"b","v":"Step 2: The Low-Stakes Engagement Signal (Reconnaissance):"},{"t":"text","v":" Re-engage on public social channels without pitching. Retweet a station announcement, comment thoughtfully on an editorial post, or support a station fundraising drive. Signal presence without commercial pressure."}]},{"spans":[{"t":"b","v":"Step 3: The Radical Ownership Memo (The Apology):"},{"t":"text","v":" Dispatch a private, 50-word ownership memo directly to the offended programmer:"}]},{"spans":[{"t":"i","v":"Script:"},{"t":"text","v":" "},{"t":"i","v":"\"Hi [Name] — looking back at my email blast from last year, I realize how unprofessional that approach was. I was unguided and treating radio like a broadcast spam cannon rather than respecting your curation and clock. I apologize. We''ve completely overhauled our operating standards. Thank you for your continued dedication to the local scene.\""}]},{"spans":[{"t":"i","v":"Rule:"},{"t":"text","v":" "},{"t":"b","v":"ZERO PITCH."},{"t":"text","v":" No songs attached. No links. Total ownership."}]},{"spans":[{"t":"b","v":"Step 4: The Value-First Bridge:"},{"t":"text","v":" 30 days after the apology memo, deliver an uncontaminated value asset: share a station event link, introduce a fellow touring act that matches their format, or attend a station live event as a paying ticket buyer."}]},{"spans":[{"t":"b","v":"Step 5: The Clean Re-Entry Payload:"},{"t":"text","v":" 60 days following the apology, introduce your newest, strongest, format-scored single using the standard 90-word pitch. The gatekeeper will remember your character and maturity."}]}]}]', '[{"b":"p","spans":[{"t":"b","v":"WAR-ROOM DIRECTIVE — 5.3 Burned-Well Repair — The 5-Step Protocol for Salvaged Relationships"}]},{"b":"p","spans":[{"t":"b","v":"WHY AN EFFECTIVE APOLOGY TURNS GATEKEEPERS INTO CHAMPIONS"},{"t":"text","v":" Programmers deal with hundreds of narcissistic, entitled musicians every month who believe the world owes them fame. They almost NEVER encounter an artist mature enough to say: "},{"t":"i","v":"\"I made a mistake, I was unprofessional, and I respect your craft too much to repeat it.\""}]},{"b":"p","spans":[{"t":"text","v":"When you send a radical ownership memo, you instantly separate yourself from 99.9% of independent musicians. You prove high emotional intelligence, professional resilience, and character. Programmers will often reply to an apology within hours with warm words: "},{"t":"i","v":"\"Appreciate this so much, man. Send over your new record whenever it''s ready.\""}]}]', '["Step 1: The 90-Day Mandatory Cooling Window: Do not attempt immediate repair while emotions or annoyance are fresh.","Send over your new record whenever it''s ready.\" <!-- WARROOM:END --> ## FREQUENCY DOMINION COMMUNITY DRILLS 1."]', '["The mechanic: honest bridge, 90-day cooling.","The missing piece: triage by ROI — the ghosted well recovers fastest; the spammed well needs the full cooling; the clash well only works if the format or MD changed.","The operator move: check the playlist before repairing a clash well. If the lineup changed, the well is new soil — and the repair is a fresh pitch."]', '[{"kind":"note","blocks":[{"b":"p","spans":[{"t":"text","v":"Complete the structured table below as part of your lesson implementation. This worksheet directly replaces legacy spreadsheets with a publication-grade execution protocol."}]}]},{"kind":"table","title":"BURNED-WELL REPAIR PROTOCOL & SALVAGE LOG","headers":["Station & Gatekeeper","Nature of Past Burn","Cooling Window Expiry","Apology Memo Sent","Value Bridge Asset","Re-Entry Target Date"],"rows":[["WLUW (Sarah Jenkins)","Mass BCC email blast sent in 2024","November 1","Staged (Draft Ready)","Share station fund drive link","December 15 Single Launch"],["WMSE (Tom Crawford)","Missed phone tracking interview","October 20","Staged (Draft Ready)","Attend WMSE record fair in person","January Tour Campaign"],["KUTX (Rick McNulty)","Unformatted 7-minute prog track sent","December 1","Staged (Draft Ready)","Promote Austin local band showcase","Spring Release Cycle"],["Radio K (Marcus Vance)","Passive-aggressive reply to decline","November 15","Staged (Draft Ready)","College radio benefit donation","February Campaign"],["WXPN (Bruce Warren)","Spammed generic inbox 4x in one week","January 15","Staged (Draft Ready)","Share World Cafe feature on socials","March Release Cycle"]]}]', '["Share an honest admission of a past relationship burn and post your drafted Radical Ownership Memo for feedback.","Discuss the emotional difficulty of admitting unprofessional behavior and how taking ownership empowers your career.","Confirm the start and completion dates for your 90-Day Cooling Window.","Celebrate any peer who successfully re-opened a dialogue with a previously burned contact."]', '{"kind":"field-exercise","prompt":"Complete every drill below with real, verifiable answers, then confirm the pass standard.","items":[{"id":"d1","label":"The Honest Burned-Well Audit","description":"The Honest Burned-Well Audit . Conduct a fearless inventory of every station relationship you have damaged or neglected over your career. Populate the Burned-Well Repair Log below.","minutes":25,"type":"response","passStandard":null},{"id":"d2","label":"The Radical Ownership Memo Drafting","description":"The Radical Ownership Memo Drafting . Draft a tailored 50-word apology memo for your single most valuable burned contact. Verify that it contains zero excuses, zero defensive qualifications, and zero music links.","minutes":20,"type":"response","passStandard":null},{"id":"d3","label":"Cooling Window Calendar Staging","description":"Cooling Window Calendar Staging . Mark the 90-day cooling completion date in your calendar for all identified burned contacts.","minutes":10,"type":"response","passStandard":null},{"id":"d4","label":"The Value Bridge Brainstorm","description":"The Value Bridge Brainstorm . Identify one tangible, non-musical value asset you can deliver to that programmer once the cooling window concludes.","minutes":15,"type":"response","passStandard":null}],"worksheets":[{"kind":"table","title":"BURNED-WELL REPAIR PROTOCOL & SALVAGE LOG","headers":["Station & Gatekeeper","Nature of Past Burn","Cooling Window Expiry","Apology Memo Sent","Value Bridge Asset","Re-Entry Target Date"],"rows":[["WLUW (Sarah Jenkins)","Mass BCC email blast sent in 2024","November 1","Staged (Draft Ready)","Share station fund drive link","December 15 Single Launch"],["WMSE (Tom Crawford)","Missed phone tracking interview","October 20","Staged (Draft Ready)","Attend WMSE record fair in person","January Tour Campaign"],["KUTX (Rick McNulty)","Unformatted 7-minute prog track sent","December 1","Staged (Draft Ready)","Promote Austin local band showcase","Spring Release Cycle"],["Radio K (Marcus Vance)","Passive-aggressive reply to decline","November 15","Staged (Draft Ready)","College radio benefit donation","February Campaign"],["WXPN (Bruce Warren)","Spammed generic inbox 4x in one week","January 15","Staged (Draft Ready)","Share World Cafe feature on socials","March Release Cycle"]]}],"confirmations":[{"id":"community","text":"One community drill answered (optional but strengthens calibration).","required":false}]}', '{"policy":"all-responses-min-words","minWords":40,"requireAllDrills":true,"requireWorksheetCells":0,"note":""}', '[{"to":"/frequency-dominion/app/stations","label":"Station records & touch log"}]', 'courses/frequency-dominion/frequency-dominion-course.zip', 1, strftime('%Y-%m-%dT%H:%M:%SZ','now'), strftime('%Y-%m-%dT%H:%M:%SZ','now'))
       ON CONFLICT(id) DO UPDATE SET module_id=excluded.module_id, code=excluded.code, title=excluded.title, minutes=excluded.minutes, exercise_minutes=excluded.exercise_minutes, position=excluded.position, truth=excluded.truth, masterclass_json=excluded.masterclass_json, field_protocol_json=excluded.field_protocol_json, warnings_json=excluded.warnings_json, decoder_json=excluded.decoder_json, worksheets_json=excluded.worksheets_json, community_json=excluded.community_json, exercise_json=excluded.exercise_json, pass_json=excluded.pass_json, tool_links_json=excluded.tool_links_json, version=lessons.version+1, updated_at=strftime('%Y-%m-%dT%H:%M:%SZ','now');
INSERT INTO lessons (id, module_id, code, title, minutes, exercise_minutes, position, published, truth, masterclass_json, field_protocol_json, warnings_json, decoder_json, worksheets_json, community_json, exercise_json, pass_json, tool_links_json, print_asset, version, created_at, updated_at)
       VALUES ('m5l4', 'm5', '5.4', 'Relationship Compounding — The 90-Day Ally Engine', 8, 95, 3, 1, 'One radio add is a transaction. Thirty lifetime allies is an unbreachable commercial moat. The 90-Day Ally Engine compounds relationships on a calendar schedule that never sleeps.', '[{"b":"h","level":3,"spans":[{"t":"text","v":"Strategic Foundation & Operational Reality"}]},{"b":"p","spans":[{"t":"text","v":"The fatal flaw of the independent music business is cyclical amnesia. An artist launches a campaign, works furiously for three weeks, lands four station adds, and then disappears into the studio for eight months. When their next record is finished, they re-emerge to discover that programmers have changed jobs, email threads have gone cold, and they are forced to rebuild their momentum from absolute zero."}]},{"b":"p","spans":[{"t":"text","v":"Dominion operators operate an institutional CRM: the "},{"t":"b","v":"90-Day Ally Engine"},{"t":"text","v":"."}]},{"b":"p","spans":[{"t":"text","v":"A music director who has added your record once is 5x more likely to add your next record than a stranger—"},{"t":"i","v":"provided you maintain relational continuity between releases"},{"t":"text","v":". You do not let relationships decay. You maintain an active portfolio of station champions through a disciplined, low-friction quarterly maintenance cadence."}]},{"b":"h","level":3,"spans":[{"t":"text","v":"The 30/10/10 Relational Portfolio Model"}]},{"b":"p","spans":[{"t":"text","v":"Your active industry network is organized into three distinct operational tiers:"}]},{"b":"list","ordered":false,"items":[{"spans":[{"t":"b","v":"30 Lifetime Allies (The Base Portfolio):"},{"t":"text","v":" Every station programmer, specialty host, college DJ, or booking agent who has ever played your music, replied to an email, or attended a show. Logged in your master ledger with personal notes, format preferences, and station anniversaries."}]},{"spans":[{"t":"b","v":"10 Warm Champions (The Mid-Tier Pipeline):"},{"t":"text","v":" Programmers who have expressed genuine personal appreciation for your sound, conducted an in-studio interview, or added multiple tracks. Maintained with bi-monthly value drops."}]},{"spans":[{"t":"b","v":"10 Active Campaign Targets (The Firing Line):"},{"t":"text","v":" The 10 priority stations currently being worked for your active single or upcoming tour date."}]}]},{"b":"h","level":3,"spans":[{"t":"text","v":"The 4-Beat Quarterly Maintenance Loop"}]},{"b":"p","spans":[{"t":"text","v":"Every 90 days, execute this four-phase operational loop across your entire 30-member ally base:"}]},{"b":"list","ordered":true,"items":[{"spans":[{"t":"b","v":"Beat 1: The New Release Pre-Flight (Day 0):"},{"t":"text","v":" Dispatch your 90-word pitch to all 30 allies two weeks prior to general public release, framed as an exclusive advance preview for long-time supporters."}]},{"spans":[{"t":"b","v":"Beat 2: The Mid-Cycle Value Drop (Day 30):"},{"t":"text","v":" Deliver an unreleased acoustic cut, live soundboard recording, or custom station sweeper with zero commercial ask."}]},{"spans":[{"t":"b","v":"Beat 3: The Check-In & Service Inquiry (Day 60):"},{"t":"text","v":" Reach out with a brief, warm note: "},{"t":"i","v":"\"Hi Tom — hope the quarterly ratings book treated WMSE well. Any upcoming local programming specials we can support or amplify for you this fall?\""}]},{"spans":[{"t":"b","v":"Beat 4: The Quarterly Portfolio Audit & Re-Ranking (Day 90):"},{"t":"text","v":" Review the entire 30-member roster. Re-rank allies, retire inactive contacts to cold archives, and promote promising new station relationships into the active Top 30."}]}]}]', '[{"b":"p","spans":[{"t":"b","v":"WAR-ROOM DIRECTIVE — 5.4 Relationship Compounding — The 90-Day Ally Engine"}]},{"b":"p","spans":[{"t":"b","v":"THE COMPOUND VALUE OF A MUSIC DIRECTOR PROMOTION"},{"t":"text","v":" College and non-commercial music directors do not stay in college radio forever. The junior music director at a university station today will become the assistant program director at a major AAA station in five years, and a senior music supervisor at a television network in eight years."}]},{"b":"p","spans":[{"t":"text","v":"When you treat young student DJs with the same profound respect, punctuality, and gratitude that you show commercial PDs, you are planting seeds across the future institutional leadership of the global music industry."}]},{"b":"p","spans":[{"t":"text","v":"When they transition to major commercial stations or film studios, you will be one of the few artists whose emails they open on Day 1."}]}]', '["You do not let relationships decay."]', '["The mechanic: 30/10/10, re-ranked monthly.","The missing piece: the tracker''s asset/ask balance is the real KPI — 3 asks and 0 assets means the account is draining.","The operator move: monthly, scan for any ally with more asks than assets and send a no-ask value drop before the next campaign. The ledger is the moat''s maintenance log."]', '[{"kind":"note","blocks":[{"b":"p","spans":[{"t":"text","v":"Complete the structured table below as part of your lesson implementation. This worksheet directly replaces legacy spreadsheets with a publication-grade execution protocol."}]}]},{"kind":"table","title":"30/10/10 RELATIONSHIP COMPOUNDING LEDGER","headers":["Ally Name & Title","Station & Market","Portfolio Tier","Last Meaningful Touch Date","Next Scheduled Value Drop","Preferred Engagement Channel"],"rows":[["Sarah Jenkins (MD)","WLUW 88.7 (Chicago)","Warm Champion (10)","September 15","October 30 (Live Acoustic Cut)","Direct Office Phone / Email"],["Alex Rivera (MD)","WNUR 89.3 (Evanston)","Warm Champion (10)","September 20","October 30 (Live Acoustic Cut)","Station Studio Drop-In"],["Tom Crawford (PD)","WMSE 91.7 (Milwaukee)","Warm Champion (10)","October 4","November 15 (Exclusive Vinyl Mailer)","Direct Email / In-Person Gig"],["Marcus Vance (MD)","Radio K (Minneapolis)","Active Target (10)","October 8","October 22 (Touch 2 Asset)","Email Thread / Spinitron"],["Elena Rostova (MD)","WCSB 89.3 (Cleveland)","Lifetime Ally (30)","August 12","November 1 (Pre-Release Advance)","Direct Email"]]}]', '["Post your completed 30/10/10 Relationship Ledger (redacting personal phone numbers).","Share an example of a relationship that compounded over multiple releases into unexpected commercial success.","What unreleased value asset have you chosen for your Day 30 Mid-Cycle Drop?","Confirm that your recurring 90-day calendar audit blocks are officially scheduled."]', '{"kind":"field-exercise","prompt":"Complete every drill below with real, verifiable answers, then confirm the pass standard.","items":[{"id":"d1","label":"The 30-Member Ally Portfolio Assembly","description":"The 30-Member Ally Portfolio Assembly . Aggregate every programmer, DJ, and tastemaker who has ever supported your music. Populate the 30/10/10 Relationship Ledger below.","minutes":45,"type":"response","passStandard":null},{"id":"d2","label":"The Quarterly Calendar Rhythm Lockdown","description":"The Quarterly Calendar Rhythm Lockdown . Schedule four recurring quarterly review dates in your annual calendar: March 31, June 30, September 30, December 31. Label them: ''Dominion 90-Day Ally Engine Audit.''","minutes":15,"type":"response","passStandard":null},{"id":"d3","label":"The Uncontaminated Mid-Cycle Value Drop Staging","description":"The Uncontaminated Mid-Cycle Value Drop Staging . Prepare two unreleased audio assets (an acoustic demo or live concert board mix) to deploy as your Day 30 value drops.","minutes":20,"type":"response","passStandard":null},{"id":"d4","label":"The Gatekeeper Life Event Log","description":"The Gatekeeper Life Event Log . Document personal details for your Top 10 Warm Champions: station anniversaries, favorite local sports teams, or preferred coffee/vinyl preferences.","minutes":15,"type":"response","passStandard":null}],"worksheets":[{"kind":"table","title":"30/10/10 RELATIONSHIP COMPOUNDING LEDGER","headers":["Ally Name & Title","Station & Market","Portfolio Tier","Last Meaningful Touch Date","Next Scheduled Value Drop","Preferred Engagement Channel"],"rows":[["Sarah Jenkins (MD)","WLUW 88.7 (Chicago)","Warm Champion (10)","September 15","October 30 (Live Acoustic Cut)","Direct Office Phone / Email"],["Alex Rivera (MD)","WNUR 89.3 (Evanston)","Warm Champion (10)","September 20","October 30 (Live Acoustic Cut)","Station Studio Drop-In"],["Tom Crawford (PD)","WMSE 91.7 (Milwaukee)","Warm Champion (10)","October 4","November 15 (Exclusive Vinyl Mailer)","Direct Email / In-Person Gig"],["Marcus Vance (MD)","Radio K (Minneapolis)","Active Target (10)","October 8","October 22 (Touch 2 Asset)","Email Thread / Spinitron"],["Elena Rostova (MD)","WCSB 89.3 (Cleveland)","Lifetime Ally (30)","August 12","November 1 (Pre-Release Advance)","Direct Email"]]}],"confirmations":[{"id":"community","text":"One community drill answered (optional but strengthens calibration).","required":false}]}', '{"policy":"all-responses-min-words","minWords":40,"requireAllDrills":true,"requireWorksheetCells":0,"note":""}', '[{"to":"/frequency-dominion/app/stations","label":"Station records & touch log"}]', 'courses/frequency-dominion/frequency-dominion-course.zip', 1, strftime('%Y-%m-%dT%H:%M:%SZ','now'), strftime('%Y-%m-%dT%H:%M:%SZ','now'))
       ON CONFLICT(id) DO UPDATE SET module_id=excluded.module_id, code=excluded.code, title=excluded.title, minutes=excluded.minutes, exercise_minutes=excluded.exercise_minutes, position=excluded.position, truth=excluded.truth, masterclass_json=excluded.masterclass_json, field_protocol_json=excluded.field_protocol_json, warnings_json=excluded.warnings_json, decoder_json=excluded.decoder_json, worksheets_json=excluded.worksheets_json, community_json=excluded.community_json, exercise_json=excluded.exercise_json, pass_json=excluded.pass_json, tool_links_json=excluded.tool_links_json, version=lessons.version+1, updated_at=strftime('%Y-%m-%dT%H:%M:%SZ','now');
INSERT INTO lessons (id, module_id, code, title, minutes, exercise_minutes, position, published, truth, masterclass_json, field_protocol_json, warnings_json, decoder_json, worksheets_json, community_json, exercise_json, pass_json, tool_links_json, print_asset, version, created_at, updated_at)
       VALUES ('m6l1', 'm6', '6.1', 'Proof Compounding Systems — Turn Every Spin Into a Weapon', 8, 85, 0, 1, 'Every broadcast spin is a verifiable intellectual property receipt; every receipt is ammunition; ammunition fuels the next release. The proof farm turns ephemeral airplay into permanent equity.', '[{"b":"h","level":3,"spans":[{"t":"text","v":"Strategic Foundation & Operational Reality"}]},{"b":"p","spans":[{"t":"text","v":"Amateur artists view a radio spin as an ephemeral event that dissipates into the atmosphere the second the song ends. They hear their track on the air, experience a fleeting burst of dopamine, and resume their daily routine."}]},{"b":"p","spans":[{"t":"text","v":"Dominion operators treat every broadcast spin as a "},{"t":"b","v":"high-yield intellectual property receipt"},{"t":"text","v":"."}]},{"b":"p","spans":[{"t":"text","v":"A single verified radio spin on a respected station represents an objective, third-party validation event that can be atomized, re-packaged, and deployed across five distinct commercial channels. If you generate 20 spins in a campaign and fail to capture and compound them, you are throwing away 80% of your career equity."}]},{"b":"p","spans":[{"t":"text","v":"The "},{"t":"b","v":"Proof Compounding System"},{"t":"text","v":" is an industrial assembly line that mines every on-air play and transforms it into permanent marketing ammunition."}]},{"b":"h","level":3,"spans":[{"t":"text","v":"The Five-Stage Proof Pipeline (Capture to Recycle)"}]},{"b":"list","ordered":true,"items":[{"spans":[{"t":"b","v":"Stage 1: Systematic Capture (Day of Spin):"},{"t":"text","v":" Real-time monitoring via Spinitron, Mediabase, station online logs, and listener alerts. The instant a spin occurs, capture timestamped screenshot evidence showing Station Callsign, Date, Exact Time, Show Title, and Artist/Track name. Log in central Proof Ledger."}]},{"spans":[{"t":"b","v":"Stage 2: Asset Conversion (Within 24 Hours):"},{"t":"text","v":" Transform the raw spin receipt into four distinct digital assets:"}]},{"spans":[{"t":"i","v":"Asset A (The Social Proof Card):"},{"t":"text","v":" Clean, high-contrast visual graphic displaying the station logo, spin quote, and airplay timestamp for Instagram Stories and LinkedIn."}]},{"spans":[{"t":"i","v":"Asset B (The Audio Aircheck Snippet):"},{"t":"text","v":" 15-second audio clip of the radio DJ announcing your track over the station intro bed."}]},{"spans":[{"t":"i","v":"Asset C (The One-Line Pitch Weapon):"},{"t":"text","v":" Formatted text snippet: "},{"t":"i","v":"\"Added into evening rotation on [Station Callsign] alongside [Charting Core Artist].\""}]},{"spans":[{"t":"i","v":"Asset D (The EPK Receipt Badge):"},{"t":"text","v":" Vector station callsign badge added to the Proof Wall of your Command Deck."}]},{"spans":[{"t":"b","v":"Stage 3: Multi-Channel Deployment (Weekly Rhythm):"},{"t":"text","v":" Deploy the converted assets across your live tour pitches, booking agency communications, sync licensing submissions, and upcoming radio touch points."}]},{"spans":[{"t":"b","v":"Stage 4: Velocity Measurement (Monthly):"},{"t":"text","v":" Track which specific proof receipts trigger the highest response rates from booking agents and music supervisors."}]},{"spans":[{"t":"b","v":"Stage 5: Evergreen Recycling (Quarterly):"},{"t":"text","v":" Bundle historical spin logs into comprehensive \"Broadcast Resume\" summaries to pitch higher-tier festival stages and national syndicated networks."}]}]}]', '[{"b":"p","spans":[{"t":"b","v":"WAR-ROOM DIRECTIVE — 6.1 Proof Compounding Systems — Turn Every Spin Into a Weapon"}]},{"b":"p","spans":[{"t":"b","v":"THE FRIDAY PROOF DROP: DOMINATING THE AIR OF VISIBILITY"},{"t":"text","v":" Every Friday afternoon, while competing artists post generic memes or complain about the music industry on social media, execute the "},{"t":"b","v":"Friday Proof Drop"},{"t":"text","v":":"}]},{"b":"list","ordered":false,"items":[{"spans":[{"t":"text","v":"Post a single, elegant graphic: "},{"t":"i","v":"\"This Week on the Airwaves: Spins on @WLUW, @WNUR, and @WMSE. Thank you to the programmers keeping independent music alive.\""}]},{"spans":[{"t":"text","v":"Broadcast this update to your email list, your booking agents, and your active promoter network."}]}]},{"b":"p","spans":[{"t":"text","v":"The Friday Proof Drop creates an undeniable perception of continuous, compounding commercial momentum. Industry gatekeepers observe you as an artist whose trajectory is moving upward every single week."}]}]', '[]', '["The mechanic: each spin becomes four assets.","The missing piece: proof is perishable — 7-day-old reads as \"now\", 90-day-old reads as \"history.\"","The operator move: refresh the EPK''s receipts weekly and archive the old ones. Current proof runs campaigns; history runs press kits."]', '[{"kind":"note","blocks":[{"b":"p","spans":[{"t":"text","v":"Complete the structured table below as part of your lesson implementation. This worksheet directly replaces legacy spreadsheets with a publication-grade execution protocol."}]}]},{"kind":"table","title":"PROOF COMPOUNDING SYSTEM LOG & ASSET MINE","headers":["Station Callsign","Date & Time of Spin","Show Name & DJ","Raw Proof Source","Derived Asset Created","Deployment Target"],"rows":[["WLUW 88.7 FM","Oct 14 @ 4:18 PM","Afternoon Drive (Sarah J)","Spinitron Screenshot","Instagram Story + Pitch Line","Pitched to WMSE Milwaukee"],["WNUR 89.3 FM","Oct 16 @ 9:42 PM","Rock Show (Alex R)","Station Stream Audio Capture","15s Audio DJ Intro Snippet","Added to EPK Audio Player"],["WMSE 91.7 FM","Oct 18 @ 2:15 PM","Midday Focus (Tom C)","Official Station Twitter Post","Quote Card Graphic","Included in Touch 3 for WXPN"],["Radio K 100.7","Oct 22 @ 8:05 PM","Real College Radio","Spinitron Airplay Log","One-Line Pitch Bullet","Deployed in Booking Pitch"],["KUTX 98.9 FM","Oct 25 @ 11:30 AM","Austin Music Spotlight","Station Playlist Archive","Station Logo Badge","Mounted on Command Deck EPK"]]}]', '["Post your designed Social Proof Card displaying a recent spin, review, or gig confirmation.","Share the exact text of your updated One-Line Pitch Weapon incorporating your latest airplay receipt.","Discuss how you captured and archived your single most valuable audio aircheck snippet.","Confirm that your Proof Farm capture alerts are fully operational across all target stations."]', '{"kind":"field-exercise","prompt":"Complete every drill below with real, verifiable answers, then confirm the pass standard.","items":[{"id":"d1","label":"The Spinitron & Alert Network Setup","description":"The Spinitron & Alert Network Setup . Establish active keyword alerts on Google, Spinitron, and Twitter/X for your artist name, track title, and catalog ISRC codes.","minutes":20,"type":"response","passStandard":null},{"id":"d2","label":"The Social Proof Card Template Creation","description":"The Social Proof Card Template Creation . Design a standardized, high-contrast digital proof card template (1080x1920 story and 1080x1080 post) ready to ingest station airplay screenshots in under 3 minutes.","minutes":30,"type":"response","passStandard":null},{"id":"d3","label":"The Audio Aircheck Capture Protocol","description":"The Audio Aircheck Capture Protocol . Practice recording an on-air stream capture of a live radio broadcast using audio capture software (such as Audio Hijack or Audacity).","minutes":20,"type":"response","passStandard":null},{"id":"d4","label":"The Master Proof Farm Log Initialization","description":"The Master Proof Farm Log Initialization . Populate the Proof Compounding System Log below with all confirmed past airplay receipts.","minutes":15,"type":"response","passStandard":null}],"worksheets":[{"kind":"table","title":"PROOF COMPOUNDING SYSTEM LOG & ASSET MINE","headers":["Station Callsign","Date & Time of Spin","Show Name & DJ","Raw Proof Source","Derived Asset Created","Deployment Target"],"rows":[["WLUW 88.7 FM","Oct 14 @ 4:18 PM","Afternoon Drive (Sarah J)","Spinitron Screenshot","Instagram Story + Pitch Line","Pitched to WMSE Milwaukee"],["WNUR 89.3 FM","Oct 16 @ 9:42 PM","Rock Show (Alex R)","Station Stream Audio Capture","15s Audio DJ Intro Snippet","Added to EPK Audio Player"],["WMSE 91.7 FM","Oct 18 @ 2:15 PM","Midday Focus (Tom C)","Official Station Twitter Post","Quote Card Graphic","Included in Touch 3 for WXPN"],["Radio K 100.7","Oct 22 @ 8:05 PM","Real College Radio","Spinitron Airplay Log","One-Line Pitch Bullet","Deployed in Booking Pitch"],["KUTX 98.9 FM","Oct 25 @ 11:30 AM","Austin Music Spotlight","Station Playlist Archive","Station Logo Badge","Mounted on Command Deck EPK"]]}],"confirmations":[{"id":"community","text":"One community drill answered (optional but strengthens calibration).","required":false}]}', '{"policy":"all-responses-min-words","minWords":40,"requireAllDrills":true,"requireWorksheetCells":0,"note":""}', '[{"to":"/frequency-dominion/app/analytics","label":"Campaign Analytics"},{"to":"/frequency-dominion/app/vault","label":"90-day audit engine"}]', 'courses/frequency-dominion/frequency-dominion-course.zip', 1, strftime('%Y-%m-%dT%H:%M:%SZ','now'), strftime('%Y-%m-%dT%H:%M:%SZ','now'))
       ON CONFLICT(id) DO UPDATE SET module_id=excluded.module_id, code=excluded.code, title=excluded.title, minutes=excluded.minutes, exercise_minutes=excluded.exercise_minutes, position=excluded.position, truth=excluded.truth, masterclass_json=excluded.masterclass_json, field_protocol_json=excluded.field_protocol_json, warnings_json=excluded.warnings_json, decoder_json=excluded.decoder_json, worksheets_json=excluded.worksheets_json, community_json=excluded.community_json, exercise_json=excluded.exercise_json, pass_json=excluded.pass_json, tool_links_json=excluded.tool_links_json, version=lessons.version+1, updated_at=strftime('%Y-%m-%dT%H:%M:%SZ','now');
INSERT INTO lessons (id, module_id, code, title, minutes, exercise_minutes, position, published, truth, masterclass_json, field_protocol_json, warnings_json, decoder_json, worksheets_json, community_json, exercise_json, pass_json, tool_links_json, print_asset, version, created_at, updated_at)
       VALUES ('m6l2', 'm6', '6.2', 'Airplay-to-Income — Convert Frequency Into Money', 8, 95, 1, 1, 'Airplay is not vanity applause — it is an intellectual property validation receipt that unlocks six distinct revenue lanes. If you are not monetizing frequency, you are leaking wealth.', '[{"b":"h","level":3,"spans":[{"t":"text","v":"Strategic Foundation & Operational Reality"}]},{"b":"p","spans":[{"t":"text","v":"There is a pervasive myth in the independent music sector that \"radio airplay doesn''t pay.\" Artists point to modest terrestrial PRO royalty checks for indie spins and claim that pursuing radio is commercially obsolete compared to viral social algorithms."}]},{"b":"p","spans":[{"t":"text","v":"This reflects a complete misunderstanding of music monetization."}]},{"b":"p","spans":[{"t":"text","v":"A radio add is not merely a royalty event; it is an "},{"t":"b","v":"Authoritative Verification Badge"},{"t":"text","v":". In the commercial music marketplace, broadcast airplay is the engine that lowers friction across every other revenue-generating transaction in your enterprise."}]},{"b":"p","spans":[{"t":"text","v":"When you hold verified radio rotation in a market, you can harvest "},{"t":"b","v":"Six Distinct Commercial Revenue Lanes"},{"t":"text","v":"."}]},{"b":"h","level":3,"spans":[{"t":"text","v":"The Six Revenue Lanes of Frequency Dominion"}]},{"b":"list","ordered":true,"items":[{"spans":[{"t":"b","v":"Lane 1: Live Concert Ticket Conversion (The Highest Yield):"},{"t":"text","v":" Airplay transforms cold tour markets into warm revenue centers. When a local station airs your song 15 times over three weeks, you are not a stranger; you are a recognized regional act. Ticket sales increase 2x to 5x, allowing you to charge $20–$30 per head rather than $10 at the door."}]},{"spans":[{"t":"b","v":"Lane 2: High-Value Sync & Commercial Licensing:"},{"t":"text","v":" Music supervisors for television networks, film studios, video games, and advertising agencies receive 1,000 unvetted song pitches daily. When your pitch notes: "},{"t":"i","v":"\"Currently in rotation on KEXP and WXPN, broadcast cleared with instant 200% one-stop sync rights,\""},{"t":"text","v":" your track moves from the bottom spam pile to priority consideration. Broadcast airplay proves the record has commercial audio fidelity."}]},{"spans":[{"t":"b","v":"Lane 3: Streaming & Algorithm Velocity Spikes:"},{"t":"text","v":" Listeners in cars and workplaces who hear your record on terrestrial radio use Shazam or search your title on Apple Music and Spotify. This localized search velocity signals high organic listener intent to DSP recommendation engines, triggering algorithmic placements on Release Radar, Discover Weekly, and Radio queues."}]},{"spans":[{"t":"b","v":"Lane 4: Regional Brand Sponsorships & Underwriting:"},{"t":"text","v":" Local businesses, craft breweries, instrument brands, and apparel companies sponsor live tours and releases when an artist can demonstrate documented local media reach. Citing station partnerships allows you to secure $1,500 to $5,000 corporate tour tour support checks."}]},{"spans":[{"t":"b","v":"Lane 5: On-Site Live Merchandise Conversion:"},{"t":"text","v":" A concert attendee primed by weeks of radio excitement converts at the merchandise table at 40% higher rates, purchasing physical vinyl, hoodies, and posters."}]},{"spans":[{"t":"b","v":"Lane 6: Performance Royalties & SoundExchange Collections:"},{"t":"text","v":" Systematic registration of every live spin, syndicated broadcast, and digital simulcast generates recurring quarterly royalty distributions from ASCAP, BMI, SESAC, and SoundExchange."}]}]}]', '[{"b":"p","spans":[{"t":"b","v":"WAR-ROOM DIRECTIVE — 6.2 Airplay-to-Income — Convert Frequency Into Money"}]},{"b":"p","spans":[{"t":"b","v":"HOW TO NEGOTIATE HIGHER PERFORMANCE GUARANTEES USING RADIO PROOF"},{"t":"text","v":" When booking regional club dates, booking talent buyers routinely offer independent artists low-stakes \"door deals\" (e.g., 70% of door after $200 venue expenses) with zero financial safety net."}]},{"b":"p","spans":[{"t":"b","v":"THE DOMINION LEVERAGE MOVE:"},{"t":"text","v":" When approaching the venue talent buyer 60 days in advance, cite your radio footprint in their municipality:"}]},{"b":"list","ordered":false,"items":[{"spans":[{"t":"i","v":"\"We are currently in active rotation on [Local Station Callsign] with upcoming specialty support on [Show Name]. The station is running listener ticket giveaways the week of show. Because we have verified broadcast promotion driving attendance in your market, we require a $750 guaranteed baseline against an 80/20 split.\""},{"t":"text","v":" This changes you from an unproven financial liability into a co-promoted entertainment event. <!-- WARROOM:END -->"}]}]}]', '[]', '["The mechanic: airplay is verifiable demand.","The missing piece: the chart (NACC/RMR) is the currency — supervisors, brands, and bookers all check it.","The operator move: build the one-page placement package (chart proof + 90-sec cut + stems + contact) before you need it. It converts twice: supervisor and sponsor."]', '[{"kind":"note","blocks":[{"b":"p","spans":[{"t":"text","v":"Complete the structured table below as part of your lesson implementation. This worksheet directly replaces legacy spreadsheets with a publication-grade execution protocol."}]}]},{"kind":"table","title":"AIRPLAY-TO-INCOME ATTRIBUTION LEDGER","headers":["Revenue Lane","Associated Radio Market","Triggering Proof Receipt","Gross Revenue Realized","Conversion Timeline","Growth Action Plan"],"rows":[["Lane 1: Live Ticket Sales","Chicago (Metro Showcase)","WLUW / WNUR Rotation","$4,850 gate & merch","30 days post-airplay","Increase venue cap from 250 to 500"],["Lane 2: Sync Licensing","National Film Placement","WXPN Specialty Feature","$6,500 master/sync fee","60 days post-airplay","Pitch music supervisors with radio quotes"],["Lane 3: DSP Algorithmic Lift","Regional Midwest","12 Regional Station Adds","$1,420 streaming royalties","45 days post-airplay","Deploy audio weapon in TikTok ad testing"],["Lane 4: Tour Sponsorship","Milwaukee / Madison","WMSE / WSUM Co-Sign","$2,000 brewery partner","14 days pre-tour","Pitch hometown sponsors on station ID ads"],["Lane 5: Broadcast Royalties","National Terrestrial","Quarterly Station Airplay","$1,850 PRO distribution","90 days post-quarter","Register clean instrumental cues"]]}]', '["Post your completed Airplay-to-Income Ledger detailing your monetization targets across the Six Lanes.","Share a recent negotiation win where citing radio airplay unlocked a venue guarantee, sync lead, or sponsor deal.","Verify that your tracks are 100% reconciled in SoundExchange and your PRO account with accurate ISRC codes.","Identify which of the Six Revenue Lanes represents your immediate priority for your upcoming release cycle."]', '{"kind":"field-exercise","prompt":"Complete every drill below with real, verifiable answers, then confirm the pass standard.","items":[{"id":"d1","label":"The Six-Lane Revenue Allocation Audit","description":"The Six-Lane Revenue Allocation Audit . Audit your previous 12 months of income across all six lanes using the Airplay-to-Income Ledger below. Identify your single largest revenue leak.","minutes":30,"type":"response","passStandard":null},{"id":"d2","label":"The Airplay-to-Ticket Tour Bridge Setup","description":"The Airplay-to-Ticket Tour Bridge Setup . For your next live date, craft a targeted email pitch to the local venue booking manager citing your confirmed radio adds in that market to negotiate a higher financial guarantee or door split.","minutes":25,"type":"response","passStandard":null},{"id":"d3","label":"The One-Stop Sync Clearance Metadata Package","description":"The One-Stop Sync Clearance Metadata Package . Prepare a dedicated Sync Pitch Brief for your radio single explicitly documenting 100% master and publishing ownership (''One-Stop'') and broadcast clearance credentials.","minutes":20,"type":"response","passStandard":null},{"id":"d4","label":"PRO & SoundExchange Catalog Reconciliation","description":"PRO & SoundExchange Catalog Reconciliation . Verify that your radio single and all alternate versions (clean edit, instrumental) are registered with exact ISRC codes in your ASCAP/BMI/SESAC catalog and SoundExchange portal.","minutes":20,"type":"response","passStandard":null}],"worksheets":[{"kind":"table","title":"AIRPLAY-TO-INCOME ATTRIBUTION LEDGER","headers":["Revenue Lane","Associated Radio Market","Triggering Proof Receipt","Gross Revenue Realized","Conversion Timeline","Growth Action Plan"],"rows":[["Lane 1: Live Ticket Sales","Chicago (Metro Showcase)","WLUW / WNUR Rotation","$4,850 gate & merch","30 days post-airplay","Increase venue cap from 250 to 500"],["Lane 2: Sync Licensing","National Film Placement","WXPN Specialty Feature","$6,500 master/sync fee","60 days post-airplay","Pitch music supervisors with radio quotes"],["Lane 3: DSP Algorithmic Lift","Regional Midwest","12 Regional Station Adds","$1,420 streaming royalties","45 days post-airplay","Deploy audio weapon in TikTok ad testing"],["Lane 4: Tour Sponsorship","Milwaukee / Madison","WMSE / WSUM Co-Sign","$2,000 brewery partner","14 days pre-tour","Pitch hometown sponsors on station ID ads"],["Lane 5: Broadcast Royalties","National Terrestrial","Quarterly Station Airplay","$1,850 PRO distribution","90 days post-quarter","Register clean instrumental cues"]]}],"confirmations":[{"id":"community","text":"One community drill answered (optional but strengthens calibration).","required":false}]}', '{"policy":"all-responses-min-words","minWords":40,"requireAllDrills":true,"requireWorksheetCells":0,"note":""}', '[{"to":"/frequency-dominion/app/analytics","label":"Campaign Analytics"},{"to":"/frequency-dominion/app/vault","label":"90-day audit engine"}]', 'courses/frequency-dominion/frequency-dominion-course.zip', 1, strftime('%Y-%m-%dT%H:%M:%SZ','now'), strftime('%Y-%m-%dT%H:%M:%SZ','now'))
       ON CONFLICT(id) DO UPDATE SET module_id=excluded.module_id, code=excluded.code, title=excluded.title, minutes=excluded.minutes, exercise_minutes=excluded.exercise_minutes, position=excluded.position, truth=excluded.truth, masterclass_json=excluded.masterclass_json, field_protocol_json=excluded.field_protocol_json, warnings_json=excluded.warnings_json, decoder_json=excluded.decoder_json, worksheets_json=excluded.worksheets_json, community_json=excluded.community_json, exercise_json=excluded.exercise_json, pass_json=excluded.pass_json, tool_links_json=excluded.tool_links_json, version=lessons.version+1, updated_at=strftime('%Y-%m-%dT%H:%M:%SZ','now');
INSERT INTO lessons (id, module_id, code, title, minutes, exercise_minutes, position, published, truth, masterclass_json, field_protocol_json, warnings_json, decoder_json, worksheets_json, community_json, exercise_json, pass_json, tool_links_json, print_asset, version, created_at, updated_at)
       VALUES ('m6l3', 'm6', '6.3', 'The Release Calendar That Dominates Quarters', 8, 80, 2, 1, 'A release is not an isolated event — it is a 12-week military operation. The artists who own radio run an annual calendar with three armed campaigns a year, backwards-engineered from impact dates.', '[{"b":"h","level":3,"spans":[{"t":"text","v":"Strategic Foundation & Operational Reality"}]},{"b":"p","spans":[{"t":"text","v":"The most destructive behavior in the independent music ecosystem is the sporadic, impulsive release cycle. An artist records a single, finishes the master on a Wednesday, uploads it to a digital distributor on Friday, posts on social media on Monday, and by week two has exhausted their promotional energy. They spend the next four months in creative hibernation, wondering why their career lacks commercial continuity."}]},{"b":"p","spans":[{"t":"text","v":"Dominion operators treat the calendar as an "},{"t":"b","v":"Enterprise Production System"},{"t":"text","v":"."}]},{"b":"p","spans":[{"t":"text","v":"You do not \"drop singles.\" You execute "},{"t":"b","v":"Quarterly Operational Campaigns"},{"t":"text","v":". A sustainable, highly profitable independent music enterprise operates on a strict cadence of "},{"t":"b","v":"three major campaigns per year"},{"t":"text","v":", with each campaign structured as a 12-week continuous execution timeline backwards-engineered from an official "},{"t":"b","v":"Radio Impact Date"},{"t":"text","v":"."}]},{"b":"h","level":3,"spans":[{"t":"text","v":"Why Three Releases Per Year Beats Monthly Chaos"}]},{"b":"p","spans":[{"t":"text","v":"Digital distribution \"gurus\" advocate releasing a new single every 30 days to game Spotify recommendation algorithms. For a serious broadcast campaign, this strategy is catastrophic:"}]},{"b":"list","ordered":false,"items":[{"spans":[{"t":"text","v":"Radio programming departments operate on multi-week evaluation cycles. It takes 14 to 21 days just for a programmer to listen, evaluate, and assign a track to an add meeting."}]},{"spans":[{"t":"text","v":"If you release a new track every 4 weeks, you abandon your first single just as radio rotation is beginning to build."}]},{"spans":[{"t":"text","v":"You burn out your station allies with constant, frantic, low-quality submissions."}]}]},{"b":"p","spans":[{"t":"text","v":"Three disciplined, fully armed 12-week campaigns per year give each single sufficient runway to achieve full regional saturation, rotation upgrades, tour sync, and revenue harvest."}]},{"b":"h","level":3,"spans":[{"t":"text","v":"The 12-Week Master Operational Timeline"}]},{"b":"list","ordered":false,"items":[{"spans":[{"t":"b","v":"Weeks 1 – 2 (The Proof & Asset Build):"},{"t":"text","v":" Final master delivered (-14 LUFS, -1.0 dBTP), FCC clean edit bounced, 90-second audio weapon and 30-second sweeper created, ID3 metadata stamped, proof stack refreshed."}]},{"spans":[{"t":"b","v":"Weeks 3 – 4 (Target Architecture Lockdown):"},{"t":"text","v":" Hometown Heat Map audited, 60 candidates scored via 100-Point Format Scorecard, 20-Station War Room Cockpit finalized and verified."}]},{"spans":[{"t":"b","v":"Weeks 5 – 6 (Weapon Staging & Gate Clearance):"},{"t":"text","v":" One-Page Command Deck EPK updated, 20 customized 3-layer subject lines pre-drafted, all 7 Load Sequence gates verified green."}]},{"spans":[{"t":"b","v":"Weeks 7 – 8 (The Pre-Roll Launch):"},{"t":"text","v":" Tour dates confirmed and locked in target station markets, venue interview windows scheduled, station ticket giveaways structured."}]},{"spans":[{"t":"b","v":"Week 9 (Wave 1 Dispatch & Impact Week):"},{"t":"text","v":" Wave 1 dispatches Tuesday 9:30 AM local time. Four-hour monitoring window active. Real-time Spinitron tracking initiated."}]},{"spans":[{"t":"b","v":"Week 10 (Wave 2 & Touch 2 Escalation):"},{"t":"text","v":" Wave 2 dispatches Thursday 9:30 AM local time. Wave 1 receives Touch 2 Asset Drop (30-second hook cut + tour dates)."}]},{"spans":[{"t":"b","v":"Week 11 (Touch 3 & Cascade Loops):"},{"t":"text","v":" Touch 3 Dignified Exit dispatched to unresponsive targets. First verified adds leveraged into Cascade Expansion loops across sibling stations."}]},{"spans":[{"t":"b","v":"Week 12 (The Harvest & Revenue Conversion):"},{"t":"text","v":" Thank-You Economy protocol deployed, physical station postcards mailed, tour dates executed, revenue logged in Airplay-to-Income Ledger."}]}]}]', '[{"b":"p","spans":[{"t":"b","v":"WAR-ROOM DIRECTIVE — 6.3 The Release Calendar That Dominates Quarters"}]},{"b":"p","spans":[{"t":"b","v":"THE DANGER OF THE DECEMBER RATINGS FREEZE"},{"t":"text","v":" Never launch an independent radio campaign between December 1st and January 5th."}]},{"b":"list","ordered":false,"items":[{"spans":[{"t":"text","v":"During December, commercial and public radio stations enter the \"Holiday Freeze.\""}]},{"spans":[{"t":"text","v":"Many stations switch to 24/7 holiday music or freeze all playlist changes to protect their fourth-quarter Arbitron ratings books."}]},{"spans":[{"t":"text","v":"Programming staffs take extended holiday vacations, and music meetings are suspended."}]}]},{"b":"p","spans":[{"t":"b","v":"OPTIMAL ANNUAL LAUNCH WINDOWS:"}]},{"b":"list","ordered":true,"items":[{"spans":[{"t":"b","v":"Window A (Late Winter / Spring):"},{"t":"text","v":" January 15 – April 15 (Fresh budgets, new music appetites, SXSW season)."}]},{"spans":[{"t":"b","v":"Window B (Early Summer):"},{"t":"text","v":" May 1 – July 15 (Upbeat programming, summer festival and tour season)."}]},{"spans":[{"t":"b","v":"Window C (Fall / Back-to-Campus):"},{"t":"text","v":" September 1 – November 10 (College radio returns, major fall tour runs). <!-- WARROOM:END -->"}]}]}]', '["You do not \"drop singles.\" You execute Quarterly Operational Campaigns."]', '["The mechanic: 12 weeks, 3 releases.","The missing piece: timing is market-attention windows — Q1 post-holiday open, Q2 spring/summer booking, Q3 fall breakout, Q4 closed (proof + audit).","The operator move: never release into Q4 as an unknown. Use November–December for the annual audit and the next year''s plan — the calendar''s closed window is the empire''s strategy season."]', '[{"kind":"note","blocks":[{"b":"p","spans":[{"t":"text","v":"Complete the structured table below as part of your lesson implementation. This worksheet directly replaces legacy spreadsheets with a publication-grade execution protocol."}]}]},{"kind":"table","title":"12-WEEK QUARTERLY CAMPAIGN MASTER CALENDAR","headers":["Campaign Week","Operational Phase","Core Mission Objectives","Deliverables Produced","Gatekeeper Milestone"],"rows":[["Weeks 1-2 (T-8)","Proof & Asset Build","Finalize audio masters & metadata","Clean WAV, 90s Weapon, Proof Stack","Audio package verified 100%"],["Weeks 3-4 (T-6)","Target Architecture","Score stations & populate War Room","Format scorecards, 20 locked targets","Gatekeepers verified"],["Weeks 5-6 (T-4)","Weapon Staging","Update Command Deck EPK & drafts","One-Page URL live, 7 gates green","All Load Sequence gates passed"],["Weeks 7-8 (T-2)","Tour Pre-Roll Sync","Coordinate venue dates with radio","Tour Pre-Roll calendar locked","Interview windows proposed"],["Week 9 (T-0)","Launch & Wave 1","Dispatch Wave 1 (Top 10 targets)","First sends logged @ 9:30 AM","Wave 1 opens & replies tracked"],["Week 10 (T+1)","Wave 2 & Touch 2","Dispatch Wave 2 + Touch 2 value drop","30s hook cut delivered to Wave 1","Dialogue initiated across targets"],["Week 11 (T+2)","Touch 3 & Cascade","Final touch exit + expansion loops","Cascade pitches to sibling stations","First adds confirmed & logged"],["Week 12 (T+3)","Harvest & Loop","Deploy thank-yous, gigs, revenue","Postcards mailed, revenue logged","Allies transitioned to 30/10/10"]]}]', '["Post your 12-Month Annual Campaign Calendar displaying your three designated 12-week operational windows.","Share your backwards-engineered Radio Impact Date for your next single release.","Discuss how shifting from a monthly release mindset to a quarterly campaign model reduces operational anxiety.","Confirm that your planned release dates avoid the December Holiday Freeze."]', '{"kind":"field-exercise","prompt":"Complete every drill below with real, verifiable answers, then confirm the pass standard.","items":[{"id":"d1","label":"The Annual 3-Campaign Architecture","description":"The Annual 3-Campaign Architecture . Lay out the next 12 months in your calendar. Designate three distinct 12-week campaign windows. Populate the Annual Release Calendar below.","minutes":30,"type":"response","passStandard":null},{"id":"d2","label":"The Backwards-Engineered Impact Date","description":"The Backwards-Engineered Impact Date . For your upcoming release, establish your formal Radio Impact Date (a Tuesday morning). Backwards-engineer exact calendar deadlines for Weeks 1 through 12.","minutes":20,"type":"response","passStandard":null},{"id":"d3","label":"The Buffer & Code Freeze Lock","description":"The Buffer & Code Freeze Lock . Establish a mandatory 14-day ''Code Freeze'' window between asset delivery and first outbound sends to ensure zero operational scrambling.","minutes":15,"type":"response","passStandard":null},{"id":"d4","label":"The Capacity Audit","description":"The Capacity Audit . Verify that your recording, production, and touring commitments align with your three planned campaign windows with zero scheduling conflicts.","minutes":15,"type":"response","passStandard":null}],"worksheets":[{"kind":"table","title":"12-WEEK QUARTERLY CAMPAIGN MASTER CALENDAR","headers":["Campaign Week","Operational Phase","Core Mission Objectives","Deliverables Produced","Gatekeeper Milestone"],"rows":[["Weeks 1-2 (T-8)","Proof & Asset Build","Finalize audio masters & metadata","Clean WAV, 90s Weapon, Proof Stack","Audio package verified 100%"],["Weeks 3-4 (T-6)","Target Architecture","Score stations & populate War Room","Format scorecards, 20 locked targets","Gatekeepers verified"],["Weeks 5-6 (T-4)","Weapon Staging","Update Command Deck EPK & drafts","One-Page URL live, 7 gates green","All Load Sequence gates passed"],["Weeks 7-8 (T-2)","Tour Pre-Roll Sync","Coordinate venue dates with radio","Tour Pre-Roll calendar locked","Interview windows proposed"],["Week 9 (T-0)","Launch & Wave 1","Dispatch Wave 1 (Top 10 targets)","First sends logged @ 9:30 AM","Wave 1 opens & replies tracked"],["Week 10 (T+1)","Wave 2 & Touch 2","Dispatch Wave 2 + Touch 2 value drop","30s hook cut delivered to Wave 1","Dialogue initiated across targets"],["Week 11 (T+2)","Touch 3 & Cascade","Final touch exit + expansion loops","Cascade pitches to sibling stations","First adds confirmed & logged"],["Week 12 (T+3)","Harvest & Loop","Deploy thank-yous, gigs, revenue","Postcards mailed, revenue logged","Allies transitioned to 30/10/10"]]}],"confirmations":[{"id":"community","text":"One community drill answered (optional but strengthens calibration).","required":false}]}', '{"policy":"all-responses-min-words","minWords":40,"requireAllDrills":true,"requireWorksheetCells":0,"note":""}', '[{"to":"/frequency-dominion/app/analytics","label":"Campaign Analytics"},{"to":"/frequency-dominion/app/vault","label":"90-day audit engine"}]', 'courses/frequency-dominion/frequency-dominion-course.zip', 1, strftime('%Y-%m-%dT%H:%M:%SZ','now'), strftime('%Y-%m-%dT%H:%M:%SZ','now'))
       ON CONFLICT(id) DO UPDATE SET module_id=excluded.module_id, code=excluded.code, title=excluded.title, minutes=excluded.minutes, exercise_minutes=excluded.exercise_minutes, position=excluded.position, truth=excluded.truth, masterclass_json=excluded.masterclass_json, field_protocol_json=excluded.field_protocol_json, warnings_json=excluded.warnings_json, decoder_json=excluded.decoder_json, worksheets_json=excluded.worksheets_json, community_json=excluded.community_json, exercise_json=excluded.exercise_json, pass_json=excluded.pass_json, tool_links_json=excluded.tool_links_json, version=lessons.version+1, updated_at=strftime('%Y-%m-%dT%H:%M:%SZ','now');
INSERT INTO lessons (id, module_id, code, title, minutes, exercise_minutes, position, published, truth, masterclass_json, field_protocol_json, warnings_json, decoder_json, worksheets_json, community_json, exercise_json, pass_json, tool_links_json, print_asset, version, created_at, updated_at)
       VALUES ('m6l4', 'm6', '6.4', 'The 90-Day Audit & Ascension Engine — Scale to $1M', 8, 95, 3, 1, 'What gets measured gets dominated. The 90-Day Audit is the executive instrument panel; the Ascension Engine scales a localized radio footprint into a seven-figure independent music enterprise.', '[{"b":"h","level":3,"spans":[{"t":"text","v":"Strategic Foundation & Operational Reality"}]},{"b":"p","spans":[{"t":"text","v":"You have built the identity, the target architecture, the pitch weapons, the 21-day campaign discipline, the human relationship network, and the proof compounding loop. You now possess an operational machine that 99% of musicians and record labels do not understand."}]},{"b":"p","spans":[{"t":"text","v":"The final element of the Frequency Dominion operating system is the "},{"t":"b","v":"Executive Governance Layer"},{"t":"text","v":"."}]},{"b":"p","spans":[{"t":"text","v":"A business that does not audit its performance metrics cannot compound. Every 90 days, at the conclusion of each quarterly campaign cycle, the Dominion operator conducts a clinical, 60-minute "},{"t":"b","v":"90-Day Strategic Audit"},{"t":"text","v":". You analyze the hard data, identify underperforming variables, double down on high-converting market sectors, and scale your independent music enterprise toward sustainable six- and seven-figure operations."}]},{"b":"h","level":3,"spans":[{"t":"text","v":"The 50-Point Quarterly Audit Scorecard"}]},{"b":"p","spans":[{"t":"text","v":"The 90-Day Audit evaluates your performance across five core enterprise dimensions, scored from 1 to 10:"}]},{"b":"list","ordered":true,"items":[{"spans":[{"t":"b","v":"Dimension 1: Momentum & Output (10 Pts Max):"},{"t":"text","v":" Were all planned execution blocks completed? Did you dispatch all 20 War Room targets? Were 100% of Touch 2 and Touch 3 follow-ups executed on schedule?"}]},{"spans":[{"t":"b","v":"Dimension 2: Reach & Cume Expansion (10 Pts Max):"},{"t":"text","v":" How many confirmed station adds were achieved? How many gross weekly broadcast impressions were generated? Did you successfully expand into new geographic rings?"}]},{"spans":[{"t":"b","v":"Dimension 3: Revenue & Monetization (10 Pts Max):"},{"t":"text","v":" What was the gross income attributed across the Six Revenue Lanes? Did live tour guarantees increase? Were PRO and SoundExchange registrations verified?"}]},{"spans":[{"t":"b","v":"Dimension 4: Relational Portfolio Health (10 Pts Max):"},{"t":"text","v":" Were 100% of adds acknowledged with the Thank-You Economy protocol? Did you mail physical cards? How many stations transitioned into the 30/10/10 Ally Engine?"}]},{"spans":[{"t":"b","v":"Dimension 5: Systems & Technical Compliance (10 Pts Max):"},{"t":"text","v":" Did any delivery links break? Were all audio masters compliant with LUFS and True Peak specs? Was your tracking ledger maintained daily without gaps?"}]}]},{"b":"h","level":3,"spans":[{"t":"text","v":"Total Benchmark Targets:"}]},{"b":"list","ordered":false,"items":[{"spans":[{"t":"b","v":"40 – 50 Points:"},{"t":"text","v":" Elite Operator Execution. High compounding momentum. Accelerate budgets and expand regional corridors."}]},{"spans":[{"t":"b","v":"30 – 39 Points:"},{"t":"text","v":" Functional Operation. Minor leaks in follow-up or monetization. Tighten execution discipline."}]},{"spans":[{"t":"b","v":"< 30 Points:"},{"t":"text","v":" System Breakdown. Re-audit Module 1 and Module 4 fundamentals before deploying additional capital."}]}]},{"b":"h","level":3,"spans":[{"t":"text","v":"The Ascension Engine: Scaling to the $1M Enterprise"}]},{"b":"p","spans":[{"t":"text","v":"Once you achieve consistent regional airplay dominance, you ascend through the "},{"t":"b","v":"Three Stages of Independence"},{"t":"text","v":":"}]},{"b":"list","ordered":false,"items":[{"spans":[{"t":"b","v":"Stage 1: The Operator ($25k – $75k Annual):"},{"t":"text","v":" Self-executes the 21-day campaign, sells out regional 200–300 cap rooms, collects initial sync and PRO royalties."}]},{"spans":[{"t":"b","v":"Stage 2: The Syndicate ($100k – $350k Annual):"},{"t":"text","v":" Recruits a dedicated virtual campaign manager or independent radio promoter to run the War Room playbook. Expands tour corridor across 15 markets. Syndicates regular festival appearances."}]},{"spans":[{"t":"b","v":"Stage 3: The Sovereign Enterprise ($500k – $1M+ Annual):"},{"t":"text","v":" Owns 100% of masters and publishing. Operates an automated release and licensing engine. Monetizes direct-to-consumer patron memberships, recurring catalog sync licenses, high-margin touring, and radio-backed regional brand partnerships."}]}]}]', '[{"b":"p","spans":[{"t":"b","v":"WAR-ROOM DIRECTIVE — 6.4 The 90-Day Audit & Ascension Engine — Scale to $1M"}]},{"b":"p","spans":[{"t":"b","v":"THE ANNUAL OPERATING OATH"},{"t":"text","v":" Dominion is not a temporary promotional sprint; it is an enduring standard of professional conduct. You have discarded the mindset of the supplicant artist begging for validation from an uncaring industry. You are an architect of broadcast distribution, a master of relationship compounding, and the sovereign owner of your creative catalog."}]},{"b":"p","spans":[{"t":"b","v":"THE OPERATOR''S FINAL DIRECTIVE:"}]},{"b":"list","ordered":true,"items":[{"spans":[{"t":"text","v":"Execute the system without emotional attachment to immediate outcomes."}]},{"spans":[{"t":"text","v":"Treat every gatekeeper as a professional customer worthy of dignity and respect."}]},{"spans":[{"t":"text","v":"Compound every victory into permanent commercial leverage."}]},{"spans":[{"t":"text","v":"Own the frequency. <!-- WARROOM:END -->"}]}]}]', '["You now possess an operational machine that 99% of musicians and record labels do not understand."]', '["The mechanic: measure, fix weakest, ascend on gates.","The missing piece: the audit is a business review — one kill/keep, one scale/hold, one ascension decision.","The operator move: sign the next-quarter memo with ONE commitment. The artist who fixes one column a quarter beats the artist who revamps everything quarterly — because machines compound on single repairs."]', '[{"kind":"note","blocks":[{"b":"p","spans":[{"t":"text","v":"Complete the structured table below as part of your lesson implementation. This worksheet directly replaces legacy spreadsheets with a publication-grade execution protocol."}]}]},{"kind":"table","title":"90-DAY AUDIT SCORECARD & ASCENSION DASHBOARD","headers":["Evaluation Dimension","Score (1-10)","Quarterly Evidence & Hard Metrics","Operational Deficiency Identified","Next-Quarter Remediation Plan"],"rows":[["1. Momentum & Execution","9 / 10","All 20 stations pitched; 100% touches sent","Slight delay on Touch 2 for Wave 2","Pre-schedule all Touch 2 drafts at launch"],["2. Reach & Station Adds","8 / 10","5 confirmed station adds (25% conversion)","Zero adds in Ring 4 distant corridor","Double down on Ring 1 & Ring 2 college hubs"],["3. Revenue Attribution","7 / 10","$8,400 gross across tickets & sync lead","PRO live performance setlists unlogged","File ASCAP OnStage report for all tour gigs"],["4. Relational Health","9 / 10","100% thank-yous sent; 5 physical cards sent","Failed to get DJ phone numbers","Execute Lesson 5.1 Call Sheets next cycle"],["5. Systems Compliance","10 / 10","Zero link errors, masters 100% compliant","None","Maintain exact audio naming standards"],["OVERALL QUARTERLY SCORE","43 / 50","Elite Operator Tier — Compounding Active","Live concert monetization gap","Scale venue guarantees using radio proof"]]}]', '["Post your final 50-Point 90-Day Audit Scorecard and announce your composite score.","Share your primary commercial revenue milestone for the upcoming 12-month ascension cycle.","Reflect on your transformation from an aspiring artist hoping for airplay into a sovereign Frequency Owner.","Commit to supporting your fellow operators in the private Dominion network."]', '{"kind":"field-exercise","prompt":"Complete every drill below with real, verifiable answers, then confirm the pass standard.","items":[{"id":"d1","label":"The 60-Minute Quarterly Audit Ritual","description":"The 60-Minute Quarterly Audit Ritual . Pull your campaign logs, Spinitron reports, bank statements, and ticketing accounts. Score your performance across all five dimensions using the Scorecard below.","minutes":45,"type":"response","passStandard":null},{"id":"d2","label":"The Single Bottleneck Identification","description":"The Single Bottleneck Identification . Identify the single lowest-scoring dimension on your scorecard. Write an explicit, 3-point remediation directive to correct this bottleneck in the upcoming quarter.","minutes":15,"type":"response","passStandard":null},{"id":"d3","label":"The 90-Day Operating Memo","description":"The 90-Day Operating Memo . Draft a one-page executive memo summarizing: Q1 Hard Results, Key Failures, Q2 Targets, and Next Quarter''s Resource Allocation.","minutes":20,"type":"response","passStandard":null},{"id":"d4","label":"The Ascension Milestone Lock","description":"The Ascension Milestone Lock . Define your primary 12-month commercial revenue milestone (e.g., $100k gross revenue or 50 verified national station adds) and post your commitment in the community archive.","minutes":15,"type":"response","passStandard":null}],"worksheets":[{"kind":"table","title":"90-DAY AUDIT SCORECARD & ASCENSION DASHBOARD","headers":["Evaluation Dimension","Score (1-10)","Quarterly Evidence & Hard Metrics","Operational Deficiency Identified","Next-Quarter Remediation Plan"],"rows":[["1. Momentum & Execution","9 / 10","All 20 stations pitched; 100% touches sent","Slight delay on Touch 2 for Wave 2","Pre-schedule all Touch 2 drafts at launch"],["2. Reach & Station Adds","8 / 10","5 confirmed station adds (25% conversion)","Zero adds in Ring 4 distant corridor","Double down on Ring 1 & Ring 2 college hubs"],["3. Revenue Attribution","7 / 10","$8,400 gross across tickets & sync lead","PRO live performance setlists unlogged","File ASCAP OnStage report for all tour gigs"],["4. Relational Health","9 / 10","100% thank-yous sent; 5 physical cards sent","Failed to get DJ phone numbers","Execute Lesson 5.1 Call Sheets next cycle"],["5. Systems Compliance","10 / 10","Zero link errors, masters 100% compliant","None","Maintain exact audio naming standards"],["OVERALL QUARTERLY SCORE","43 / 50","Elite Operator Tier — Compounding Active","Live concert monetization gap","Scale venue guarantees using radio proof"]]}],"confirmations":[{"id":"community","text":"One community drill answered (optional but strengthens calibration).","required":false}]}', '{"policy":"all-responses-min-words","minWords":40,"requireAllDrills":true,"requireWorksheetCells":0,"note":""}', '[{"to":"/frequency-dominion/app/analytics","label":"Campaign Analytics"},{"to":"/frequency-dominion/app/vault","label":"90-day audit engine"}]', 'courses/frequency-dominion/frequency-dominion-course.zip', 1, strftime('%Y-%m-%dT%H:%M:%SZ','now'), strftime('%Y-%m-%dT%H:%M:%SZ','now'))
       ON CONFLICT(id) DO UPDATE SET module_id=excluded.module_id, code=excluded.code, title=excluded.title, minutes=excluded.minutes, exercise_minutes=excluded.exercise_minutes, position=excluded.position, truth=excluded.truth, masterclass_json=excluded.masterclass_json, field_protocol_json=excluded.field_protocol_json, warnings_json=excluded.warnings_json, decoder_json=excluded.decoder_json, worksheets_json=excluded.worksheets_json, community_json=excluded.community_json, exercise_json=excluded.exercise_json, pass_json=excluded.pass_json, tool_links_json=excluded.tool_links_json, version=lessons.version+1, updated_at=strftime('%Y-%m-%dT%H:%M:%SZ','now');
